window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1CH"]={"book":"1CH","editions":{"fin-biblia1776":[[1,1,"Adam, Set, Enos,","Adam, Set, Enos,"],[1,2,"Kenan, Mahaleel, Jared,","Kenan, Mahaleel, Jared,"],[1,3,"Henok, Metusala, Lamek,","Henok, Metusala, Lamek,"],[1,4,"Noa, Sem, Ham ja Japhet.","Noa, Sem, Ham ja Japhet."],[1,5,"Japhetin lapset: Gomer, Magog, Madai, Javan ja Tubal, Mesek ja Tiras.","Japhetin lapset: Gomer, Magog, Madai, Javan ja Tubal, Mesek ja Tiras."],[1,6,"Gomerin lapset: Askenas, Riphatja, Togarma.","Gomerin lapset: Askenas, Riphatja, Togarma."],[1,7,"Niin myös Javanin lapset: Elisa ja Tarsisa, Kittim ja Dodanim.","Niin myös Javanin lapset: Elisa ja Tarsisa, Kittim ja Dodanim."],[1,8,"Hamin lapset: Kus, Mitsraim, Put ja Kanaan.","Hamin lapset: Kus, Mitsraim, Put ja Kanaan."],[1,9,"Ja Kusin lapset: Seba, Hevila, Sabta, Raema ja Sabteka; ja Raeman lapset: Sjeba ja Dedan.","Ja Kusin lapset: Seba, Hevila, Sabta, Raema ja Sabteka; ja Raeman lapset: Sjeba ja Dedan."],[1,10,"Kus siitti Nimrodin: tämä rupesi olemaan voimallinen maalla.","Kus siitti Nimrodin: tämä rupesi olemaan voimallinen maalla."],[1,11,"Mistraim siitti Ludim, Anamim, Lehabim, Naphutim,","Mistraim siitti Ludim, Anamim, Lehabim, Naphutim,"],[1,12,"Niin myös Patrusim ja Kaluhim, joista Philistealaiset ovat tulleet ja Kaphtorim.","Niin myös Patrusim ja Kaluhim, joista Philistealaiset ovat tulleet ja Kaphtorim."],[1,13,"Kanaan siitti Zidonin esikoisensa ja Hetin,","Kanaan siitti Zidonin esikoisensa ja Hetin,"],[1,14,"Niin myös Jebusin, Amorin ja Gergosin,","Niin myös Jebusin, Amorin ja Gergosin,"],[1,15,"Ja Hevin, Arkin ja Sinin,","Ja Hevin, Arkin ja Sinin,"],[1,16,"Ja Arvadin, Zemarin ja Hematin.","Ja Arvadin, Zemarin ja Hematin."],[1,17,"Semin lapset: Elam, Assur, Arphaksad, Lud ja Aram, Uts, Hul, Geter ja Masek.","Semin lapset: Elam, Assur, Arphaksad, Lud ja Aram, Uts, Hul, Geter ja Masek."],[1,18,"Arphaksad siitti Salan, ja Sala siitti Eberin.","Arphaksad siitti Salan, ja Sala siitti Eberin."],[1,19,"Eberille oli syntynyt kaksi poikaa: yhden nimi oli Peleg, että hänen aikanansa oli maa jaettu, ja hänen veljensä nimi oli Joktan.","Eberille oli syntynyt kaksi poikaa: yhden nimi oli Peleg, että hänen aikanansa oli maa jaettu, ja hänen veljensä nimi oli Joktan."],[1,20,"Joktan siitti Almodadin ja Salephin, Hatsarmavetin ja Jaran,","Joktan siitti Almodadin ja Salephin, Hatsarmavetin ja Jaran,"],[1,21,"Hadoramin, Usalin ja Diklan,","Hadoramin, Usalin ja Diklan,"],[1,22,"Ebalin, Abimaelin ja Sjeban,","Ebalin, Abimaelin ja Sjeban,"],[1,23,"Ophirin, Hevilan ja Jobadin: nämät ovat kaikki Joktanin lapset.","Ophirin, Hevilan ja Jobadin: nämät ovat kaikki Joktanin lapset."],[1,24,"Sem, Arphaksad, Sala,","Sem, Arphaksad, Sala,"],[1,25,"Eber, Peleg, Regu,","Eber, Peleg, Regu,"],[1,26,"Serug, Nahor, Tara,","Serug, Nahor, Tara,"],[1,27,"Abram, se on Abraham.","Abram, se on Abraham."],[1,28,"Abrahamin lapset: Isaak ja Ismael.","Abrahamin lapset: Isaak ja Ismael."],[1,29,"Nämät ovat heidän sukukuntansa: Ismaelin esikoinen Nebajot, Kedar, Adbeel ja Mibsam,","Nämät ovat heidän sukukuntansa: Ismaelin esikoinen Nebajot, Kedar, Adbeel ja Mibsam,"],[1,30,"Misma, Duma, Masa, Hadad ja Tema,","Misma, Duma, Masa, Hadad ja Tema,"],[1,31,"Jetur, Naphis ja Kedma: nämät ovat Ismaelin lapset.","Jetur, Naphis ja Kedma: nämät ovat Ismaelin lapset."],[1,32,"Keturan Abrahamin toisen emännän lapset, jotka hän synnytti: Simran, Joksan, Medan, Midian, Jesbak ja Sua; ja Joksanin lapset: Sjeba ja Dedan.","Keturan Abrahamin toisen emännän lapset, jotka hän synnytti: Simran, Joksan, Medan, Midian, Jesbak ja Sua; ja Joksanin lapset: Sjeba ja Dedan."],[1,33,"Midianin lapset: Epha, Epher, Henok, Abida ja Eldaa. Nämät ovat kaikki Keturan lapset.","Midianin lapset: Epha, Epher, Henok, Abida ja Eldaa. Nämät ovat kaikki Keturan lapset."],[1,34,"Ja Abraham siitti Isaakin. Isaakin lapset olivat Esau ja Israel.","Ja Abraham siitti Isaakin. Isaakin lapset olivat Esau ja Israel."],[1,35,"Esaun lapset: Eliphas, Reguel, Jeus, Jaelam ja Korah.","Esaun lapset: Eliphas, Reguel, Jeus, Jaelam ja Korah."],[1,36,"Eliphan lapset: Teman, Omar, Zephi, Gaetan, Kenas, Timna ja Amalek.","Eliphan lapset: Teman, Omar, Zephi, Gaetan, Kenas, Timna ja Amalek."],[1,37,"Reguelin lapset: Nahat, Sera, Samma ja Missa.","Reguelin lapset: Nahat, Sera, Samma ja Missa."],[1,38,"Seirin lapset: Lotan, Sobal, Sibeon ja Ana, Dison, Etser ja Disan.","Seirin lapset: Lotan, Sobal, Sibeon ja Ana, Dison, Etser ja Disan."],[1,39,"Lotanin lapset: Hori ja Homam; mutta Lotanin sisar oli Timna.","Lotanin lapset: Hori ja Homam; mutta Lotanin sisar oli Timna."],[1,40,"Sobalin lapset: Aljan, Manahat, Ebal, Sephi ja Onam. Sibeonin lapset ovat: Aija ja Ana.","Sobalin lapset: Aljan, Manahat, Ebal, Sephi ja Onam. Sibeonin lapset ovat: Aija ja Ana."],[1,41,"Anan lapset: Dison. Disonin lapset: Hamran, Esban, Jitran ja Karan.","Anan lapset: Dison. Disonin lapset: Hamran, Esban, Jitran ja Karan."],[1,42,"Etserin lapset: Bilhan, Saevan, Jaekan. Disanin lapset: Uts ja Aran.","Etserin lapset: Bilhan, Saevan, Jaekan. Disanin lapset: Uts ja Aran."],[1,43,"Nämät ovat kuninkaat, jotka hallitsivat Edomin maalla, ennenkuin yksikään kuningas hallitsi Israelin lasten seassa: Bela Beorin poika, ja hänen kaupunkinsa nimi oli Dinhaba.","Nämät ovat kuninkaat, jotka hallitsivat Edomin maalla, ennenkuin yksikään kuningas hallitsi Israelin lasten seassa: Bela Beorin poika, ja hänen kaupunkinsa nimi oli Dinhaba."],[1,44,"Ja kuin Bela oli kuollut, tuli Jobab Seran poika Botsrasta kuninkaaksi hänen siaansa.","Ja kuin Bela oli kuollut, tuli Jobab Seran poika Botsrasta kuninkaaksi hänen siaansa."],[1,45,"Kuin Jobab oli kuollut, tuli Husam kuninkaaksi hänen siaansa, Temanilaisten maalta.","Kuin Jobab oli kuollut, tuli Husam kuninkaaksi hänen siaansa, Temanilaisten maalta."],[1,46,"Kuin Husam oli kuollut, tuli hänen siaansa kuninkaaksi Hadad Bedadin poika, joka löi Midianilaiset Moabilaisten kedolla; ja hänen kaupunkinsa nimi oli Avit.","Kuin Husam oli kuollut, tuli hänen siaansa kuninkaaksi Hadad Bedadin poika, joka löi Midianilaiset Moabilaisten kedolla; ja hänen kaupunkinsa nimi oli Avit."],[1,47,"Kuin Hadad oli kuollut, tuli hänen siaansa kuninkaaksi Samla Masrekasta.","Kuin Hadad oli kuollut, tuli hänen siaansa kuninkaaksi Samla Masrekasta."],[1,48,"Kuin Samla oli kuollut, tuli Saul Rehobotin virran tyköä kuninkaaksi hänen siaansa.","Kuin Samla oli kuollut, tuli Saul Rehobotin virran tyköä kuninkaaksi hänen siaansa."],[1,49,"Kuin Saul oli kuollut, tuli Baal Hanan Akborin poika kuninkaaksi hänen siaansa.","Kuin Saul oli kuollut, tuli Baal Hanan Akborin poika kuninkaaksi hänen siaansa."],[1,50,"Kuin Baal Hanan oli kuollut, hallitsi hänen siassansa Hadad; ja hänen kaupunkinsa nimi oli Pagi. Ja hänen emäntänsä nimi oli Mehetabeel, Matredin tytär, Mehasabin tyttären.","Kuin Baal Hanan oli kuollut, hallitsi hänen siassansa Hadad; ja hänen kaupunkinsa nimi oli Pagi. Ja hänen emäntänsä nimi oli Mehetabeel, Matredin tytär, Mehasabin tyttären."],[1,51,"Kuin Hadad oli kuollut, olivat ruhtinaat Edomissa: ruhtinas Timna, ruhtinas Alja, ruhtinas Jetet,","Kuin Hadad oli kuollut, olivat ruhtinaat Edomissa: ruhtinas Timna, ruhtinas Alja, ruhtinas Jetet,"],[1,52,"Ruhtinas Oholibama, ruhtinas Ela, ruhtinas Pinon,","Ruhtinas Oholibama, ruhtinas Ela, ruhtinas Pinon,"],[1,53,"Ruhtinas Kenas, ruhtinas Teman, ruhtinas Mibtsar,","Ruhtinas Kenas, ruhtinas Teman, ruhtinas Mibtsar,"],[1,54,"Ruhtinas Magdiel, ruhtinas Iram: nämät ovat Edomin ruhtinaat.","Ruhtinas Magdiel, ruhtinas Iram: nämät ovat Edomin ruhtinaat."],[2,1,"Nämät ovat Israelin lapset: Ruben, Simeon, Levi ja Juuda, Isaskar ja Sebulon,","Nämät ovat Israelin lapset: Ruben, Simeon, Levi ja Juuda, Isaskar ja Sebulon,"],[2,2,"Dan, Joseph ja Benjamin, Naphtali, Gad ja Asser.","Dan, Joseph ja Benjamin, Naphtali, Gad ja Asser."],[2,3,"Juudan lapset: Ger, Onan, Sela, ne kolme synnytti hänelle Suan tytär Kanaanealainen. Ja Ger Juudan esikoinen oli paha Herran edessä, sentähden tappoi hän hänen.","Juudan lapset: Ger, Onan, Sela, ne kolme synnytti hänelle Suan tytär Kanaanealainen. Ja Ger Juudan esikoinen oli paha Herran edessä, sentähden tappoi hän hänen."],[2,4,"Ja Tamar hänen miniänsä synnytti hänelle Peretsen ja Seran, niin että Juudan lapsia oli kaikkiansa viisi.","Ja Tamar hänen miniänsä synnytti hänelle Peretsen ja Seran, niin että Juudan lapsia oli kaikkiansa viisi."],[2,5,"Peretsen lapset: Hetsron ja Hamul.","Peretsen lapset: Hetsron ja Hamul."],[2,6,"Seran lapset: Simri, Etan, Heman, Kalkol ja Dara: ja heitä kaikkiansa oli myös viisi.","Seran lapset: Simri, Etan, Heman, Kalkol ja Dara: ja heitä kaikkiansa oli myös viisi."],[2,7,"Karmin lapset: Akar, joka Israelin murheelliseksi saatti, ryhtyissänsä kirottuun.","Karmin lapset: Akar, joka Israelin murheelliseksi saatti, ryhtyissänsä kirottuun."],[2,8,"Etanin lapset, Asaria.","Etanin lapset, Asaria."],[2,9,"Hetsronin lapset, jotka hänelle ovat syntyneet: Jerahmeel, Ram ja Kalubai.","Hetsronin lapset, jotka hänelle ovat syntyneet: Jerahmeel, Ram ja Kalubai."],[2,10,"Ram siitti Amminadabin; Amminadab siitti Nahessonin, Juudan lasten päämiehen.","Ram siitti Amminadabin; Amminadab siitti Nahessonin, Juudan lasten päämiehen."],[2,11,"Nahesson siitti Salman; Salma siitti Boaksen.","Nahesson siitti Salman; Salma siitti Boaksen."],[2,12,"Boas siitti Obedin; Obed siitti Isain.","Boas siitti Obedin; Obed siitti Isain."],[2,13,"Isai siitti esikoisensa Eliabin, toisen Abinadabin, kolmannen Simean,","Isai siitti esikoisensa Eliabin, toisen Abinadabin, kolmannen Simean,"],[2,14,"Neljännen Netaneelin, viidennen Raddain,","Neljännen Netaneelin, viidennen Raddain,"],[2,15,"Kuudennen Otsemin ja seitsemännen Davidin.","Kuudennen Otsemin ja seitsemännen Davidin."],[2,16,"Ja heidän sisarensa olivat Seruja ja Abigail. Serujan lapset: Abisai, Joab ja Asael, ne kolme.","Ja heidän sisarensa olivat Seruja ja Abigail. Serujan lapset: Abisai, Joab ja Asael, ne kolme."],[2,17,"Ja Abigail synnytti Amasan; ja Jeter Ismaelilainen oli Amasan isä.","Ja Abigail synnytti Amasan; ja Jeter Ismaelilainen oli Amasan isä."],[2,18,"Kaleb Hetsronin poika siitti emäntäinsä Asuban ja Jerigodin kanssa, nämät ovat hänen lapsensa: Jeser, Sobad ja Ardon.","Kaleb Hetsronin poika siitti emäntäinsä Asuban ja Jerigodin kanssa, nämät ovat hänen lapsensa: Jeser, Sobad ja Ardon."],[2,19,"Ja kuin Asuba kuoli, otti Kaleb itsellensä Ephratin, joka synnytti hänelle Hurin.","Ja kuin Asuba kuoli, otti Kaleb itsellensä Ephratin, joka synnytti hänelle Hurin."],[2,20,"Hur siitti Urin ja Uri siitti Betsaleelin.","Hur siitti Urin ja Uri siitti Betsaleelin."],[2,21,"Sitte meni Hetsron Makirin Gileadin isän tyttären tykö ja nai hänen, kuin hän oli kuudenkymmenen ajastaikainen; ja hän synnytti hänelle Segubin.","Sitte meni Hetsron Makirin Gileadin isän tyttären tykö ja nai hänen, kuin hän oli kuudenkymmenen ajastaikainen; ja hän synnytti hänelle Segubin."],[2,22,"Ja Segub siitti Jairin; ja hänellä oli kolmekolmattakymmentä kaupunkia Gileadin maakunnassa.","Ja Segub siitti Jairin; ja hänellä oli kolmekolmattakymmentä kaupunkia Gileadin maakunnassa."],[2,23,"Mutta Gesur ja Aram saivat heiltä Jairin kylät, Kenatin ja hänen tyttärensä, kuusikymmentä kaupunkia: kaikki nämät ovat Makirin Gileadin isän lapset.","Mutta Gesur ja Aram saivat heiltä Jairin kylät, Kenatin ja hänen tyttärensä, kuusikymmentä kaupunkia: kaikki nämät ovat Makirin Gileadin isän lapset."],[2,24,"Kuin Hetsron oli kuollut Kalebin Ephratassa, niin Hetsronin emäntä Abia synnytti hänelle Assurin Tekoan isän.","Kuin Hetsron oli kuollut Kalebin Ephratassa, niin Hetsronin emäntä Abia synnytti hänelle Assurin Tekoan isän."],[2,25,"Ja Jerahmeelilla Hetsronin esikoisella olivat lapset: hänen esikoisensa Ram, ja Buna, Oren, Otsem ja Ahia.","Ja Jerahmeelilla Hetsronin esikoisella olivat lapset: hänen esikoisensa Ram, ja Buna, Oren, Otsem ja Ahia."],[2,26,"Ja Jerahmeelilla oli vielä toinen emäntä, hänen nimensä oli Atara, hän on Onamin äiti.","Ja Jerahmeelilla oli vielä toinen emäntä, hänen nimensä oli Atara, hän on Onamin äiti."],[2,27,"Ja Ramin Jerahmeelin esikoisen lapset: Maats, Jamin ja Eker.","Ja Ramin Jerahmeelin esikoisen lapset: Maats, Jamin ja Eker."],[2,28,"Ja Onamilla olivat lapset: Samai ja Jada; Samain lapset: Nadab ja Abisur.","Ja Onamilla olivat lapset: Samai ja Jada; Samain lapset: Nadab ja Abisur."],[2,29,"Ja Abisurin emännän nimi oli Abihail, ja hän synnytti hänelle Ahbanin ja Molidin.","Ja Abisurin emännän nimi oli Abihail, ja hän synnytti hänelle Ahbanin ja Molidin."],[2,30,"Nadabin lapset: Seled ja Appaim. Ja Seled kuoli lapsetonna.","Nadabin lapset: Seled ja Appaim. Ja Seled kuoli lapsetonna."],[2,31,"Ja Appaimin lapset: Jisei; ja Jisein lapset: Sesan; Sesanin lapset: Ahlai.","Ja Appaimin lapset: Jisei; ja Jisein lapset: Sesan; Sesanin lapset: Ahlai."],[2,32,"Ja Jodan Sammain veljen lapset: Jeter ja Jonatan. Ja Jeter kuoli lapsetonna.","Ja Jodan Sammain veljen lapset: Jeter ja Jonatan. Ja Jeter kuoli lapsetonna."],[2,33,"Ja Jonatanin lapset: Pelet ja Sasa: nämät ovat Jerahmeelin lapset.","Ja Jonatanin lapset: Pelet ja Sasa: nämät ovat Jerahmeelin lapset."],[2,34,"Sesanilla ei ollut yhtään poikaa, vaan tyttäriä. Ja Sesanilla oli Egyptiläinen palvelia, hänen nimensä oli Jarha.","Sesanilla ei ollut yhtään poikaa, vaan tyttäriä. Ja Sesanilla oli Egyptiläinen palvelia, hänen nimensä oli Jarha."],[2,35,"Ja Sesan antoi Jarhalle palveliallensa tyttärensä emännäksi, hän synnytti hänelle Attain.","Ja Sesan antoi Jarhalle palveliallensa tyttärensä emännäksi, hän synnytti hänelle Attain."],[2,36,"Attai siitti Natanin, Natan siitti Sabadin.","Attai siitti Natanin, Natan siitti Sabadin."],[2,37,"Sabad siitti Ephlalin, Ephlal siitti Obedin.","Sabad siitti Ephlalin, Ephlal siitti Obedin."],[2,38,"Obed siitti Jehun, Jehu siitti Asarian.","Obed siitti Jehun, Jehu siitti Asarian."],[2,39,"Asaria siitti Haletsin, ja Halets siitti Elasan.","Asaria siitti Haletsin, ja Halets siitti Elasan."],[2,40,"Elasa siitti Sismain, ja Sismai siitti Sallumin.","Elasa siitti Sismain, ja Sismai siitti Sallumin."],[2,41,"Sallum siitti Jekamian, ja Jekamia siitti Elisaman.","Sallum siitti Jekamian, ja Jekamia siitti Elisaman."],[2,42,"Kalebin Jerahmeelin veljen lapset: Mesa hänen esikoisensa; hän on Siphin isä: ja Maresan Hebronin isän lapset.","Kalebin Jerahmeelin veljen lapset: Mesa hänen esikoisensa; hän on Siphin isä: ja Maresan Hebronin isän lapset."],[2,43,"Ja Hebronin lapset: Kora, Tappua, Rekem ja Samma.","Ja Hebronin lapset: Kora, Tappua, Rekem ja Samma."],[2,44,"Samma siitti Rahamin Jorkamin isän; ja Rekem siitti Sammain.","Samma siitti Rahamin Jorkamin isän; ja Rekem siitti Sammain."],[2,45,"Ja Sammain poika Maon, ja Maon oli Betsurin isä.","Ja Sammain poika Maon, ja Maon oli Betsurin isä."],[2,46,"Ja Epha Kalebin vaimo synnytti Haranin, Motsan ja Gaseksen; ja Haran siitti Gaseksen.","Ja Epha Kalebin vaimo synnytti Haranin, Motsan ja Gaseksen; ja Haran siitti Gaseksen."],[2,47,"Ja Jahdain lapset: Regem, Jotam, Gesan, Pelet, Epha ja Saaph.","Ja Jahdain lapset: Regem, Jotam, Gesan, Pelet, Epha ja Saaph."],[2,48,"Maeka Kalebin vaimo synnytti Seberin ja Tirhenan.","Maeka Kalebin vaimo synnytti Seberin ja Tirhenan."],[2,49,"Ja hän synnytti myös Saaphin Madmannan isän ja Sjevan Makbenan isän ja Gibean isän. Ja Aksa oli Kalebin tytär.","Ja hän synnytti myös Saaphin Madmannan isän ja Sjevan Makbenan isän ja Gibean isän. Ja Aksa oli Kalebin tytär."],[2,50,"Nämät olivat Kalebin lapset Hurin pojan Ephratan esikoisen: Sobal, Kirjatjearimin isä,","Nämät olivat Kalebin lapset Hurin pojan Ephratan esikoisen: Sobal, Kirjatjearimin isä,"],[2,51,"Salma Betlehemin isä, Hareph Betgaderin isä.","Salma Betlehemin isä, Hareph Betgaderin isä."],[2,52,"Ja Sobalilla Kirjatjearimin isällä oli poikia: Haroe, Hatsimenyhot.","Ja Sobalilla Kirjatjearimin isällä oli poikia: Haroe, Hatsimenyhot."],[2,53,"Ja Kirjatjearimin sukukunnat: Jetriläiset, Putilaiset, Sumatilaiset ja Misrailaiset. Heistä ovat Zorgatilaiset ja Estaolilaiset tulleet.","Ja Kirjatjearimin sukukunnat: Jetriläiset, Putilaiset, Sumatilaiset ja Misrailaiset. Heistä ovat Zorgatilaiset ja Estaolilaiset tulleet."],[2,54,"Salman lapset, Betlehem ja Netophatilaiset, Joabin huoneen kruunut; ja puoli osaa Manatilaisista ovat Zorgilaiset.","Salman lapset, Betlehem ja Netophatilaiset, Joabin huoneen kruunut; ja puoli osaa Manatilaisista ovat Zorgilaiset."],[2,55,"Ja kirjoittajain sukukunnat, jotka asuivat Jabeksessa, ovat Tirgatilaiset, Simealaiset, Sukatilaiset. Nämät ovat Kiniläiset, jotka ovat tulleet Hammatista Rekabin huoneen isästä.","Ja kirjoittajain sukukunnat, jotka asuivat Jabeksessa, ovat Tirgatilaiset, Simealaiset, Sukatilaiset. Nämät ovat Kiniläiset, jotka ovat tulleet Hammatista Rekabin huoneen isästä."],[3,1,"Nämät olivat Davidin pojat, jotka hänelle syntyneet olivat Hebronissa: Amnon esikoinen, joka syntyi Ahinoamista Jisreeliläisestä, toinen Daniel Abigailista Karmelilaisesta.","Nämät olivat Davidin pojat, jotka hänelle syntyneet olivat Hebronissa: Amnon esikoinen, joka syntyi Ahinoamista Jisreeliläisestä, toinen Daniel Abigailista Karmelilaisesta."],[3,2,"Kolmas Absalom Maakan poika Talmain Gessurin kuninkaan tyttären, neljäs Adonia Haggitin poika,","Kolmas Absalom Maakan poika Talmain Gessurin kuninkaan tyttären, neljäs Adonia Haggitin poika,"],[3,3,"Viides Sephatia Abitalista, kuudes Jitream, hänen emännästänsä Eglasta.","Viides Sephatia Abitalista, kuudes Jitream, hänen emännästänsä Eglasta."],[3,4,"Nämät kuusi ovat hänelle syntyneet Hebronissa. Ja hän hallitsi siellä seitsemän vuotta ja kuusi kuukautta; mutta Jerusalemissa hallitsi hän kolmeneljättäkymmentä ajastaikaa.","Nämät kuusi ovat hänelle syntyneet Hebronissa. Ja hän hallitsi siellä seitsemän vuotta ja kuusi kuukautta; mutta Jerusalemissa hallitsi hän kolmeneljättäkymmentä ajastaikaa."],[3,5,"Ja nämät ovat hänelle syntyneet Jerusalemissa: Simea, Sobab, Natan ja Salomo, ne neljä Batsuasta Ammeelin tyttärestä.","Ja nämät ovat hänelle syntyneet Jerusalemissa: Simea, Sobab, Natan ja Salomo, ne neljä Batsuasta Ammeelin tyttärestä."],[3,6,"Sitte Jibhar, Elisama ja Eliphalet,","Sitte Jibhar, Elisama ja Eliphalet,"],[3,7,"Nogah, Nepheg ja Japhia,","Nogah, Nepheg ja Japhia,"],[3,8,"Elisama, Eljada, Eliphelet; ne yhdeksän.","Elisama, Eljada, Eliphelet; ne yhdeksän."],[3,9,"Nämät ovat kaikki Davidin pojat; ilman muiden vaimoin lapsia. Ja Tamar oli heidän sisarensa.","Nämät ovat kaikki Davidin pojat; ilman muiden vaimoin lapsia. Ja Tamar oli heidän sisarensa."],[3,10,"Rehabeam oli Salomon poika, hänen poikansa Abia, hänen poikansa Asa, hänen poikansa Josaphat,","Rehabeam oli Salomon poika, hänen poikansa Abia, hänen poikansa Asa, hänen poikansa Josaphat,"],[3,11,"Hänen poikansa Joram, hänen poikansa Ahasia, hänen poikansa Joas,","Hänen poikansa Joram, hänen poikansa Ahasia, hänen poikansa Joas,"],[3,12,"Hänen poikansa Amasia, hänen poikansa Asaria, hänen poikansa Jotam,","Hänen poikansa Amasia, hänen poikansa Asaria, hänen poikansa Jotam,"],[3,13,"Hänen poikansa Ahas, hänen poikansa Hiskia, hänen poikansa Manasse,","Hänen poikansa Ahas, hänen poikansa Hiskia, hänen poikansa Manasse,"],[3,14,"Hänen poikansa Amon, hänen poikansa Josia.","Hänen poikansa Amon, hänen poikansa Josia."],[3,15,"Mutta Josian pojat olivat: esikoinen Johanan, toinen Jojakim, kolmas Zidkia, neljäs Sallum.","Mutta Josian pojat olivat: esikoinen Johanan, toinen Jojakim, kolmas Zidkia, neljäs Sallum."],[3,16,"Mutta Jojakimin lapset: Jekonia hänen poikansa, Zidkia hänen poikansa.","Mutta Jojakimin lapset: Jekonia hänen poikansa, Zidkia hänen poikansa."],[3,17,"Mutta vangitun Jekonian lapset: hänen poikansa Sealtiel,","Mutta vangitun Jekonian lapset: hänen poikansa Sealtiel,"],[3,18,"(Hänen poikansa) Malkiram, Pedaja, Senatsar, Jekamja, Hosama, Nedabja.","(Hänen poikansa) Malkiram, Pedaja, Senatsar, Jekamja, Hosama, Nedabja."],[3,19,"Pedajan pojat, Zerubbabel ja Simi; Zerubbabelin pojat Mesullam ja Hanania, ja heidän sisarensa Selomit,","Pedajan pojat, Zerubbabel ja Simi; Zerubbabelin pojat Mesullam ja Hanania, ja heidän sisarensa Selomit,"],[3,20,"Hasuba, Ohel, Berekia, Hasadia, Jusabhesed; ne viisi.","Hasuba, Ohel, Berekia, Hasadia, Jusabhesed; ne viisi."],[3,21,"Hananian pojat Pelatja ja Jesaja; Rephajan pojat, Arnanin pojat, Obadian pojat, Sekanian pojat.","Hananian pojat Pelatja ja Jesaja; Rephajan pojat, Arnanin pojat, Obadian pojat, Sekanian pojat."],[3,22,"Mutta Sekanian lapset: Semaja; ja Semajan lapset: Hattus, Jigal, Baria, Nearia, Saphat; ne kuusi.","Mutta Sekanian lapset: Semaja; ja Semajan lapset: Hattus, Jigal, Baria, Nearia, Saphat; ne kuusi."],[3,23,"Nearin lapset: Eljoenai, Hiskia, Asrikam; ne kolme.","Nearin lapset: Eljoenai, Hiskia, Asrikam; ne kolme."],[3,24,"Eljoenain lapset: Hodajeva, Eljasib, Pelaja, Akkub, Johanan, Delaja ja Anani; ne seitsemän.","Eljoenain lapset: Hodajeva, Eljasib, Pelaja, Akkub, Johanan, Delaja ja Anani; ne seitsemän."],[4,1,"Juudan lapset: Perets, Hetsron, Karmi, Hur ja Sobal.","Juudan lapset: Perets, Hetsron, Karmi, Hur ja Sobal."],[4,2,"Mutta Reaja Sobalin poika siitti Jahatin, Jahat siitti Ahumain ja Lahadin: nämät ovat Zorgalaisten sukukunnat.","Mutta Reaja Sobalin poika siitti Jahatin, Jahat siitti Ahumain ja Lahadin: nämät ovat Zorgalaisten sukukunnat."],[4,3,"Ja nämät Etamin isän: Jisreel, Jisma, Jidbas, ja heidän sisarensa nimi oli Hatslelponi.","Ja nämät Etamin isän: Jisreel, Jisma, Jidbas, ja heidän sisarensa nimi oli Hatslelponi."],[4,4,"Ja Penuel Gedorin isä, ja Eser Husan isä: nämät ovat Hurin Betlehemin isän Ephratan esikoisen lapset.","Ja Penuel Gedorin isä, ja Eser Husan isä: nämät ovat Hurin Betlehemin isän Ephratan esikoisen lapset."],[4,5,"Mutta Ashurilla Tekoan isällä oli kaksi emäntää, Helea ja Naera.","Mutta Ashurilla Tekoan isällä oli kaksi emäntää, Helea ja Naera."],[4,6,"Ja Naera synnytti hänelle Ahussamin, Hepherin, Temenin, Ahastarin: nämät ovat Naeran lapset.","Ja Naera synnytti hänelle Ahussamin, Hepherin, Temenin, Ahastarin: nämät ovat Naeran lapset."],[4,7,"Mutta Helean lapset: Zeret, Jesohar ja Etnan.","Mutta Helean lapset: Zeret, Jesohar ja Etnan."],[4,8,"Mutta Kots siitti Anubin ja Hatsobeban, ja Aharhelin Harumin pojan sukukunnat.","Mutta Kots siitti Anubin ja Hatsobeban, ja Aharhelin Harumin pojan sukukunnat."],[4,9,"Mutta Jagbets oli kuuluisampi veljiänsä; ja hänen äitinsä kutsui hänen Jagbets, sillä hän sanoi: minä olen hänen synnyttänyt kivulla.","Mutta Jagbets oli kuuluisampi veljiänsä; ja hänen äitinsä kutsui hänen Jagbets, sillä hän sanoi: minä olen hänen synnyttänyt kivulla."],[4,10,"Ja Jagbets rukoili Israelin Jumalaa ja sanoi: jos sinä minua hyvin siunaisit ja levittäisit minun maani rajat, ja sinun kätes olis minun kanssani, ja asettaisit sitä pahaa, ettei se minua vaivaisi. Ja Jumala antoi tapahtua niinkuin hän rukoili.","Ja Jagbets rukoili Israelin Jumalaa ja sanoi: jos sinä minua hyvin siunaisit ja levittäisit minun maani rajat, ja sinun kätes olis minun kanssani, ja asettaisit sitä pahaa, ettei se minua vaivaisi. Ja Jumala antoi tapahtua niinkuin hän rukoili."],[4,11,"Mutta Kelub Suan veli siitti Mehirin, se on Estonin isä.","Mutta Kelub Suan veli siitti Mehirin, se on Estonin isä."],[4,12,"Mutta Eston siitti Petraphan, Pasean, Tehinnan Irnahaksen isän: nämät ovat Rekan miehet.","Mutta Eston siitti Petraphan, Pasean, Tehinnan Irnahaksen isän: nämät ovat Rekan miehet."],[4,13,"Kenaksen lapset: Otniel ja Seraja; Otnielin lapset: Hatat.","Kenaksen lapset: Otniel ja Seraja; Otnielin lapset: Hatat."],[4,14,"Ja Meonatai siitti Ophran, ja Seraja siitti Joabin seppäin laakson isän, sillä he olivat puusepät.","Ja Meonatai siitti Ophran, ja Seraja siitti Joabin seppäin laakson isän, sillä he olivat puusepät."],[4,15,"Kalebin Jephunnen pojan lapset: Iru, Ela ja Naam; Elan lapset: Kenas.","Kalebin Jephunnen pojan lapset: Iru, Ela ja Naam; Elan lapset: Kenas."],[4,16,"Jehaleelin lapset: Siph, Sipha, Tiria ja Asareel.","Jehaleelin lapset: Siph, Sipha, Tiria ja Asareel."],[4,17,"Esran lapset: Jeter, Mered, Epher ja Jalon; ja hän siitti Mirjamin, Sammain, Jisban, Estemoan isän.","Esran lapset: Jeter, Mered, Epher ja Jalon; ja hän siitti Mirjamin, Sammain, Jisban, Estemoan isän."],[4,18,"Ja hänen Juudalainen emäntänsä synnytti Jeredin Gedorin isän, Heberin Sokon isän, Jekuthelin Sanoan isän: nämät ovat Bitian Pharaon tyttären lapset, jonka Mered otti.","Ja hänen Juudalainen emäntänsä synnytti Jeredin Gedorin isän, Heberin Sokon isän, Jekuthelin Sanoan isän: nämät ovat Bitian Pharaon tyttären lapset, jonka Mered otti."],[4,19,"Hodijan emännän Nahamin Kegilan isän sisaren lapset: Garmi ja Estemoa, Maakatilainen.","Hodijan emännän Nahamin Kegilan isän sisaren lapset: Garmi ja Estemoa, Maakatilainen."],[4,20,"Ja Simonin lapset: Amnon ja Rinna, Benhanan ja Tilon. Jisin lapset: Sohet ja Bensohet.","Ja Simonin lapset: Amnon ja Rinna, Benhanan ja Tilon. Jisin lapset: Sohet ja Bensohet."],[4,21,"Selan Juudan pojan lapset: Erlekan isä, Laeda Maresan isä, ja liinainkutojain suvut Asbean huoneessa,","Selan Juudan pojan lapset: Erlekan isä, Laeda Maresan isä, ja liinainkutojain suvut Asbean huoneessa,"],[4,22,"Niin myös Jokim, ja Koseban miehet, Joas ja Saraph, jotka olivat herrat Moabissa ja Jasubilekemissä: nämät ovat vanhat asiat.","Niin myös Jokim, ja Koseban miehet, Joas ja Saraph, jotka olivat herrat Moabissa ja Jasubilekemissä: nämät ovat vanhat asiat."],[4,23,"He olivat savenvalajat ja asuivat moisioissa ja umpiaidoissa, ja kuninkaan tykönä työnsä tähden, siellä he asuivat.","He olivat savenvalajat ja asuivat moisioissa ja umpiaidoissa, ja kuninkaan tykönä työnsä tähden, siellä he asuivat."],[4,24,"Simeonin lapset: Nemuel ja Jamin, Jarib, Sera, Saul,","Simeonin lapset: Nemuel ja Jamin, Jarib, Sera, Saul,"],[4,25,"Sallum hänen poikansa, Mibsam hänen poikansa, Misma hänen poikansa.","Sallum hänen poikansa, Mibsam hänen poikansa, Misma hänen poikansa."],[4,26,"Misman pojat olivat: Hamuel hänen poikansa, Sakur hänen poikansa, Simei hänen poikansa.","Misman pojat olivat: Hamuel hänen poikansa, Sakur hänen poikansa, Simei hänen poikansa."],[4,27,"Simeillä oli kuusitoistakymmentä poikaa ja kuusi tytärtä, mutta hänen veljillänsä ei ollut monta lasta; sillä kaikki heidän sukukuntansa ei enentynyt niinkuin Juudan lapset.","Simeillä oli kuusitoistakymmentä poikaa ja kuusi tytärtä, mutta hänen veljillänsä ei ollut monta lasta; sillä kaikki heidän sukukuntansa ei enentynyt niinkuin Juudan lapset."],[4,28,"Ja he asuivat Bersebassa, Moladassa ja Hatsarsuasissa,","Ja he asuivat Bersebassa, Moladassa ja Hatsarsuasissa,"],[4,29,"Ja Bilhassa ja Etsemissä ja Toladissa,","Ja Bilhassa ja Etsemissä ja Toladissa,"],[4,30,"Ja Betuelissa ja Hormassa ja Siklagissa,","Ja Betuelissa ja Hormassa ja Siklagissa,"],[4,31,"Ja Betmarkabotissa ja Hatsarsusimissa, BetBirissä ja Saaraimissa. Nämät olivat heidän kaupunkinsa, Davidin hallitukseen asti,","Ja Betmarkabotissa ja Hatsarsusimissa, BetBirissä ja Saaraimissa. Nämät olivat heidän kaupunkinsa, Davidin hallitukseen asti,"],[4,32,"Ja heidän kylänsä, Etam, Ain, Rimmon, Token ja Asan: viisi kaupunkia;","Ja heidän kylänsä, Etam, Ain, Rimmon, Token ja Asan: viisi kaupunkia;"],[4,33,"Ja kaikki ne kylät, jotka olivat niiden kaupunkein ympäristöllä Baaliin asti. Tämä on heidän asumasiansa ja sukukuntansa heidän keskenänsä.","Ja kaikki ne kylät, jotka olivat niiden kaupunkein ympäristöllä Baaliin asti. Tämä on heidän asumasiansa ja sukukuntansa heidän keskenänsä."],[4,34,"Ja Mesobab, Jamlek ja Josat Amatsian poika,","Ja Mesobab, Jamlek ja Josat Amatsian poika,"],[4,35,"Joel ja Jehu Josibian poika, Serajan pojan, Asielin pojan,","Joel ja Jehu Josibian poika, Serajan pojan, Asielin pojan,"],[4,36,"Eljoenai, Jaekoba, Jesohaja, Asaja, Adiel, Jesimiel ja Benaja,","Eljoenai, Jaekoba, Jesohaja, Asaja, Adiel, Jesimiel ja Benaja,"],[4,37,"Ja Sisa Siphin poika, Allonin pojan, Jedajan pojan, Simrin pojan, Semajan pojan:","Ja Sisa Siphin poika, Allonin pojan, Jedajan pojan, Simrin pojan, Semajan pojan:"],[4,38,"Nämät nimitettiin päämiehiksi sukukuntainsa seassa; ja heidän isäinsä huone hajoitti itsensä paljouden tähden.","Nämät nimitettiin päämiehiksi sukukuntainsa seassa; ja heidän isäinsä huone hajoitti itsensä paljouden tähden."],[4,39,"Ja he menivät pois ja tulivat hamaan Gedoriin asti itäiselle puolelle laaksoa, etsimään laidunta lampaillensa.","Ja he menivät pois ja tulivat hamaan Gedoriin asti itäiselle puolelle laaksoa, etsimään laidunta lampaillensa."],[4,40,"Ja he löysivät lihavan ja hyvän laitumen ja maan, joka oli avara ja lavia, rauhallinen ja levollinen; sillä Hamin lapset olivat ennen siellä asuneet.","Ja he löysivät lihavan ja hyvän laitumen ja maan, joka oli avara ja lavia, rauhallinen ja levollinen; sillä Hamin lapset olivat ennen siellä asuneet."],[4,41,"Ja jotka nimenomattain kirjoitetut olivat, tulivat Hiskian Juudan kuninkaan aikaan, ja he löivät muiden majat ja Meonilaiset jotka sieltä löydettiin, ja hävittivät heidät hamaan tähän päivään asti, ja asuivat heidän siallansa; sillä siellä olivat laitumet heidän lampaillensa.","Ja jotka nimenomattain kirjoitetut olivat, tulivat Hiskian Juudan kuninkaan aikaan, ja he löivät muiden majat ja Meonilaiset jotka sieltä löydettiin, ja hävittivät heidät hamaan tähän päivään asti, ja asuivat heidän siallansa; sillä siellä olivat laitumet heidän lampaillensa."],[4,42,"Ja silloin meni heistä liki viisisataa miestä, jotka olivat Simeonin lapsia, Seirin vuorelle; ja Pelatia, Nearia, Rephaja ja Ussiel Jisein lapset olivat heidän päämiehensä,","Ja silloin meni heistä liki viisisataa miestä, jotka olivat Simeonin lapsia, Seirin vuorelle; ja Pelatia, Nearia, Rephaja ja Ussiel Jisein lapset olivat heidän päämiehensä,"],[4,43,"Ja tappoivat päässeet ja jääneet Amalekilaisista, ja asuivat siinä tähän päivään asti.","Ja tappoivat päässeet ja jääneet Amalekilaisista, ja asuivat siinä tähän päivään asti."],[5,1,"Rubenin Israelin esikoisen lapset, sillä hän oli ensimäinen poika; mutta että hän isänsä vuoteen saastutti, annettiin hänen esikoisuutensa Josephin Israelin pojan lapsille, ja ei hän ole polviluvussa luettu esikoiseksi:","Rubenin Israelin esikoisen lapset, sillä hän oli ensimäinen poika; mutta että hän isänsä vuoteen saastutti, annettiin hänen esikoisuutensa Josephin Israelin pojan lapsille, ja ei hän ole polviluvussa luettu esikoiseksi:"],[5,2,"Sillä Juuda oli voimallinen veljeinsä seassa, ja pääruhtinaat ovat hänestä; ja Josephilla on esikoisuus.","Sillä Juuda oli voimallinen veljeinsä seassa, ja pääruhtinaat ovat hänestä; ja Josephilla on esikoisuus."],[5,3,"Niin ovat Rubenin Israelin ensimäisen pojan lapset: Hanok, Pallu, Hetsron ja Karmi.","Niin ovat Rubenin Israelin ensimäisen pojan lapset: Hanok, Pallu, Hetsron ja Karmi."],[5,4,"Ja Joelin lapset: Semaja hänen poikansa, Gog hänen poikansa, Simei hänen poikansa,","Ja Joelin lapset: Semaja hänen poikansa, Gog hänen poikansa, Simei hänen poikansa,"],[5,5,"Hänen poikansa Miika, hänen poikansa Reaja, hänen poikansa Baal,","Hänen poikansa Miika, hänen poikansa Reaja, hänen poikansa Baal,"],[5,6,"Hänen poikansa Beera, jonka Tiglat Pilneser Assyrian kuningas vei vangiksi; hän oli Rubenilaisten pääruhtinas.","Hänen poikansa Beera, jonka Tiglat Pilneser Assyrian kuningas vei vangiksi; hän oli Rubenilaisten pääruhtinas."],[5,7,"Mutta hänen veljensä heidän sukukuntainsa jälkeen, koska he heidän sukukunnissansa polvilukuun luettiin, pitivät he Jeielin ja Sakarian pääruhtinainansa,","Mutta hänen veljensä heidän sukukuntainsa jälkeen, koska he heidän sukukunnissansa polvilukuun luettiin, pitivät he Jeielin ja Sakarian pääruhtinainansa,"],[5,8,"Ja Bela Asaksen poika, Seman pojan, Joelin pojan: hän asui Aroerissa hamaan Neboon ja Baalmeoniin asti;","Ja Bela Asaksen poika, Seman pojan, Joelin pojan: hän asui Aroerissa hamaan Neboon ja Baalmeoniin asti;"],[5,9,"Ja asui itään päin siihenasti kuin tullaan korpeen, Phratin virran tyköä; sillä heidän karjansa oli paljo enentynyt Gileadin maalla.","Ja asui itään päin siihenasti kuin tullaan korpeen, Phratin virran tyköä; sillä heidän karjansa oli paljo enentynyt Gileadin maalla."],[5,10,"Ja Saulin ajalla sotivat he Hagarilaisia vastaan, niin että ne lankesivat heidän kättensä kautta; ja he asuivat heidän majoissansa, kaikessa itäisessä puolessa Gileadin maata.","Ja Saulin ajalla sotivat he Hagarilaisia vastaan, niin että ne lankesivat heidän kättensä kautta; ja he asuivat heidän majoissansa, kaikessa itäisessä puolessa Gileadin maata."],[5,11,"Ja Gadin lapset asuivat juuri heidän kohdallansa Basanin maassa Salkaan asti.","Ja Gadin lapset asuivat juuri heidän kohdallansa Basanin maassa Salkaan asti."],[5,12,"Joel ylimmäinen, Sapham toinen, Jaenai ja Saphat Basanissa.","Joel ylimmäinen, Sapham toinen, Jaenai ja Saphat Basanissa."],[5,13,"Ja heidän veljensä heidän isäinsä huoneen jälkeen, Mikael, Mesullam, Seba, Jorai, Jaekan, Sia ja Eber, seitsemän.","Ja heidän veljensä heidän isäinsä huoneen jälkeen, Mikael, Mesullam, Seba, Jorai, Jaekan, Sia ja Eber, seitsemän."],[5,14,"Nämät ovat Abihailin lapset Hurin pojan, Jaroan pojan, Gileadin pojan, Mikaelin pojan, Jesirain pojan, Jahdon pojan, Busin pojan.","Nämät ovat Abihailin lapset Hurin pojan, Jaroan pojan, Gileadin pojan, Mikaelin pojan, Jesirain pojan, Jahdon pojan, Busin pojan."],[5,15,"Ahi Abdielin poika, Gunin pojan, oli päämies heidän isäinsä huoneessa.","Ahi Abdielin poika, Gunin pojan, oli päämies heidän isäinsä huoneessa."],[5,16,"Ja he asuivat Basanin Gileadissa ja hänen kylissänsä ja kaikissa Saronin esikaupungeissa, hamaan heidän rajoihinsa asti.","Ja he asuivat Basanin Gileadissa ja hänen kylissänsä ja kaikissa Saronin esikaupungeissa, hamaan heidän rajoihinsa asti."],[5,17,"Nämät ovat kaikki luetut polvilukuun Jotamin Juudan kuninkaan ja Jerobeamin Israelin kuninkaan aikana.","Nämät ovat kaikki luetut polvilukuun Jotamin Juudan kuninkaan ja Jerobeamin Israelin kuninkaan aikana."],[5,18,"Rubenin lapset, Gadilaiset ja puoli Manassen sukukuntaa, jotka olivat urhoolliset miehet, jotka kilpeä ja miekkaa kantoivat ja taisivat joutsen jännittää, ja olivat oppineet sotimaan; joita oli neljäviidettäkymmentä tuhatta, seitsemänsataa ja kuusikymmentä, jotka kelpasivat sotaan menemään.","Rubenin lapset, Gadilaiset ja puoli Manassen sukukuntaa, jotka olivat urhoolliset miehet, jotka kilpeä ja miekkaa kantoivat ja taisivat joutsen jännittää, ja olivat oppineet sotimaan; joita oli neljäviidettäkymmentä tuhatta, seitsemänsataa ja kuusikymmentä, jotka kelpasivat sotaan menemään."],[5,19,"Ja kuin he läksivät sotaan Hagarilaisia, Jeturia, Naphesta ja Nodabia vastaan,","Ja kuin he läksivät sotaan Hagarilaisia, Jeturia, Naphesta ja Nodabia vastaan,"],[5,20,"Niin he autettiin niitä vastaan, ja Hagarilaiset annettiin heidän käsiinsä, ja kaikki jotka heidän kanssansa olivat; sillä he huusivat Jumalan tykö sodassa, ja hän kuuli heidän rukouksensa, että he turvasivat häneen.","Niin he autettiin niitä vastaan, ja Hagarilaiset annettiin heidän käsiinsä, ja kaikki jotka heidän kanssansa olivat; sillä he huusivat Jumalan tykö sodassa, ja hän kuuli heidän rukouksensa, että he turvasivat häneen."],[5,21,"Ja he veivät heidän karjansa pois, viisikymmentä tuhatta kamelia, kaksisataa ja viisikymmentä tuhatta lammasta, kaksituhatta aasia, niin myös satatuhatta ihmistä.","Ja he veivät heidän karjansa pois, viisikymmentä tuhatta kamelia, kaksisataa ja viisikymmentä tuhatta lammasta, kaksituhatta aasia, niin myös satatuhatta ihmistä."],[5,22,"Sillä siellä lankesi monta haavoitettuna, että sota oli Jumalalta. Ja he asuivat niiden siassa vankeuteen asti.","Sillä siellä lankesi monta haavoitettuna, että sota oli Jumalalta. Ja he asuivat niiden siassa vankeuteen asti."],[5,23,"Ja puolen Manassen sukukunnan lapset asuivat maassa, Basanissa hamaan Baal Hermoniin ja Seniriin, ja Hermonin vuoreen asti; sillä heitä oli monta.","Ja puolen Manassen sukukunnan lapset asuivat maassa, Basanissa hamaan Baal Hermoniin ja Seniriin, ja Hermonin vuoreen asti; sillä heitä oli monta."],[5,24,"Ja nämät olivat pääruhtinaat heidän isäinsä huoneessa: Epher, Jisei, Eliel, Asriel, Jeremia, Hodavia, Jahdiel, väkevät ja voimalliset miehet ja kuuluisat pääruhtinaat heidän isäinsä huoneessa.","Ja nämät olivat pääruhtinaat heidän isäinsä huoneessa: Epher, Jisei, Eliel, Asriel, Jeremia, Hodavia, Jahdiel, väkevät ja voimalliset miehet ja kuuluisat pääruhtinaat heidän isäinsä huoneessa."],[5,25,"Ja koska he syntiä tekivät isäinsä Jumalaa vastaan, ja tekivät huoruutta niiden kansain epäjumalain kanssa siinä maassa, jotka Jumala oli hävittänyt heidän edestänsä;","Ja koska he syntiä tekivät isäinsä Jumalaa vastaan, ja tekivät huoruutta niiden kansain epäjumalain kanssa siinä maassa, jotka Jumala oli hävittänyt heidän edestänsä;"],[5,26,"Herätti Israelin Jumala Phulin Assyrian kuninkaan hengen, ja Tiglat Pilneserin Assyrian kuninkaan hengen, ja vei Rubenilaiset, Gadilaiset ja puolen Manassen sukukuntaa pois, ja vei heidät Halaan, Haboriin, ja Haraan, ja Gosanin virran tykö, hamaan tähän päivään asti.","Herätti Israelin Jumala Phulin Assyrian kuninkaan hengen, ja Tiglat Pilneserin Assyrian kuninkaan hengen, ja vei Rubenilaiset, Gadilaiset ja puolen Manassen sukukuntaa pois, ja vei heidät Halaan, Haboriin, ja Haraan, ja Gosanin virran tykö, hamaan tähän päivään asti."],[6,1,"Levin lapset: Gerson, Kahat ja Merari.","Levin lapset: Gerson, Kahat ja Merari."],[6,2,"Mutta Kahatin lapset: Amram, Jitsehar, Hebron ja Usiel.","Mutta Kahatin lapset: Amram, Jitsehar, Hebron ja Usiel."],[6,3,"Amramin lapset: Aaron, Moses ja Mirjam; Aaronin lapset: Nadab, Abihu, Eleasar ja Itamar.","Amramin lapset: Aaron, Moses ja Mirjam; Aaronin lapset: Nadab, Abihu, Eleasar ja Itamar."],[6,4,"Eleasar siitti Pinehaan; Pinehas siitti Abisuan.","Eleasar siitti Pinehaan; Pinehas siitti Abisuan."],[6,5,"Abisua siitti Bukkin; Bukki siitti Ussin.","Abisua siitti Bukkin; Bukki siitti Ussin."],[6,6,"Ussi siitti Serajan; Seraja siitti Merajotin.","Ussi siitti Serajan; Seraja siitti Merajotin."],[6,7,"Merajot siitti Amarian; Amaria siitti Ahitobin.","Merajot siitti Amarian; Amaria siitti Ahitobin."],[6,8,"Ahitob siitti Zadokin; Zadok siitti Ahimaatsin.","Ahitob siitti Zadokin; Zadok siitti Ahimaatsin."],[6,9,"Ahimaats siitti Asarian; Asaria siitti Johananin.","Ahimaats siitti Asarian; Asaria siitti Johananin."],[6,10,"Johanan siitti Asarian, joka oli pappi siinä huoneessa, jonka Salomo rakensi Jerusalemissa.","Johanan siitti Asarian, joka oli pappi siinä huoneessa, jonka Salomo rakensi Jerusalemissa."],[6,11,"Asaria siitti Amarian; Amaria siitti Ahitobin.","Asaria siitti Amarian; Amaria siitti Ahitobin."],[6,12,"Ahitob siitti Zadokin; Zadok siitti Sallumin.","Ahitob siitti Zadokin; Zadok siitti Sallumin."],[6,13,"Sallum siitti Hilkian; Hilkia siitti Asarian.","Sallum siitti Hilkian; Hilkia siitti Asarian."],[6,14,"Asaria siitti Serajan; Seraja siitti Jotsadakin.","Asaria siitti Serajan; Seraja siitti Jotsadakin."],[6,15,"Jotsadak myös meni pois, silloin kuin Herra antoi Juudan ja Jerusalemin vietää vankina Nebukadnetsarin kautta.","Jotsadak myös meni pois, silloin kuin Herra antoi Juudan ja Jerusalemin vietää vankina Nebukadnetsarin kautta."],[6,16,"Levin lapset: Gersom, Kahat ja Merari.","Levin lapset: Gersom, Kahat ja Merari."],[6,17,"Ja nämät olivat Gersomin lasten nimet: Libni ja Simei.","Ja nämät olivat Gersomin lasten nimet: Libni ja Simei."],[6,18,"Kahatin lapset: Amram, Jitsehar, Hebron ja Ussiel.","Kahatin lapset: Amram, Jitsehar, Hebron ja Ussiel."],[6,19,"Merarin lapset: Maheli ja Musi. Nämät ovat Leviläisten sukukunnat heidän isäinsä seassa:","Merarin lapset: Maheli ja Musi. Nämät ovat Leviläisten sukukunnat heidän isäinsä seassa:"],[6,20,"Gersomin poika oli Libni, hänen poikansa Jahat, hänen poikansa Simma,","Gersomin poika oli Libni, hänen poikansa Jahat, hänen poikansa Simma,"],[6,21,"Hänen poikansa Joah, hänen poikansa Iddo, hänen poikansa Sera, hänen poikansa Jeatrai.","Hänen poikansa Joah, hänen poikansa Iddo, hänen poikansa Sera, hänen poikansa Jeatrai."],[6,22,"Kahatin lapset: hänen poikansa Amminadab, hänen poikansa Kora, hänen poikansa Assir,","Kahatin lapset: hänen poikansa Amminadab, hänen poikansa Kora, hänen poikansa Assir,"],[6,23,"Hänen poikansa Elkana, hänen poikansa Abiasaph, hänen poikansa Assir,","Hänen poikansa Elkana, hänen poikansa Abiasaph, hänen poikansa Assir,"],[6,24,"Hänen poikansa Tahat, hänen poikansa Uriel, hänen poikansa Ussia, hänen poikansa Saul.","Hänen poikansa Tahat, hänen poikansa Uriel, hänen poikansa Ussia, hänen poikansa Saul."],[6,25,"Elkanan lapset: Amasai ja Ahimot,","Elkanan lapset: Amasai ja Ahimot,"],[6,26,"Elkana, hänen poikansa Elkana, hänen poikansa Sophai, hänen poikansa Nahat,","Elkana, hänen poikansa Elkana, hänen poikansa Sophai, hänen poikansa Nahat,"],[6,27,"Hänen poikansa Eliab, hänen poikansa Jeroham, hänen poikansa Elkana.","Hänen poikansa Eliab, hänen poikansa Jeroham, hänen poikansa Elkana."],[6,28,"Samuelin lapset: hänen esikoisensa Vasni ja Abia.","Samuelin lapset: hänen esikoisensa Vasni ja Abia."],[6,29,"Merarin lapset: Maheli, hänen poikansa Libni, hänen poikansa Simei, hänen poikansa Ussa,","Merarin lapset: Maheli, hänen poikansa Libni, hänen poikansa Simei, hänen poikansa Ussa,"],[6,30,"Hänen poikansa Simea, hänen poikansa Haggia, hänen poikansa Asaja.","Hänen poikansa Simea, hänen poikansa Haggia, hänen poikansa Asaja."],[6,31,"Ja nämät ovat ne, jotka David asetti veisaamaan Herran huoneesen, kuin arkki lepäsi.","Ja nämät ovat ne, jotka David asetti veisaamaan Herran huoneesen, kuin arkki lepäsi."],[6,32,"Ja he palvelivat virsillä seurakunnan majan asuinsian edessä, siihenasti että Salomo rakensi Herran huoneen Jerusalemissa; ja he seisoivat virassansa asetuksensa jälkeen.","Ja he palvelivat virsillä seurakunnan majan asuinsian edessä, siihenasti että Salomo rakensi Herran huoneen Jerusalemissa; ja he seisoivat virassansa asetuksensa jälkeen."],[6,33,"Ja nämät ovat ne, jotka siellä seisoivat, ja heidän lapsensa: Kahatin lapsista, Heman veisaaja, Joelin poika, Samuelin pojan,","Ja nämät ovat ne, jotka siellä seisoivat, ja heidän lapsensa: Kahatin lapsista, Heman veisaaja, Joelin poika, Samuelin pojan,"],[6,34,"Elkanan pojan, Jerohamin pojan, Elielin pojan, Toan pojan,","Elkanan pojan, Jerohamin pojan, Elielin pojan, Toan pojan,"],[6,35,"Zuphin pojan, Elkanan pojan, Mahatin pojan, Amasain pojan,","Zuphin pojan, Elkanan pojan, Mahatin pojan, Amasain pojan,"],[6,36,"Elkanan pojan, Joelin pojan, Asarian pojan, Zephanian pojan,","Elkanan pojan, Joelin pojan, Asarian pojan, Zephanian pojan,"],[6,37,"Tahatin pojan, Assirin pojan, Abiasaphin pojan, Koran pojan,","Tahatin pojan, Assirin pojan, Abiasaphin pojan, Koran pojan,"],[6,38,"Jitseharin pojan, Kahatin pojan, Levin pojan, Israelin pojan.","Jitseharin pojan, Kahatin pojan, Levin pojan, Israelin pojan."],[6,39,"Ja hänen veljensä Assaph seisoi hänen oikialla puolellansa; ja Assaph oli Berekian poika, Simejan pojan,","Ja hänen veljensä Assaph seisoi hänen oikialla puolellansa; ja Assaph oli Berekian poika, Simejan pojan,"],[6,40,"Mikaelin pojan, Baesejan pojan, Malkian pojan,","Mikaelin pojan, Baesejan pojan, Malkian pojan,"],[6,41,"Etnin pojan, Seran pojan, Adajan pojan,","Etnin pojan, Seran pojan, Adajan pojan,"],[6,42,"Etanin pojan, Simman pojan, Simein pojan,","Etanin pojan, Simman pojan, Simein pojan,"],[6,43,"Jahatin pojan, Gersomin pojan, Levin pojan.","Jahatin pojan, Gersomin pojan, Levin pojan."],[6,44,"Mutta heidän veljensä, Merarin lapset, vasemmalla puolella: Etan Kisin poika, Abdin pojan, Mallukin pojan,","Mutta heidän veljensä, Merarin lapset, vasemmalla puolella: Etan Kisin poika, Abdin pojan, Mallukin pojan,"],[6,45,"Hasabian pojan, Amasian pojan, Hilkian pojan,","Hasabian pojan, Amasian pojan, Hilkian pojan,"],[6,46,"Amsin pojan, Banin pojan, Samerin pojan,","Amsin pojan, Banin pojan, Samerin pojan,"],[6,47,"Mahelin pojan, Musin pojan, Merarin pojan, Levin pojan.","Mahelin pojan, Musin pojan, Merarin pojan, Levin pojan."],[6,48,"Ja Leviläiset heidän veljensä olivat annetut kaikkinaisiin virkoihin Jumalan huoneen asuinsiassa.","Ja Leviläiset heidän veljensä olivat annetut kaikkinaisiin virkoihin Jumalan huoneen asuinsiassa."],[6,49,"Ja Aaron ja hänen poikansa olivat sytyttäjät polttouhrin alttarilla ja suitsutusalttarilla kaikkinaisissa töissä siinä kaikkein pyhimmässä, sovittamassa Israelia, juuri niinkuin Moses Jumalan palvelia käskenyt oli.","Ja Aaron ja hänen poikansa olivat sytyttäjät polttouhrin alttarilla ja suitsutusalttarilla kaikkinaisissa töissä siinä kaikkein pyhimmässä, sovittamassa Israelia, juuri niinkuin Moses Jumalan palvelia käskenyt oli."],[6,50,"Nämät ovat Aaronin lapset: Eleasar hänen poikansa, Pinehas hänen poikansa, Abisua hänen poikansa,","Nämät ovat Aaronin lapset: Eleasar hänen poikansa, Pinehas hänen poikansa, Abisua hänen poikansa,"],[6,51,"Bukki hänen poikansa, Ussi hänen poikansa, Seraja hänen poikansa,","Bukki hänen poikansa, Ussi hänen poikansa, Seraja hänen poikansa,"],[6,52,"Merajot hänen poikansa, Amaria hänen poikansa, Ahitob hänen poikansa,","Merajot hänen poikansa, Amaria hänen poikansa, Ahitob hänen poikansa,"],[6,53,"Zadok hänen poikansa, Ahimaats hänen poikansa.","Zadok hänen poikansa, Ahimaats hänen poikansa."],[6,54,"Ja nämät ovat heidän asuinsiansa ja kylänsä heidän rajoissansa: Aaronin lasten Kahatilaisten sukukunnasta: sillä arpa lankesi heille.","Ja nämät ovat heidän asuinsiansa ja kylänsä heidän rajoissansa: Aaronin lasten Kahatilaisten sukukunnasta: sillä arpa lankesi heille."],[6,55,"Ja he antoivat heille Hebronin Juudan maalta ja hänen esikaupunkinsa hänen ympäristöltänsä.","Ja he antoivat heille Hebronin Juudan maalta ja hänen esikaupunkinsa hänen ympäristöltänsä."],[6,56,"Mutta kaupungin pellot ja sen kylät antoivat he Kalebille Jephunnen pojalle.","Mutta kaupungin pellot ja sen kylät antoivat he Kalebille Jephunnen pojalle."],[6,57,"Niin antoivat he Aaronin lapsille vapaat kaupungit, Hebronin ja Libnan esikaupunkeinensa, Jaterin ja Estemoan esikaupunkeinensa,","Niin antoivat he Aaronin lapsille vapaat kaupungit, Hebronin ja Libnan esikaupunkeinensa, Jaterin ja Estemoan esikaupunkeinensa,"],[6,58,"Hilen esikaupunkeinensa, ja Debirin esikaupunkeinensa,","Hilen esikaupunkeinensa, ja Debirin esikaupunkeinensa,"],[6,59,"Asanin esikaupunkeinensa, ja Betsemeksen esikaupunkeinensa;","Asanin esikaupunkeinensa, ja Betsemeksen esikaupunkeinensa;"],[6,60,"Ja BenJaminin sukukunnasta: Geban esikaupunkeinensa, Alemetin esikaupunkeinensa ja Anatotin esikaupunkeinensa. Ja kaikki kaupungit heidän sukukunnissansa olivat kolmetoistakymmentä kaupunkia.","Ja BenJaminin sukukunnasta: Geban esikaupunkeinensa, Alemetin esikaupunkeinensa ja Anatotin esikaupunkeinensa. Ja kaikki kaupungit heidän sukukunnissansa olivat kolmetoistakymmentä kaupunkia."],[6,61,"Mutta ne muut Kahatin lapset heidän suvussansa, siitä puolesta Manassen sukukunnasta, saivat kymmenen kaupunkia arvalla.","Mutta ne muut Kahatin lapset heidän suvussansa, siitä puolesta Manassen sukukunnasta, saivat kymmenen kaupunkia arvalla."],[6,62,"Gersonin lapset heidän sukukuntainsa jälkeen saivat Isaskarin sukukunnalta, Asserin sukukunnalta, Naphtalin sukukunnalta ja Manassen sukukunnalta Basanissa, kolmetoistakymmentä kaupunkia.","Gersonin lapset heidän sukukuntainsa jälkeen saivat Isaskarin sukukunnalta, Asserin sukukunnalta, Naphtalin sukukunnalta ja Manassen sukukunnalta Basanissa, kolmetoistakymmentä kaupunkia."],[6,63,"Ja Merarin lapset heidän sukukuntainsa jälkeen saivat arvalla Rubenin sukukunnalta, Gadin sukukunnalta ja Sebulonin sukukunnalta, kaksitoistakymmentä kaupunkia.","Ja Merarin lapset heidän sukukuntainsa jälkeen saivat arvalla Rubenin sukukunnalta, Gadin sukukunnalta ja Sebulonin sukukunnalta, kaksitoistakymmentä kaupunkia."],[6,64,"Ja Israelin lapset antoivat myös Leviläisille kaupungit esikaupunkeinensa,","Ja Israelin lapset antoivat myös Leviläisille kaupungit esikaupunkeinensa,"],[6,65,"Ja antoivat arvan jälkeen Juudan lasten sukukunnasta, Simeonin lasten sukukunnasta, BenJaminin lasten sukukunnasta, ne kaupungit, jotka he nimittivät.","Ja antoivat arvan jälkeen Juudan lasten sukukunnasta, Simeonin lasten sukukunnasta, BenJaminin lasten sukukunnasta, ne kaupungit, jotka he nimittivät."],[6,66,"Mutta ne, jotka olivat Kahatin lasten suvusta, saivat rajakaupunkinsa Ephraimin sukukunnasta.","Mutta ne, jotka olivat Kahatin lasten suvusta, saivat rajakaupunkinsa Ephraimin sukukunnasta."],[6,67,"Niin antoivat he heille nämät vapaat kaupungit: Sikemin ja sen esikaupungit, Ephraimin vuorelta, niin myös Geserin ja sen esikaupungit,","Niin antoivat he heille nämät vapaat kaupungit: Sikemin ja sen esikaupungit, Ephraimin vuorelta, niin myös Geserin ja sen esikaupungit,"],[6,68,"Jokmeamin ja sen esikaupungit, ja Bethoronin esikaupunkeinensa,","Jokmeamin ja sen esikaupungit, ja Bethoronin esikaupunkeinensa,"],[6,69,"Ajalonin esikaupunkeinensa, ja Gatrimmonin esikaupunkeinensa;","Ajalonin esikaupunkeinensa, ja Gatrimmonin esikaupunkeinensa;"],[6,70,"Niin myös puolesta Manassen sukukunnasta, Anerin esikaupunkeinensa, ja Bileamin esikaupunkeinensa, antoivat he jääneiden Kahatin lasten sukukunnalle,","Niin myös puolesta Manassen sukukunnasta, Anerin esikaupunkeinensa, ja Bileamin esikaupunkeinensa, antoivat he jääneiden Kahatin lasten sukukunnalle,"],[6,71,"Mutta Gersonin lapsille antoivat he puolesta Manassen sukukunnasta, Golanin Basanissa esikaupunkeinensa, ja Astarotin esikaupunkeinensa;","Mutta Gersonin lapsille antoivat he puolesta Manassen sukukunnasta, Golanin Basanissa esikaupunkeinensa, ja Astarotin esikaupunkeinensa;"],[6,72,"Isaskarin sukukunnasta, Kedeksen esikaupunkeinensa, ja Dobratin esikaupunkeinensa,","Isaskarin sukukunnasta, Kedeksen esikaupunkeinensa, ja Dobratin esikaupunkeinensa,"],[6,73,"Ramotin esikaupunkeinensa, ja Anemin esikaupunkeinensa;","Ramotin esikaupunkeinensa, ja Anemin esikaupunkeinensa;"],[6,74,"Asserin sukukunnasta, Masalin esikaupunkeinensa ja Abdonin esikaupunkeinensa,","Asserin sukukunnasta, Masalin esikaupunkeinensa ja Abdonin esikaupunkeinensa,"],[6,75,"Hukokin esikaupunkeinensa, ja Rehobin esikaupunkeinensa;","Hukokin esikaupunkeinensa, ja Rehobin esikaupunkeinensa;"],[6,76,"Naphtalin sukukunnasta, Kedeksen Galileassa esikaupunkeinensa, Hammonin esikaupunkeinensa ja Kirjataimin esikaupunkeinensa.","Naphtalin sukukunnasta, Kedeksen Galileassa esikaupunkeinensa, Hammonin esikaupunkeinensa ja Kirjataimin esikaupunkeinensa."],[6,77,"Muille Merarin lapsille antoivat he Sebulonin sukukunnasta, Rimmonin esikaupunkeinensa, ja Taborin esikaupunkeinensa;","Muille Merarin lapsille antoivat he Sebulonin sukukunnasta, Rimmonin esikaupunkeinensa, ja Taborin esikaupunkeinensa;"],[6,78,"Ja tuolta puolen Jordania Jerihoon päin, itään käsin Jordanin tyköä, Rubenin sukukunnasta, Betserin korvessa esikaupunkeinensa, ja Jahsan esikaupunkeinensa;","Ja tuolta puolen Jordania Jerihoon päin, itään käsin Jordanin tyköä, Rubenin sukukunnasta, Betserin korvessa esikaupunkeinensa, ja Jahsan esikaupunkeinensa;"],[6,79,"Kedemotin esikaupunkeinensa, ja Mephaatin esikaupunkeinensa;","Kedemotin esikaupunkeinensa, ja Mephaatin esikaupunkeinensa;"],[6,80,"Gadin sukukunnasta, Ramotin Gileadissa esikaupunkeinensa, Mahanaimin esikaupunkeinensa,","Gadin sukukunnasta, Ramotin Gileadissa esikaupunkeinensa, Mahanaimin esikaupunkeinensa,"],[6,81,"Ja Hesbonin esikaupunkeinensa, ja Jaeserin esikaupunkeinensa.","Ja Hesbonin esikaupunkeinensa, ja Jaeserin esikaupunkeinensa."],[7,1,"Isaskarin lapset: Tola, Pua, Jasub ja Simron, neljä.","Isaskarin lapset: Tola, Pua, Jasub ja Simron, neljä."],[7,2,"Tolan lapset: Ussi, Rephaja, Jeriel, Jahemai, Jibsam ja Samuel, jotka olivat päämiehet heidän isäinsä huoneessa Tolasta, ja väkevät miehet sukukunnissansa; heidän lukunsa oli Davidin aikana kaksikolmattakymmentä tuhatta ja kuusisataa.","Tolan lapset: Ussi, Rephaja, Jeriel, Jahemai, Jibsam ja Samuel, jotka olivat päämiehet heidän isäinsä huoneessa Tolasta, ja väkevät miehet sukukunnissansa; heidän lukunsa oli Davidin aikana kaksikolmattakymmentä tuhatta ja kuusisataa."],[7,3,"Ussin lapset: Jisraja. Ja Jisrajan lapset: Mikael, Obadia, Joel ja Jesia, viisi, ja olivat kaikki päämiehet.","Ussin lapset: Jisraja. Ja Jisrajan lapset: Mikael, Obadia, Joel ja Jesia, viisi, ja olivat kaikki päämiehet."],[7,4,"Ja heidän kanssansa heidän sukukunnissansa isäinsä huoneessa oli sotajoukko kuusineljättäkymmentä tuhatta; sillä heillä oli monta emäntää ja lasta.","Ja heidän kanssansa heidän sukukunnissansa isäinsä huoneessa oli sotajoukko kuusineljättäkymmentä tuhatta; sillä heillä oli monta emäntää ja lasta."],[7,5,"Ja heidän veljensä, jalot miehet kaikesta Isaskarin sukukunnasta, olivat seitsemänyhdeksättäkymmentä tuhatta, nämät kaikki luettiin polvilukuun.","Ja heidän veljensä, jalot miehet kaikesta Isaskarin sukukunnasta, olivat seitsemänyhdeksättäkymmentä tuhatta, nämät kaikki luettiin polvilukuun."],[7,6,"BenJaminin lapset: Bela, Beker, Jediael, ne kolme.","BenJaminin lapset: Bela, Beker, Jediael, ne kolme."],[7,7,"Belan lapset: Etsbon, Ussi, Ussiel, Jerimot ja Iri, ne viisi, päämiehet heidän isäinsä huoneesta, väkevät miehet, ja heitä luettiin polvilukuun kaksikolmattakymmentä tuhatta ja neljäneljättäkymmentä.","Belan lapset: Etsbon, Ussi, Ussiel, Jerimot ja Iri, ne viisi, päämiehet heidän isäinsä huoneesta, väkevät miehet, ja heitä luettiin polvilukuun kaksikolmattakymmentä tuhatta ja neljäneljättäkymmentä."],[7,8,"Bekerin lapset: Semira, Joas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Alemeth: ne kaikki olivat Bekerin lapset,","Bekerin lapset: Semira, Joas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Alemeth: ne kaikki olivat Bekerin lapset,"],[7,9,"Ja olivat luetut polvilukuun heidän sukukunnastansa, heidän isäinsä huoneen päämiehet, kaksikymmentä tuhatta ja kaksisataa jaloa miestä.","Ja olivat luetut polvilukuun heidän sukukunnastansa, heidän isäinsä huoneen päämiehet, kaksikymmentä tuhatta ja kaksisataa jaloa miestä."],[7,10,"Jediaelin lapset: Bilhan. Bilhanin lapset: Jeus, Benjamin, Ehud, Kenaena, Setan, Tarsis ja Ahisaar.","Jediaelin lapset: Bilhan. Bilhanin lapset: Jeus, Benjamin, Ehud, Kenaena, Setan, Tarsis ja Ahisaar."],[7,11,"Ne olivat kaikki Jediaelin lapset, heidän isäinsä sukukuntain päämiehet, ja väkevät miehet: seitsemäntoistakymmentä tuhatta ja kaksisataa, jotka sotaan läksivät.","Ne olivat kaikki Jediaelin lapset, heidän isäinsä sukukuntain päämiehet, ja väkevät miehet: seitsemäntoistakymmentä tuhatta ja kaksisataa, jotka sotaan läksivät."],[7,12,"Suppim ja Huppim olivat Irin lapset. Mutta Husim Aherin lapset.","Suppim ja Huppim olivat Irin lapset. Mutta Husim Aherin lapset."],[7,13,"Naphtalin lapset: Jahsiel, Guni, Jetser ja Sallum, Bilhan lapset.","Naphtalin lapset: Jahsiel, Guni, Jetser ja Sallum, Bilhan lapset."],[7,14,"Manassen lapset: Esriel, jonka hänen emäntänsä synnytti; mutta hänen Syrialainen jalkavaimonsa synnytti Makirin Gileadin isän.","Manassen lapset: Esriel, jonka hänen emäntänsä synnytti; mutta hänen Syrialainen jalkavaimonsa synnytti Makirin Gileadin isän."],[7,15,"Makir otti Huppimin ja Suppimin tyköä emännän, joka oli molempain sisar, Maeka nimeltä; hänen toisen poikansa nimi oli Zelophkad. Ja Zelophkadilla oli tyttäriä.","Makir otti Huppimin ja Suppimin tyköä emännän, joka oli molempain sisar, Maeka nimeltä; hänen toisen poikansa nimi oli Zelophkad. Ja Zelophkadilla oli tyttäriä."],[7,16,"Ja Maeka Makirin emäntä synnytti pojan, jonka hän kutsui Peres, ja hänen veljensä kutsuttiin Sares, ja hänen poikansa oli Ulam ja Rakem.","Ja Maeka Makirin emäntä synnytti pojan, jonka hän kutsui Peres, ja hänen veljensä kutsuttiin Sares, ja hänen poikansa oli Ulam ja Rakem."],[7,17,"Mutta Bedam oli Ulamin poika. Nämät ovat Gileadin lapset, Makirin pojan Manassen pojan.","Mutta Bedam oli Ulamin poika. Nämät ovat Gileadin lapset, Makirin pojan Manassen pojan."],[7,18,"Ja hänen sisarensa Moleeket synnytti Ishudin, Abieserin ja Mahlan.","Ja hänen sisarensa Moleeket synnytti Ishudin, Abieserin ja Mahlan."],[7,19,"Ja Semidalla olivat nämät lapset: Ahjan, Sikem, Likhi ja Aniam.","Ja Semidalla olivat nämät lapset: Ahjan, Sikem, Likhi ja Aniam."],[7,20,"Nämät ovat Ephraimin lapset: Sutela, ja Bered hänen poikansa, Tahat hänen poikansa, Elada hänen poikansa, Tahat hänen poikansa,","Nämät ovat Ephraimin lapset: Sutela, ja Bered hänen poikansa, Tahat hänen poikansa, Elada hänen poikansa, Tahat hänen poikansa,"],[7,21,"Sabad hänen poikansa, Sutela hänen poikansa, Eser ja Elad. Ja Gatin miehet, siinä maassa syntyneet, löivät heidät kuoliaaksi; sillä he olivat menneet ottamaan heidän karjaansa.","Sabad hänen poikansa, Sutela hänen poikansa, Eser ja Elad. Ja Gatin miehet, siinä maassa syntyneet, löivät heidät kuoliaaksi; sillä he olivat menneet ottamaan heidän karjaansa."],[7,22,"Ja heidän isänsä Ephraim murehti kauvan aikaa; ja hänen veljensä tulivat lohduttamaan häntä.","Ja heidän isänsä Ephraim murehti kauvan aikaa; ja hänen veljensä tulivat lohduttamaan häntä."],[7,23,"Ja hän meni emäntänsä tykö, ja hän siitti ja synnytti pojan, jonka hän kutsui Beria, että hän oli ollut ahdistuksessa huoneessansa.","Ja hän meni emäntänsä tykö, ja hän siitti ja synnytti pojan, jonka hän kutsui Beria, että hän oli ollut ahdistuksessa huoneessansa."],[7,24,"Hänen tyttärensä oli Seera, hän rakensi alimaisen ja ylimäisen Bethoronin ja Ussen Seeran.","Hänen tyttärensä oli Seera, hän rakensi alimaisen ja ylimäisen Bethoronin ja Ussen Seeran."],[7,25,"Hänen poikansa oli Repha ja Reseph, ja Tela hänen poikansa, Tahan hänen poikansa,","Hänen poikansa oli Repha ja Reseph, ja Tela hänen poikansa, Tahan hänen poikansa,"],[7,26,"Ladan hänen poikansa, Ammihud hänen poikansa, Elisama hänen poikansa,","Ladan hänen poikansa, Ammihud hänen poikansa, Elisama hänen poikansa,"],[7,27,"Nun hänen poikansa, Josua hänen poikansa.","Nun hänen poikansa, Josua hänen poikansa."],[7,28,"Ja heidän tavaransa ja asuinsiansa oli Betel, kyläinsä kanssa, ja Naeran itään päin, ja Geser länteen päin kyläinsä kanssa, Sekem kyläinsä kanssa, hamaan Assaan asti kyläinsä kanssa;","Ja heidän tavaransa ja asuinsiansa oli Betel, kyläinsä kanssa, ja Naeran itään päin, ja Geser länteen päin kyläinsä kanssa, Sekem kyläinsä kanssa, hamaan Assaan asti kyläinsä kanssa;"],[7,29,"Ja Manassen lasten poikain tyköä, Betsean kylinensä, Taenak ja hänen kylänsä, Megiddo ja hänen kylänsä. Näissä asuivat Josephin Israelin pojan lapset.","Ja Manassen lasten poikain tyköä, Betsean kylinensä, Taenak ja hänen kylänsä, Megiddo ja hänen kylänsä. Näissä asuivat Josephin Israelin pojan lapset."],[7,30,"Asserin lapset: Jimna, Jisva, Jisvi, Beria ja Sera heidän sisarensa.","Asserin lapset: Jimna, Jisva, Jisvi, Beria ja Sera heidän sisarensa."],[7,31,"Berian lapset olivat: Heber ja Makiel, se on Bersavitin isä.","Berian lapset olivat: Heber ja Makiel, se on Bersavitin isä."],[7,32,"Ja Heber siitti Japhletin, Somerin, Hotamin, ja Suan heidän sisarensa.","Ja Heber siitti Japhletin, Somerin, Hotamin, ja Suan heidän sisarensa."],[7,33,"Japhletin lapset: Pasak, Bimhal ja Asvat: ne olivat Japhletin lapset.","Japhletin lapset: Pasak, Bimhal ja Asvat: ne olivat Japhletin lapset."],[7,34,"Somerin lapset: Ahi, Rahga, Jehubba ja Aram.","Somerin lapset: Ahi, Rahga, Jehubba ja Aram."],[7,35,"Ja hänen veljensä Helemin lapset: Zopha, Jimna, Seles ja Amal.","Ja hänen veljensä Helemin lapset: Zopha, Jimna, Seles ja Amal."],[7,36,"Zophan lapset: Sua, Harnepher, Sual, Beri ja Jimra,","Zophan lapset: Sua, Harnepher, Sual, Beri ja Jimra,"],[7,37,"Betser, Hod, Samma, Silsa, Jitran ja Beera.","Betser, Hod, Samma, Silsa, Jitran ja Beera."],[7,38,"Jeterin lapset: Jephunne, Phispa ja Ara.","Jeterin lapset: Jephunne, Phispa ja Ara."],[7,39,"Ullan lapset: Arah, Hanniel ja Ritsja.","Ullan lapset: Arah, Hanniel ja Ritsja."],[7,40,"Nämät olivat kaikki Asserin lapset, valitut päämiehet heidän isäinsä huoneessa, väkevät miehet ja päämiesten pääruhtinaat, ja luettiin polvittain sotajoukkoon, ja heidän lukunsa oli kuusikolmattakymmentä tuhatta miestä.","Nämät olivat kaikki Asserin lapset, valitut päämiehet heidän isäinsä huoneessa, väkevät miehet ja päämiesten pääruhtinaat, ja luettiin polvittain sotajoukkoon, ja heidän lukunsa oli kuusikolmattakymmentä tuhatta miestä."],[8,1,"Benjamin siitti Belan ensimäisen poikansa, Asbalin toisen, Ahran kolmannen,","Benjamin siitti Belan ensimäisen poikansa, Asbalin toisen, Ahran kolmannen,"],[8,2,"Noan neljännen, Raphan viidennen.","Noan neljännen, Raphan viidennen."],[8,3,"Ja Belalla oli lapsia, Addar, Gera, Abihud,","Ja Belalla oli lapsia, Addar, Gera, Abihud,"],[8,4,"Abisua, Naaman ja Ahoa,","Abisua, Naaman ja Ahoa,"],[8,5,"Gera, Sephupham ja Huram.","Gera, Sephupham ja Huram."],[8,6,"Nämät ovat Ehudin lapset, jotka olivat isäin päämiehet niiden seassa, jotka asuivat Gebassa; ja hän vei heitä Manahatiin,","Nämät ovat Ehudin lapset, jotka olivat isäin päämiehet niiden seassa, jotka asuivat Gebassa; ja hän vei heitä Manahatiin,"],[8,7,"Naaman, Ahia ja Gera, hän vei heidät pois, ja siitti Ussan ja Ahihudin.","Naaman, Ahia ja Gera, hän vei heidät pois, ja siitti Ussan ja Ahihudin."],[8,8,"Ja Saharaim siitti Moabin maalla, sittekuin hän heidät tyköänsä laskenut oli, Husimista ja Baerasta hänen emännistänsä.","Ja Saharaim siitti Moabin maalla, sittekuin hän heidät tyköänsä laskenut oli, Husimista ja Baerasta hänen emännistänsä."],[8,9,"Ja hän siitti emännästänsä Hodesta, Jobabin, Zibian, Mesan ja Malkamin,","Ja hän siitti emännästänsä Hodesta, Jobabin, Zibian, Mesan ja Malkamin,"],[8,10,"Jeusin, Sobjan ja Mirman. Nämät ovat hänen lapsensa, isäin päämiehet.","Jeusin, Sobjan ja Mirman. Nämät ovat hänen lapsensa, isäin päämiehet."],[8,11,"Husimista siitti hän Abitobin ja Elpaalin.","Husimista siitti hän Abitobin ja Elpaalin."],[8,12,"Elpaalin lapset olivat: Eber, Miseam ja Semer: se rakensi Onon ja Lodin, ja hänen kylänsä.","Elpaalin lapset olivat: Eber, Miseam ja Semer: se rakensi Onon ja Lodin, ja hänen kylänsä."],[8,13,"Ja Beria ja Sama olivat isäin päämiehet, niiden, jotka asuivat Ajalonissa: ne ajoivat niitä takaa, jotka asuivat Gatissa.","Ja Beria ja Sama olivat isäin päämiehet, niiden, jotka asuivat Ajalonissa: ne ajoivat niitä takaa, jotka asuivat Gatissa."],[8,14,"Ja Ahio, Sasak ja Jeremot,","Ja Ahio, Sasak ja Jeremot,"],[8,15,"Sebadia, Arad, Ader,","Sebadia, Arad, Ader,"],[8,16,"Mikael, Jispa ja Joha, Berian lapset.","Mikael, Jispa ja Joha, Berian lapset."],[8,17,"Sebadia, Mesullam, Hiski, Heber,","Sebadia, Mesullam, Hiski, Heber,"],[8,18,"Jismerai, Jislia ja Jobab, Elpaanin lapset.","Jismerai, Jislia ja Jobab, Elpaanin lapset."],[8,19,"Jakim, Sikri ja Saddi,","Jakim, Sikri ja Saddi,"],[8,20,"Elienai, Zilletai ja Eliel,","Elienai, Zilletai ja Eliel,"],[8,21,"Adaja, Beraja ja Simrat, Simein lapset.","Adaja, Beraja ja Simrat, Simein lapset."],[8,22,"Jispan, Eber ja Eliel.","Jispan, Eber ja Eliel."],[8,23,"Abdon, Sikri ja Hanan,","Abdon, Sikri ja Hanan,"],[8,24,"Hananja, Elam ja Antotia,","Hananja, Elam ja Antotia,"],[8,25,"Jiphdeja ja Penuel, Sasakin lapset.","Jiphdeja ja Penuel, Sasakin lapset."],[8,26,"Samserai, Seharia ja Atalia,","Samserai, Seharia ja Atalia,"],[8,27,"Jaeresia, Elia ja Sikri, Jerohamin lapset.","Jaeresia, Elia ja Sikri, Jerohamin lapset."],[8,28,"Nämät ovat isäin päämiehet heidän sukukunnissansa; ja he asuivat Jerusalemissa.","Nämät ovat isäin päämiehet heidän sukukunnissansa; ja he asuivat Jerusalemissa."],[8,29,"Mutta Gibeonissa asui Gibeonin isä; ja hänen emäntänsä nimi oli Maeka.","Mutta Gibeonissa asui Gibeonin isä; ja hänen emäntänsä nimi oli Maeka."],[8,30,"Ja hänen ensimäinen poikansa oli Abdon, sitte oli Zur, Kis, Baal ja Nadab,","Ja hänen ensimäinen poikansa oli Abdon, sitte oli Zur, Kis, Baal ja Nadab,"],[8,31,"Gedor, Ahio ja Seker.","Gedor, Ahio ja Seker."],[8,32,"Mutta Miklot siitti Simean; ja he asuivat myös Jerusalemissa veljeinsä kohdalla heidän kanssansa.","Mutta Miklot siitti Simean; ja he asuivat myös Jerusalemissa veljeinsä kohdalla heidän kanssansa."],[8,33,"Ner siitti Kisin; Kis siitti Saulin; Saul siitti Jonatanin, Malkisuan, Abinadabin ja Esbaalin.","Ner siitti Kisin; Kis siitti Saulin; Saul siitti Jonatanin, Malkisuan, Abinadabin ja Esbaalin."],[8,34,"Jonatanin poika oli Meribbaal; Meribbaal siitti Miikan.","Jonatanin poika oli Meribbaal; Meribbaal siitti Miikan."],[8,35,"Miikan lapset olivat: Piton, Melek, Taerea ja Ahas.","Miikan lapset olivat: Piton, Melek, Taerea ja Ahas."],[8,36,"Ahas siitti Joaddan; Joadda siitti Alemetin, Asmavetin ja Simrin; Simri siitti Motsan.","Ahas siitti Joaddan; Joadda siitti Alemetin, Asmavetin ja Simrin; Simri siitti Motsan."],[8,37,"Motsa siitti Binean; hänen poikansa oli Rapha, hänen poikansa Elasa, hänen poikansa Atsel.","Motsa siitti Binean; hänen poikansa oli Rapha, hänen poikansa Elasa, hänen poikansa Atsel."],[8,38,"Mutta Atselilla oli kuusi poikaa, joiden nimet olivat: Esrikam, Bokru, Ismael, Searia, Obadia ja Hanan. Nämät kaikki olivat Atselin pojat.","Mutta Atselilla oli kuusi poikaa, joiden nimet olivat: Esrikam, Bokru, Ismael, Searia, Obadia ja Hanan. Nämät kaikki olivat Atselin pojat."],[8,39,"Esekin hänen veljensä lapset: Ulam hänen ensimäinen poikansa, Jeus toinen, Eliphelet kolmas.","Esekin hänen veljensä lapset: Ulam hänen ensimäinen poikansa, Jeus toinen, Eliphelet kolmas."],[8,40,"Mutta Ulamin lapset olivat vahvat miehet ja jalot joutsimiehet, ja heillä oli paljo poikia ja poikain poikia, sata ja viisikymmentä. Nämät kaikki ovat Benjaminin lapsista.","Mutta Ulamin lapset olivat vahvat miehet ja jalot joutsimiehet, ja heillä oli paljo poikia ja poikain poikia, sata ja viisikymmentä. Nämät kaikki ovat Benjaminin lapsista."],[9,1,"Ja koko Israel luettiin polviluvun jälkeen, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan; ja Juuda vietiin Babeliin pahain tekoinsa tähden.","Ja koko Israel luettiin polviluvun jälkeen, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan; ja Juuda vietiin Babeliin pahain tekoinsa tähden."],[9,2,"Mutta ne ensimäiset asujamet, jotka tulivat perintöönsä ja kaupunkeihinsa, olivat Israel, papit, Leviläiset ja Netinimit.","Mutta ne ensimäiset asujamet, jotka tulivat perintöönsä ja kaupunkeihinsa, olivat Israel, papit, Leviläiset ja Netinimit."],[9,3,"Ja silloin asuivat Jerusalemissa Juudan lapsista, Benjaminin lapsista, ja Ephraimin ja Manassen lapsista:","Ja silloin asuivat Jerusalemissa Juudan lapsista, Benjaminin lapsista, ja Ephraimin ja Manassen lapsista:"],[9,4,"Utal Ammihudin poika, Omrin pojan, Imrin pojan, Banin pojan, Peretsin Juudan pojan lapsista.","Utal Ammihudin poika, Omrin pojan, Imrin pojan, Banin pojan, Peretsin Juudan pojan lapsista."],[9,5,"Mutta Silonilaisista Asaja ensimäinen poika, ja hänen poikansa.","Mutta Silonilaisista Asaja ensimäinen poika, ja hänen poikansa."],[9,6,"Seran lapsista, Jeguel veljinensä; kuusisataa ja yhdeksänkymmentä.","Seran lapsista, Jeguel veljinensä; kuusisataa ja yhdeksänkymmentä."],[9,7,"Benjaminin lapsista, Sallu Mesullamin poika, Hodavian pojan, Hassenuan pojan,","Benjaminin lapsista, Sallu Mesullamin poika, Hodavian pojan, Hassenuan pojan,"],[9,8,"Ja Jibneja Jerohamin poika, ja Ela Ussin poika, Mikrin pojan, ja Mesullam Sephatian poika, Reguelin pojan, Jibnejan pojan;","Ja Jibneja Jerohamin poika, ja Ela Ussin poika, Mikrin pojan, ja Mesullam Sephatian poika, Reguelin pojan, Jibnejan pojan;"],[9,9,"Niin myös heidän veljensä sukukuntainsa jälkeen yhdeksänsataa ja kuusikuudettakymmentä: nämät kaikki ovat olleet isäin päämiehet heidän isäinsä huoneessa.","Niin myös heidän veljensä sukukuntainsa jälkeen yhdeksänsataa ja kuusikuudettakymmentä: nämät kaikki ovat olleet isäin päämiehet heidän isäinsä huoneessa."],[9,10,"Papeista: Jedaja, Jojarib ja Jakin,","Papeista: Jedaja, Jojarib ja Jakin,"],[9,11,"Ja Asaria Hilkian poika, Mesullamin pojan, Zadokin pojan, Merajotin pojan, Ahitobin pojan, Jumalan huoneen päämies,","Ja Asaria Hilkian poika, Mesullamin pojan, Zadokin pojan, Merajotin pojan, Ahitobin pojan, Jumalan huoneen päämies,"],[9,12,"Ja Adaja Jerohamin poika, Pashurin pojan, Malkian pojan, ja myös Maesai Adielin poika, Jahseran pojan, Mesullamin pojan. Mesillemitin pojan, Immerin pojan;","Ja Adaja Jerohamin poika, Pashurin pojan, Malkian pojan, ja myös Maesai Adielin poika, Jahseran pojan, Mesullamin pojan. Mesillemitin pojan, Immerin pojan;"],[9,13,"Niin myös heidän veljeinsä päämiehet isäinsä huoneessa, tuhannen seitsemänsataa ja kuusikymmentä väkevää miestä, toimittamaan viran menoja Jumalan huoneessa.","Niin myös heidän veljeinsä päämiehet isäinsä huoneessa, tuhannen seitsemänsataa ja kuusikymmentä väkevää miestä, toimittamaan viran menoja Jumalan huoneessa."],[9,14,"Mutta Leviläisistä, jotka olivat Merarin lapsia, Semaja Hassubin poika, Asrikamin pojan, Hasabian pojan;","Mutta Leviläisistä, jotka olivat Merarin lapsia, Semaja Hassubin poika, Asrikamin pojan, Hasabian pojan;"],[9,15,"Ja Bakbakkar, Heres, ja Galal, ja Mattania Miikan poika, Sikrin pojan, Asaphin pojan;","Ja Bakbakkar, Heres, ja Galal, ja Mattania Miikan poika, Sikrin pojan, Asaphin pojan;"],[9,16,"Ja Obadia Semajan poika, Galalin pojan, Jedutunin pojan, ja Berekia Asan poika, Elkanan pojan, joka asui Netophatilaisten kylissä.","Ja Obadia Semajan poika, Galalin pojan, Jedutunin pojan, ja Berekia Asan poika, Elkanan pojan, joka asui Netophatilaisten kylissä."],[9,17,"Ja ovenvartiat olivat Sallum, Akkub, Talmon, Ahiman ja heidän veljensä: Sallum oli ylimmäinen.","Ja ovenvartiat olivat Sallum, Akkub, Talmon, Ahiman ja heidän veljensä: Sallum oli ylimmäinen."],[9,18,"Sillä he olivat tähän saakka vartioineet itäisellä puolella kuninkaan porttia: ne olivat ovenvartiat Levin poikain seassa.","Sillä he olivat tähän saakka vartioineet itäisellä puolella kuninkaan porttia: ne olivat ovenvartiat Levin poikain seassa."],[9,19,"Ja Sallum Koren poika Ebjasaphin pojan, Koran pojan ja hänen veljensä hänen isänsä huoneesta, ne Korhilaiset, heidän virkansa menoissa, vartioitsemaan seurakunnan majan ovipieleen; ja heidän isänsä pitää vartioitseman Herran leirissä sisällekäymistä.","Ja Sallum Koren poika Ebjasaphin pojan, Koran pojan ja hänen veljensä hänen isänsä huoneesta, ne Korhilaiset, heidän virkansa menoissa, vartioitsemaan seurakunnan majan ovipieleen; ja heidän isänsä pitää vartioitseman Herran leirissä sisällekäymistä."],[9,20,"Mutta Pinehas Eleasarin poika oli ennen ollut heidän päämiehensä; sillä Herra oli hänen kanssansa.","Mutta Pinehas Eleasarin poika oli ennen ollut heidän päämiehensä; sillä Herra oli hänen kanssansa."],[9,21,"Ja Sakaria Meselemian poika oli vartia seurakunnan majan ovella.","Ja Sakaria Meselemian poika oli vartia seurakunnan majan ovella."],[9,22,"Kaikki nämät olivat valitut ovea vartioitsemaan, kaksisataa ja kaksitoistakymmentä, jotka olivat luetut polviluvun jälkeen heidän kylissänsä. Ja David ja Samuel, näkiä, asettivat heitä virkaan heidän uskollisuudessansa,","Kaikki nämät olivat valitut ovea vartioitsemaan, kaksisataa ja kaksitoistakymmentä, jotka olivat luetut polviluvun jälkeen heidän kylissänsä. Ja David ja Samuel, näkiä, asettivat heitä virkaan heidän uskollisuudessansa,"],[9,23,"Niin että he ja heidän lapsensa ottivat Herran huoneesta vaarin, seurakunnan majan huoneesta, että he sitä vartioitsivat.","Niin että he ja heidän lapsensa ottivat Herran huoneesta vaarin, seurakunnan majan huoneesta, että he sitä vartioitsivat."],[9,24,"Ja ovenvartiat olivat asetetut neljää ilmaa kohden: itään, länteen, pohjaan ja etelään päin.","Ja ovenvartiat olivat asetetut neljää ilmaa kohden: itään, länteen, pohjaan ja etelään päin."],[9,25,"Mutta heidän veljensä olivat maakylissänsä, niin kuitenkin, että heidän piti tuleman sisälle seitsemäntenä päivänä, ja ajasta niin aikaan heidän tykönänsä oleman.","Mutta heidän veljensä olivat maakylissänsä, niin kuitenkin, että heidän piti tuleman sisälle seitsemäntenä päivänä, ja ajasta niin aikaan heidän tykönänsä oleman."],[9,26,"Sillä Leviläiset olivat uskotut olemaan neljäksi ylimmäiseksi ovenvartiaksi; ja he olivat myös kätkyin ja Herran huoneen tavarain päällä.","Sillä Leviläiset olivat uskotut olemaan neljäksi ylimmäiseksi ovenvartiaksi; ja he olivat myös kätkyin ja Herran huoneen tavarain päällä."],[9,27,"Ja he olivat yötä Jumalan huoneen ympärillä; sillä heidän piti sitä vartioitseman, ja avajaman joka aamu.","Ja he olivat yötä Jumalan huoneen ympärillä; sillä heidän piti sitä vartioitseman, ja avajaman joka aamu."],[9,28,"Ja muutamat olivat heistä viran asetten päällä; sillä heidän piti ne kantaman ulos ja sisälle luvun jälkeen.","Ja muutamat olivat heistä viran asetten päällä; sillä heidän piti ne kantaman ulos ja sisälle luvun jälkeen."],[9,29,"Ja muutamat heistä olivat asetetut astiain ja pyhäin kaluin päälle, sämpyläjauhoin, viinan, öljyn, pyhän savun ja myös yrttein päälle.","Ja muutamat heistä olivat asetetut astiain ja pyhäin kaluin päälle, sämpyläjauhoin, viinan, öljyn, pyhän savun ja myös yrttein päälle."],[9,30,"Mutta muutamat pappein lapsista tekivät hyvin valmistettuja voiteita.","Mutta muutamat pappein lapsista tekivät hyvin valmistettuja voiteita."],[9,31,"Ja Mattitjalle Leviläisistä, Sallumin Korhilaisten ensimäiselle pojalle oli uskottu mitä pannuissa valmistettiin.","Ja Mattitjalle Leviläisistä, Sallumin Korhilaisten ensimäiselle pojalle oli uskottu mitä pannuissa valmistettiin."],[9,32,"Ja Kahatilaisista heidän veljistänsä olivat asetetut katsomusleipäin yli, että he niitä valmistaisivat joka sabbattina.","Ja Kahatilaisista heidän veljistänsä olivat asetetut katsomusleipäin yli, että he niitä valmistaisivat joka sabbattina."],[9,33,"Nämät ovat veisaajat, Leviläisten isäin päämiehet vapaat heidän kammioissansa; sillä he olivat siellä askareissansa päivää ja yötä.","Nämät ovat veisaajat, Leviläisten isäin päämiehet vapaat heidän kammioissansa; sillä he olivat siellä askareissansa päivää ja yötä."],[9,34,"Nämät olivat ylimmäiset Leviläisten isät, päämiehet sukukunnissansa; he asuivat Jerusalemissa.","Nämät olivat ylimmäiset Leviläisten isät, päämiehet sukukunnissansa; he asuivat Jerusalemissa."],[9,35,"Jegil Gibeonin isä asui Gibeonissa; hänen emäntänsä nimi oli Maeka,","Jegil Gibeonin isä asui Gibeonissa; hänen emäntänsä nimi oli Maeka,"],[9,36,"Ja hänen ensimäinen poikansa Abdon, Zur, Kis, Baal, Ner ja Nadab,","Ja hänen ensimäinen poikansa Abdon, Zur, Kis, Baal, Ner ja Nadab,"],[9,37,"Gedor, Ahio, Sakaria ja Miklot.","Gedor, Ahio, Sakaria ja Miklot."],[9,38,"Mutta Miklot siitti Simeamin; jotka myös asuivat veljeinsä kohdalla, veljinensä Jerusalemissa.","Mutta Miklot siitti Simeamin; jotka myös asuivat veljeinsä kohdalla, veljinensä Jerusalemissa."],[9,39,"Ja Ner siitti Kisin; Kis siitti Saulin; Saul siitti Jonatanin, Malkisuan, Abinadabin, Esbaalin.","Ja Ner siitti Kisin; Kis siitti Saulin; Saul siitti Jonatanin, Malkisuan, Abinadabin, Esbaalin."],[9,40,"Ja Meribbaal oli Jonatanin poika; ja Meribbaal siitti Miikan.","Ja Meribbaal oli Jonatanin poika; ja Meribbaal siitti Miikan."],[9,41,"Miikan pojat olivat Piton, Melek ja Tahrea.","Miikan pojat olivat Piton, Melek ja Tahrea."],[9,42,"Ahas siitti Jaeran; Jaera siitti Alemetin, Asmavetin ja Simrin; Simri siitti Motsan.","Ahas siitti Jaeran; Jaera siitti Alemetin, Asmavetin ja Simrin; Simri siitti Motsan."],[9,43,"Motsa siitti Binejan; ja Rephaja oli hänen poikansa, Eleasa hänen poikansa, Atsel hänen poikansa.","Motsa siitti Binejan; ja Rephaja oli hänen poikansa, Eleasa hänen poikansa, Atsel hänen poikansa."],[9,44,"Ja Atselilla oli kuusi poikaa, ja nämät olivat heidän nimensä: Asrikam, Bokru, Ismael, Searia, Obadia ja Hanan: ne olivat Atselin pojat.","Ja Atselilla oli kuusi poikaa, ja nämät olivat heidän nimensä: Asrikam, Bokru, Ismael, Searia, Obadia ja Hanan: ne olivat Atselin pojat."],[10,1,"Mutta Philistealaiset sotivat Israelia vastaan; ja Israel pakeni Philistealaisia, ja he lankesivat lyötynä Gilboan vuorella.","Mutta Philistealaiset sotivat Israelia vastaan; ja Israel pakeni Philistealaisia, ja he lankesivat lyötynä Gilboan vuorella."],[10,2,"Ja Philistealaiset kovin ajoivat Saulia ja hänen poikiansa takaa, ja Philistealaiset löivät Jonatanin, Abinadabin ja Malkisuan, Saulin pojat.","Ja Philistealaiset kovin ajoivat Saulia ja hänen poikiansa takaa, ja Philistealaiset löivät Jonatanin, Abinadabin ja Malkisuan, Saulin pojat."],[10,3,"Ja sota oli ankara Saulia vastaan, ja joutsimiehet tulivat hänen päällensä, ja hän haavoitettiin ampujilta.","Ja sota oli ankara Saulia vastaan, ja joutsimiehet tulivat hänen päällensä, ja hän haavoitettiin ampujilta."],[10,4,"Niin sanoi Saul aseensa kantajalle: vedä miekkas ulos ja pistä minut lävitse, ettei nämät ympärileikkaamattomat tulisi ja tekisi häpiällisesti minulle. Mutta hänen aseensa kantaja ei tahtonut; sillä hän pelkäsi suuresti. Niin otti Saul miekan ja heittäysi siihen.","Niin sanoi Saul aseensa kantajalle: vedä miekkas ulos ja pistä minut lävitse, ettei nämät ympärileikkaamattomat tulisi ja tekisi häpiällisesti minulle. Mutta hänen aseensa kantaja ei tahtonut; sillä hän pelkäsi suuresti. Niin otti Saul miekan ja heittäysi siihen."],[10,5,"Kuin hänen aseensa kantaja näki Saulin kuolleeksi, heittäysi myös hän miekkaan ja kuoli.","Kuin hänen aseensa kantaja näki Saulin kuolleeksi, heittäysi myös hän miekkaan ja kuoli."],[10,6,"Ja niin Saul kuoli, ja kolme hänen poikaansa, ja koko hänen huoneensa kuoli yhtä haavaa.","Ja niin Saul kuoli, ja kolme hänen poikaansa, ja koko hänen huoneensa kuoli yhtä haavaa."],[10,7,"Kuin Israelin miehet, jotka laaksossa olivat, näkivät heidän paenneeksi ja Saulin poikinensa kuolleeksi, jättivät he kaupunkinsa ja pakenivat. Ja Philistealaiset tulivat ja asuivat niissä.","Kuin Israelin miehet, jotka laaksossa olivat, näkivät heidän paenneeksi ja Saulin poikinensa kuolleeksi, jättivät he kaupunkinsa ja pakenivat. Ja Philistealaiset tulivat ja asuivat niissä."],[10,8,"Toisena päivänä tulivat Philistealaiset riisumaan lyötyjä, ja he löysivät Saulin poikinensa makaavan Gilboan vuorella.","Toisena päivänä tulivat Philistealaiset riisumaan lyötyjä, ja he löysivät Saulin poikinensa makaavan Gilboan vuorella."],[10,9,"Ja sittekuin he hänen riisuneet olivat, ottivat he hänen päänsä ja aseensa, ja lähettivät Philistealaisten maan ympäri, ja antoivat ilmoittaa epäjumalillensa ja kansalle,","Ja sittekuin he hänen riisuneet olivat, ottivat he hänen päänsä ja aseensa, ja lähettivät Philistealaisten maan ympäri, ja antoivat ilmoittaa epäjumalillensa ja kansalle,"],[10,10,"Ja panivat hänen aseensa jumalansa huoneesen, ja hänen päänsä löivät he kiinni Dagonin huoneen päälle.","Ja panivat hänen aseensa jumalansa huoneesen, ja hänen päänsä löivät he kiinni Dagonin huoneen päälle."],[10,11,"Kuin kaikki Gileadin Jabeksessa kuulivat kaikki, mitä Philistealaiset Saulille tehneet olivat,","Kuin kaikki Gileadin Jabeksessa kuulivat kaikki, mitä Philistealaiset Saulille tehneet olivat,"],[10,12,"Nousivat kaikki väkevät miehet ja ottivat Saulin ja hänen poikansa ruumiit, ja veivät ne Jabekseen, ja hautasivat heidän luunsa tammen alle Jabeksessa, ja paastosivat seitsemän päivää.","Nousivat kaikki väkevät miehet ja ottivat Saulin ja hänen poikansa ruumiit, ja veivät ne Jabekseen, ja hautasivat heidän luunsa tammen alle Jabeksessa, ja paastosivat seitsemän päivää."],[10,13,"Ja niin kuoli Saul pahoissa teoissansa, joita hän Herraa vastaan tehnyt oli, ettei hän pitänyt Herran sanaa, ja että hän myös etsi velhovaimoa kysyäksensä häneltä,","Ja niin kuoli Saul pahoissa teoissansa, joita hän Herraa vastaan tehnyt oli, ettei hän pitänyt Herran sanaa, ja että hän myös etsi velhovaimoa kysyäksensä häneltä,"],[10,14,"Ja ei kysynyt Herralta; sentähden tappoi hän hänen, ja käänsi valtakunnan Davidille Isain pojalle.","Ja ei kysynyt Herralta; sentähden tappoi hän hänen, ja käänsi valtakunnan Davidille Isain pojalle."],[11,1,"Ja koko Israel kokoontui Davidin tykö Hebroniin ja sanoi: katso, me olemme sinun luus ja lihas.","Ja koko Israel kokoontui Davidin tykö Hebroniin ja sanoi: katso, me olemme sinun luus ja lihas."],[11,2,"Ja aina ennenkin, Saulin ollessa kuninkaana, johdatit sinä Israelin ulos ja sisälle. Ja Herra sinun Jumalas on sanonut sinulle: sinun pitää kaitseman kansaani Israelia ja sinun pitää oleman kansani Israelin päämiehen.","Ja aina ennenkin, Saulin ollessa kuninkaana, johdatit sinä Israelin ulos ja sisälle. Ja Herra sinun Jumalas on sanonut sinulle: sinun pitää kaitseman kansaani Israelia ja sinun pitää oleman kansani Israelin päämiehen."],[11,3,"Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja David teki liiton heidän kanssansa Herran edessä Hebronissa. Ja he voitelivat Davidin Israelin kuninkaaksi Herran sanan jälkeen Samuelin kautta.","Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja David teki liiton heidän kanssansa Herran edessä Hebronissa. Ja he voitelivat Davidin Israelin kuninkaaksi Herran sanan jälkeen Samuelin kautta."],[11,4,"Sitten meni David ja koko Israel Jerusalemiin, se on Jebus; sillä Jebusilaiset asuivat siinä maassa.","Sitten meni David ja koko Israel Jerusalemiin, se on Jebus; sillä Jebusilaiset asuivat siinä maassa."],[11,5,"Ja Jebuksen asuvaiset sanoivat Davidille: sinun ei pidä tuleman tänne; mutta David voitti Zionin linnan, se on Davidin kaupunki.","Ja Jebuksen asuvaiset sanoivat Davidille: sinun ei pidä tuleman tänne; mutta David voitti Zionin linnan, se on Davidin kaupunki."],[11,6,"Ja David sanoi: joka Jebusilaiset ensin lyö, hänen pitää oleman pään ja ylimmäisen. Niin Joab Zerujan poika astui ensin ylös ja tuli päämieheksi.","Ja David sanoi: joka Jebusilaiset ensin lyö, hänen pitää oleman pään ja ylimmäisen. Niin Joab Zerujan poika astui ensin ylös ja tuli päämieheksi."],[11,7,"Ja David asui linnassa; sentähden kutsuivat he sen Davidin kaupungiksi.","Ja David asui linnassa; sentähden kutsuivat he sen Davidin kaupungiksi."],[11,8,"Ja hän rakensi kaupungin ympäri Millosta ja sitte kaiken ympäri. Ja Joab jätti ne elämään, jotka jääneet olivat kaupunkiin.","Ja hän rakensi kaupungin ympäri Millosta ja sitte kaiken ympäri. Ja Joab jätti ne elämään, jotka jääneet olivat kaupunkiin."],[11,9,"Ja niin David menestyi ja tuli väkeväksi, ja Herra Zebaot oli hänen kanssansa.","Ja niin David menestyi ja tuli väkeväksi, ja Herra Zebaot oli hänen kanssansa."],[11,10,"Nämät ovat ylimmäiset Davidin väkevimpäin seassa, jotka miehuullisesti hänen kanssansa pitivät hänen valtakunnassansa koko Israelin tykönä, niin että hän tehtiin kuninkaaksi Herran sanan jälkeen Israelin ylitse.","Nämät ovat ylimmäiset Davidin väkevimpäin seassa, jotka miehuullisesti hänen kanssansa pitivät hänen valtakunnassansa koko Israelin tykönä, niin että hän tehtiin kuninkaaksi Herran sanan jälkeen Israelin ylitse."],[11,11,"Ja tämä on Davidin sankarien luku: Jasobeam Hakmonin poika ylimmäinen päämiesten seassa. Hän nosti keihäänsä ja löi kerralla kolmesataa.","Ja tämä on Davidin sankarien luku: Jasobeam Hakmonin poika ylimmäinen päämiesten seassa. Hän nosti keihäänsä ja löi kerralla kolmesataa."],[11,12,"Hänen jälkeensä oli Eleasar, Dodon Ahohilaisen poika, hän oli kolmen sankarin seassa.","Hänen jälkeensä oli Eleasar, Dodon Ahohilaisen poika, hän oli kolmen sankarin seassa."],[11,13,"Tämä oli Davidin kanssa Pasdammimissa, kuin Philistealaiset olivat kokoontuneet sinne sotaan. Ja oli kappale peltoa ohraa täynnä, ja kansa pakeni Philistealaisia.","Tämä oli Davidin kanssa Pasdammimissa, kuin Philistealaiset olivat kokoontuneet sinne sotaan. Ja oli kappale peltoa ohraa täynnä, ja kansa pakeni Philistealaisia."],[11,14,"Ja he astuivat keskelle peltoa, ja varjelivat sen, ja löivät Philistealaiset. Ja Herra antoi heille suuren autuuden.","Ja he astuivat keskelle peltoa, ja varjelivat sen, ja löivät Philistealaiset. Ja Herra antoi heille suuren autuuden."],[11,15,"Ja kolme niistä kolmestakymmenestä ylimmäisestä tulivat kalliolle alas Davidin tykö Adullamin luolaan. Mutta Philistealaisten leiri oli Rephaimin laaksossa.","Ja kolme niistä kolmestakymmenestä ylimmäisestä tulivat kalliolle alas Davidin tykö Adullamin luolaan. Mutta Philistealaisten leiri oli Rephaimin laaksossa."],[11,16,"Ja David oli silloin linnassa; ja Philistealaisten kansa oli silloin Betlehemissä.","Ja David oli silloin linnassa; ja Philistealaisten kansa oli silloin Betlehemissä."],[11,17,"Ja David himoitsi ja sanoi: kuka antais minun juoda sitä vettä, joka on kaivossa Betlehemin portin tykönä?","Ja David himoitsi ja sanoi: kuka antais minun juoda sitä vettä, joka on kaivossa Betlehemin portin tykönä?"],[11,18,"Niin ne kolme juoksivat Philistealaisten leiriin, ja ammunsivat vettä kaivosta Betlehemin portin tyköä, ottivat ja kantoivat Davidille; mutta ei David tahtonut sitä juoda, vaan kaasi sen Herran eteen,","Niin ne kolme juoksivat Philistealaisten leiriin, ja ammunsivat vettä kaivosta Betlehemin portin tyköä, ottivat ja kantoivat Davidille; mutta ei David tahtonut sitä juoda, vaan kaasi sen Herran eteen,"],[11,19,"Ja sanoi: Jumala antakoon sen kaukana olla minusta, että minä tämän tekisin! pitäiskö minun juoman näiden miesten verta heidän henkensä vaarassa? sillä he ovat sen tuoneet henkensä vaaralla; sentähden ei hän tahtonut sitä juoda. Sen tekivät ne kolme sankaria.","Ja sanoi: Jumala antakoon sen kaukana olla minusta, että minä tämän tekisin! pitäiskö minun juoman näiden miesten verta heidän henkensä vaarassa? sillä he ovat sen tuoneet henkensä vaaralla; sentähden ei hän tahtonut sitä juoda. Sen tekivät ne kolme sankaria."],[11,20,"Abisai Joabin veli, hän oli ylimmäinen kolmesta, ja hän nosti keihäänsä ja löi kolmesataa, ja hän ylistettiin niiden kolmen seassa.","Abisai Joabin veli, hän oli ylimmäinen kolmesta, ja hän nosti keihäänsä ja löi kolmesataa, ja hän ylistettiin niiden kolmen seassa."],[11,21,"Ja hän oli kolmen seassa kuuluisampi kahta ja oli heidän päämiehensä; mutta kolmen tykö ei hän tullut.","Ja hän oli kolmen seassa kuuluisampi kahta ja oli heidän päämiehensä; mutta kolmen tykö ei hän tullut."],[11,22,"Benaja Jojadan poika väkevän miehen poika, joka suuria töitä tehnyt oli, Kabtseelista: hän löi kaksi Moabilaisten jalopeuraa; ja hän meni alas ja löi jalopeuran keskellä kaivoa lumen aikana.","Benaja Jojadan poika väkevän miehen poika, joka suuria töitä tehnyt oli, Kabtseelista: hän löi kaksi Moabilaisten jalopeuraa; ja hän meni alas ja löi jalopeuran keskellä kaivoa lumen aikana."],[11,23,"Hän löi myös Egyptin miehen, joka oli viisi kyynärää pitkä, ja Egyptiläisen kädessä oli keihäs niinkuin kankaan puu, mutta hän meni alas hänen tykönsä sauvalla, tempasi keihään Egyptiläisen kädestä ja tappoi hänen omalla keihäällänsä.","Hän löi myös Egyptin miehen, joka oli viisi kyynärää pitkä, ja Egyptiläisen kädessä oli keihäs niinkuin kankaan puu, mutta hän meni alas hänen tykönsä sauvalla, tempasi keihään Egyptiläisen kädestä ja tappoi hänen omalla keihäällänsä."],[11,24,"Näitä teki Benaja Jojadan poika; ja hän ylistettiin kolmen uljasten seassa,","Näitä teki Benaja Jojadan poika; ja hän ylistettiin kolmen uljasten seassa,"],[11,25,"Ja oli kuuluisampi niitä kolmeakymmentä; mutta kolmen tykö ei hän tullut. Ja David teki hänen salaiseksi neuvonantajaksensa.","Ja oli kuuluisampi niitä kolmeakymmentä; mutta kolmen tykö ei hän tullut. Ja David teki hänen salaiseksi neuvonantajaksensa."],[11,26,"Niin myös sotasankarit: Asahel Joabin veli, Elhanan Dodonin poika Betlehemistä,","Niin myös sotasankarit: Asahel Joabin veli, Elhanan Dodonin poika Betlehemistä,"],[11,27,"Samot Harorilainen, Heles Pelonilainen,","Samot Harorilainen, Heles Pelonilainen,"],[11,28,"Ira Ikeksen Tekoalaisen poika, Abieser Antotilainen.","Ira Ikeksen Tekoalaisen poika, Abieser Antotilainen."],[11,29,"Sibbekai Husatilainen, Ilai Ahohilainen,","Sibbekai Husatilainen, Ilai Ahohilainen,"],[11,30,"Maherai Netophatilainen, Heled Baenan Netophatilaisen poika,","Maherai Netophatilainen, Heled Baenan Netophatilaisen poika,"],[11,31,"Ittai Ribain poika Gibeasta, BenJaminin lapsista, Benaja Pirtagonilainen,","Ittai Ribain poika Gibeasta, BenJaminin lapsista, Benaja Pirtagonilainen,"],[11,32,"Hurai Gasin pojista, Abiel Arbatilainen,","Hurai Gasin pojista, Abiel Arbatilainen,"],[11,33,"Asmavet Baharumilainen, Eliahba Saalbonilainen;","Asmavet Baharumilainen, Eliahba Saalbonilainen;"],[11,34,"Hasemin Gisonilaisen lapset: Jonatan Sagen Hararilaisen poika,","Hasemin Gisonilaisen lapset: Jonatan Sagen Hararilaisen poika,"],[11,35,"Ahiam Sakarin Hararilaisen poika, Eliphal Urin poika,","Ahiam Sakarin Hararilaisen poika, Eliphal Urin poika,"],[11,36,"Hepher Makeratilainen, Ahia Pelonilainen,","Hepher Makeratilainen, Ahia Pelonilainen,"],[11,37,"Hetsro Karmelilainen, Naerai Asbain poika,","Hetsro Karmelilainen, Naerai Asbain poika,"],[11,38,"Joel Natanin veli, Mibhar Hagrin poika,","Joel Natanin veli, Mibhar Hagrin poika,"],[11,39,"Zelek Ammonilainen, Naherai Berotilainen, Joabin Zerujan pojan aseenkantaja,","Zelek Ammonilainen, Naherai Berotilainen, Joabin Zerujan pojan aseenkantaja,"],[11,40,"Ira Jetriläinen, Gareb Jetriläinen,","Ira Jetriläinen, Gareb Jetriläinen,"],[11,41,"Uria Hetiläinen, Sabad Ahelain poika,","Uria Hetiläinen, Sabad Ahelain poika,"],[11,42,"Adina Sisan Rubenilaisen poika, Rubenilaisten päämies, ja kolmekymmentä oli hänen kanssansa;","Adina Sisan Rubenilaisen poika, Rubenilaisten päämies, ja kolmekymmentä oli hänen kanssansa;"],[11,43,"Hanan Maekan poika, Josaphat Mitniläinen,","Hanan Maekan poika, Josaphat Mitniläinen,"],[11,44,"Ussia Asteratilainen, Sama ja Jeiel Hotamin Aroerilaisen pojat,","Ussia Asteratilainen, Sama ja Jeiel Hotamin Aroerilaisen pojat,"],[11,45,"Jediael Simrin poika, Joha hänen veljensä, Titsiläinen,","Jediael Simrin poika, Joha hänen veljensä, Titsiläinen,"],[11,46,"Eliel Maheavilainen, Jeribai ja Josavia Elnaamin pojat, Itma Moabilainen,","Eliel Maheavilainen, Jeribai ja Josavia Elnaamin pojat, Itma Moabilainen,"],[11,47,"Eliel, Obed ja Jaesiel Mesobajasta.","Eliel, Obed ja Jaesiel Mesobajasta."],[12,1,"Nämät tulivat Davidin tykö Ziklagiin, kuin hän vielä oli suljettu Saulin Kisin pojan edestä; ja he olivat myös sankarein seassa, jotka sotaan auttivat,","Nämät tulivat Davidin tykö Ziklagiin, kuin hän vielä oli suljettu Saulin Kisin pojan edestä; ja he olivat myös sankarein seassa, jotka sotaan auttivat,"],[12,2,"Ja olivat soveliaat ampujat joutsella molemmin käsin, kivillä, nuolilla ja joutsilla: Saulin veljistä, BenJaminista:","Ja olivat soveliaat ampujat joutsella molemmin käsin, kivillä, nuolilla ja joutsilla: Saulin veljistä, BenJaminista:"],[12,3,"Ahieser päämies ja Joas, Semajan Gibealaisen pojat, Jesiel ja Pelet Asmavetin pojat, Baraka ja Jehu Antonilainen,","Ahieser päämies ja Joas, Semajan Gibealaisen pojat, Jesiel ja Pelet Asmavetin pojat, Baraka ja Jehu Antonilainen,"],[12,4,"Jesmaja Gibeonilainen, väkevä kolmenkymmenen seassa ja ylitse kolmenkymmenen, Jeremia, Jahesiel, Johanan ja Josabad Gederalainen,","Jesmaja Gibeonilainen, väkevä kolmenkymmenen seassa ja ylitse kolmenkymmenen, Jeremia, Jahesiel, Johanan ja Josabad Gederalainen,"],[12,5,"Elusai, Jerimot, Bealia, Semaria ja Saphatia Harophilainen,","Elusai, Jerimot, Bealia, Semaria ja Saphatia Harophilainen,"],[12,6,"Elkana, Jesija, Asareel, Joeser ja Jasobeam Korhilainen,","Elkana, Jesija, Asareel, Joeser ja Jasobeam Korhilainen,"],[12,7,"Joela ja Sedadia Jerohamin lapset Gedorista.","Joela ja Sedadia Jerohamin lapset Gedorista."],[12,8,"Gadilaisista eroittivat heitänsä Davidin tykö linnaan korvessa väkevät sankarit ja sotamiehet, jotka kilpeä ja keihästä kantoivat; ja heidän kasvonsa olivat niinkuin jalopeuran kasvot, ja nopiat niinkuin metsävuohet vuorilla:","Gadilaisista eroittivat heitänsä Davidin tykö linnaan korvessa väkevät sankarit ja sotamiehet, jotka kilpeä ja keihästä kantoivat; ja heidän kasvonsa olivat niinkuin jalopeuran kasvot, ja nopiat niinkuin metsävuohet vuorilla:"],[12,9,"Ensimäinen Eser, toinen Obadia, kolmas Eliab,","Ensimäinen Eser, toinen Obadia, kolmas Eliab,"],[12,10,"Neljäs Mismanna, viides Jeremia,","Neljäs Mismanna, viides Jeremia,"],[12,11,"Kuudes Attai, seitsemäs Eliel,","Kuudes Attai, seitsemäs Eliel,"],[12,12,"Kahdeksas Johanan, ykdeksäs Elsabad,","Kahdeksas Johanan, ykdeksäs Elsabad,"],[12,13,"Kymmenes Jeremia, yksitoistakymmenes Mahbanai.","Kymmenes Jeremia, yksitoistakymmenes Mahbanai."],[12,14,"Nämät olivat Gadin lapsista sodan päämiehet: vähin sadan päälle ja suurin tuhannen päälle.","Nämät olivat Gadin lapsista sodan päämiehet: vähin sadan päälle ja suurin tuhannen päälle."],[12,15,"Nämät ovat ne jotka menivät Jordanin ylitse ensimäisenä kuuna, kuin se oli täysi kaikkiin reunoihinsa asti; ja he ajoivat pakoon kaikki, jotka asuivat laaksossa, itään ja länteen päin.","Nämät ovat ne jotka menivät Jordanin ylitse ensimäisenä kuuna, kuin se oli täysi kaikkiin reunoihinsa asti; ja he ajoivat pakoon kaikki, jotka asuivat laaksossa, itään ja länteen päin."],[12,16,"Ja sinne myös tulivat BenJaminin lapsista ja Juudasta, Davidin tykö linnaan.","Ja sinne myös tulivat BenJaminin lapsista ja Juudasta, Davidin tykö linnaan."],[12,17,"Ja David meni ulos heidän tykönsä, ja vastasi ja sanoi heille: jos tulitte rauhan kanssa minun tyköni auttamaan minua, niin olkoon sydämeni teidän kanssanne: vaan jos tulitte pettämään minua vihollisilleni, vaikka ei vääryyttä ole minussa, niin meidän isäimme Jumala nähköön ja rangaiskoon;","Ja David meni ulos heidän tykönsä, ja vastasi ja sanoi heille: jos tulitte rauhan kanssa minun tyköni auttamaan minua, niin olkoon sydämeni teidän kanssanne: vaan jos tulitte pettämään minua vihollisilleni, vaikka ei vääryyttä ole minussa, niin meidän isäimme Jumala nähköön ja rangaiskoon;"],[12,18,"Ja henki vaikutti Amasain, päämiehen kolmenkymmenen seassa: Sinun me olemme, David, ja pidämme sinun kanssas, Isain poika, rauha, rauha olkoon sinulle, rauha olkoon sinun auttajilles! sillä sinun Jumalas auttaa sinua. Niin otti David heidät tykönsä ja asetti heidät sotaväen päämiehiksi.","Ja henki vaikutti Amasain, päämiehen kolmenkymmenen seassa: Sinun me olemme, David, ja pidämme sinun kanssas, Isain poika, rauha, rauha olkoon sinulle, rauha olkoon sinun auttajilles! sillä sinun Jumalas auttaa sinua. Niin otti David heidät tykönsä ja asetti heidät sotaväen päämiehiksi."],[12,19,"Ja Manassesta tuli väkeä Davidin puolelle, kuin hän meni Philistealaisten kanssa Saulia vastaan sotaan, vaikka ei he auttaneet heitä; sillä Philistealaisten päämiehet antoivat neuvonpiteestä hänen tyköänsä mennä pois, ja sanoivat: jos hän lankee herransa Saulin tykö, niin se tulee henkemme vaaraksi.","Ja Manassesta tuli väkeä Davidin puolelle, kuin hän meni Philistealaisten kanssa Saulia vastaan sotaan, vaikka ei he auttaneet heitä; sillä Philistealaisten päämiehet antoivat neuvonpiteestä hänen tyköänsä mennä pois, ja sanoivat: jos hän lankee herransa Saulin tykö, niin se tulee henkemme vaaraksi."],[12,20,"Kuin hän meni Ziklagiin, tulivat hänen tykönsä Manassesta Adna, Josabad, Jediael, Mikael, Josabad, Elihu ja Ziltai, tuhanten päämiehet Manassesta.","Kuin hän meni Ziklagiin, tulivat hänen tykönsä Manassesta Adna, Josabad, Jediael, Mikael, Josabad, Elihu ja Ziltai, tuhanten päämiehet Manassesta."],[12,21,"Ja he auttivat Davidia sotajoukkoa vastaan; sillä he olivat kaikki väkevät miehet ja olivat päämiehet sodassa.","Ja he auttivat Davidia sotajoukkoa vastaan; sillä he olivat kaikki väkevät miehet ja olivat päämiehet sodassa."],[12,22,"Ja joka päivä tuli muutamia Davidin tykö auttamaan häntä, siihenasti että se tuli suureksi sotajoukoksi, niinkuin Jumalan sotajoukoksi.","Ja joka päivä tuli muutamia Davidin tykö auttamaan häntä, siihenasti että se tuli suureksi sotajoukoksi, niinkuin Jumalan sotajoukoksi."],[12,23,"Ja tämä on sotaan hankittuin päämiesten luku, jotka tulivat Davidin tykö Hebroniin, kääntämään Saulin valtakuntaa hänen tykönsä, Herran sanan jälkeen:","Ja tämä on sotaan hankittuin päämiesten luku, jotka tulivat Davidin tykö Hebroniin, kääntämään Saulin valtakuntaa hänen tykönsä, Herran sanan jälkeen:"],[12,24,"Juudan lapsista, jotka kantoivat kilpeä ja keihästä, oli kuusituhatta ja kahdeksansataa sotaan hankittua;","Juudan lapsista, jotka kantoivat kilpeä ja keihästä, oli kuusituhatta ja kahdeksansataa sotaan hankittua;"],[12,25,"Simeonin lapsista väkevät miehet sotimaan, seitsemäntuhatta ja sata;","Simeonin lapsista väkevät miehet sotimaan, seitsemäntuhatta ja sata;"],[12,26,"Levin lapsista neljätuhatta ja kuusisataa;","Levin lapsista neljätuhatta ja kuusisataa;"],[12,27,"Ja Jojada niiden päämies, jotka olivat Aaronista, ja hänen kanssansa oli kolmetuhatta ja seitsemänsataa;","Ja Jojada niiden päämies, jotka olivat Aaronista, ja hänen kanssansa oli kolmetuhatta ja seitsemänsataa;"],[12,28,"Ja Zadok väkevä nuorukainen, ja hänen isänsä huoneen kanssa oli kaksikolmattakymmentä päämiestä;","Ja Zadok väkevä nuorukainen, ja hänen isänsä huoneen kanssa oli kaksikolmattakymmentä päämiestä;"],[12,29,"Ja BenJaminin lapsista Saulin veljistä kolmetuhatta; sillä siihenasti piti heistä sangen monta vielä Saulin huoneen kanssa;","Ja BenJaminin lapsista Saulin veljistä kolmetuhatta; sillä siihenasti piti heistä sangen monta vielä Saulin huoneen kanssa;"],[12,30,"Ja Ephraimin lapsista kaksikymmentä tuhatta ja kahdeksansataa, väkevät ja ylistetyt miehet heidän isäinsä huoneessa;","Ja Ephraimin lapsista kaksikymmentä tuhatta ja kahdeksansataa, väkevät ja ylistetyt miehet heidän isäinsä huoneessa;"],[12,31,"Ja puolesta Manassen sukukunnasta kahdeksantoistakymmentä tuhatta, jotka olivat nimeltänsä nimitetyt tulemaan ja tekemään Davidia kuninkaaksi;","Ja puolesta Manassen sukukunnasta kahdeksantoistakymmentä tuhatta, jotka olivat nimeltänsä nimitetyt tulemaan ja tekemään Davidia kuninkaaksi;"],[12,32,"Ja Isaskarin lapsista, jotka olivat taitavat aikain tietäjät ymmärtämään, mitä Israelin tekemän piti, kaksisataa heidän päämiestänsä, ja kaikki heidän veljensä tekivät heidän käskynsä jälkeen;","Ja Isaskarin lapsista, jotka olivat taitavat aikain tietäjät ymmärtämään, mitä Israelin tekemän piti, kaksisataa heidän päämiestänsä, ja kaikki heidän veljensä tekivät heidän käskynsä jälkeen;"],[12,33,"Sebulonista, jotka menivät sotimaan, hankitut sotaan kaikkinaisilla sota-aseilla, viisikymmentä tuhatta, asettamaan itsensä yksimielisesti järjestykseen;","Sebulonista, jotka menivät sotimaan, hankitut sotaan kaikkinaisilla sota-aseilla, viisikymmentä tuhatta, asettamaan itsensä yksimielisesti järjestykseen;"],[12,34,"Naphtalista tuhannen päämiestä, ja seitsemänneljättäkymmentä tuhatta heidän kanssansa, jotka kantoivat kilpeä ja keihästä;","Naphtalista tuhannen päämiestä, ja seitsemänneljättäkymmentä tuhatta heidän kanssansa, jotka kantoivat kilpeä ja keihästä;"],[12,35,"Danista hankitsivat sotaan kahdeksankolmattakymmentä tuhatta ja kuusisataa;","Danista hankitsivat sotaan kahdeksankolmattakymmentä tuhatta ja kuusisataa;"],[12,36,"Asserista, jotka menivät hankittuina sotimaan, neljäkymmentä tuhatta;","Asserista, jotka menivät hankittuina sotimaan, neljäkymmentä tuhatta;"],[12,37,"Tuolta puolelta Jordania: Rubenilaisista, Gadilaisista ja puolesta Manassen sukukunnasta, kaikkinaisilla aseilla sotaan, sata ja kaksikymmentä tuhatta.","Tuolta puolelta Jordania: Rubenilaisista, Gadilaisista ja puolesta Manassen sukukunnasta, kaikkinaisilla aseilla sotaan, sata ja kaksikymmentä tuhatta."],[12,38,"Kaikki nämät sotamiehet sodan toimittajat tulivat täydestä sydämestä Hebroniin, tekemään Davidia koko Israelin kuninkaaksi: niin myös kaikilla muilla Israelissa oli yksi mieli tehdä Davidia Israelin kuninkaaksi.","Kaikki nämät sotamiehet sodan toimittajat tulivat täydestä sydämestä Hebroniin, tekemään Davidia koko Israelin kuninkaaksi: niin myös kaikilla muilla Israelissa oli yksi mieli tehdä Davidia Israelin kuninkaaksi."],[12,39,"Ja he olivat siellä Davidin tykönä kolme päivää, söivät ja joivat; sillä heidän veljensä olivat valmistaneet heidän eteensä.","Ja he olivat siellä Davidin tykönä kolme päivää, söivät ja joivat; sillä heidän veljensä olivat valmistaneet heidän eteensä."],[12,40,"Ja ne myös, jotka likin olivat heidän ympärillänsä Isaskariin, Sebuloniin ja Naphtaliin asti, he toivat leipiä aaseilla, kameleilla, muuleilla ja härjillä, syötäviä jauhoja, fikunoita, rusinoita, viinaa, öljyä, härkiä ja lampaita viljalta; sillä ilo oli Israelissa.","Ja ne myös, jotka likin olivat heidän ympärillänsä Isaskariin, Sebuloniin ja Naphtaliin asti, he toivat leipiä aaseilla, kameleilla, muuleilla ja härjillä, syötäviä jauhoja, fikunoita, rusinoita, viinaa, öljyä, härkiä ja lampaita viljalta; sillä ilo oli Israelissa."],[13,1,"Ja David piti neuvoa tuhanten ja satain pääruhtinain ja kaikkein päämiesten kanssa.","Ja David piti neuvoa tuhanten ja satain pääruhtinain ja kaikkein päämiesten kanssa."],[13,2,"Ja David sanoi kaikelle Israelin joukoille: jos teille kelpaa, ja jos se on Herralta meidän Jumalaltamme, niin toimittakaamme kaikella muotoa menemään muiden meidän veljeimme tykö koko Israelin maahan, ja pappein ja Leviläisten tykö kaupunkeihin, joissa esikaupungit ovat, että he kokoontuisivat meidän tykömme,","Ja David sanoi kaikelle Israelin joukoille: jos teille kelpaa, ja jos se on Herralta meidän Jumalaltamme, niin toimittakaamme kaikella muotoa menemään muiden meidän veljeimme tykö koko Israelin maahan, ja pappein ja Leviläisten tykö kaupunkeihin, joissa esikaupungit ovat, että he kokoontuisivat meidän tykömme,"],[13,3,"Ja noutakaamme Jumalamme arkki meidän tykömme; sillä emme Saulin aikana siitä lukua pitäneet.","Ja noutakaamme Jumalamme arkki meidän tykömme; sillä emme Saulin aikana siitä lukua pitäneet."],[13,4,"Niin kaikki joukko vastasi, että niin piti tehtämän; sillä se kelpasi kaikelle kansalle.","Niin kaikki joukko vastasi, että niin piti tehtämän; sillä se kelpasi kaikelle kansalle."],[13,5,"Niin David kokosi kaiken Israelin, Egyptin Siihorista aina Hamatiin asti, noutamaan Jumalan arkkia Kirjatjearimista.","Niin David kokosi kaiken Israelin, Egyptin Siihorista aina Hamatiin asti, noutamaan Jumalan arkkia Kirjatjearimista."],[13,6,"Ja David meni ja kaikki Israel Baalatiin, Kirjatjearimiin, joka on Juudassa, noutamaan sieltä Herran Jumalan arkkia, joka Kerubimin päällä istuu, jonka nimeä rukoillaan.","Ja David meni ja kaikki Israel Baalatiin, Kirjatjearimiin, joka on Juudassa, noutamaan sieltä Herran Jumalan arkkia, joka Kerubimin päällä istuu, jonka nimeä rukoillaan."],[13,7,"Ja he panivat Jumalan arkin uuteen vaunuun, veivät sen Abinadabin huoneesta, ja Ussa ja Ahio ajoivat vaunua.","Ja he panivat Jumalan arkin uuteen vaunuun, veivät sen Abinadabin huoneesta, ja Ussa ja Ahio ajoivat vaunua."],[13,8,"Mutta David ja kaikki Israel iloitsivat Jumalan edessä kaikesta voimastansa, lauluilla, kanteleilla, psaltareilla, trumpuilla, symbaleilla ja basunilla.","Mutta David ja kaikki Israel iloitsivat Jumalan edessä kaikesta voimastansa, lauluilla, kanteleilla, psaltareilla, trumpuilla, symbaleilla ja basunilla."],[13,9,"Ja he tulivat Kidonin lakeudelle, niin ojensi Ussa kätensä arkkia pitelemään; sillä härjät poikkesivat sivulle.","Ja he tulivat Kidonin lakeudelle, niin ojensi Ussa kätensä arkkia pitelemään; sillä härjät poikkesivat sivulle."],[13,10,"Niin Herran viha julmistui Ussan päälle ja löi häntä, että hän ojensi kätensä arkkia pitämään, niin että hän siinä kuoli Jumalan edessä.","Niin Herran viha julmistui Ussan päälle ja löi häntä, että hän ojensi kätensä arkkia pitämään, niin että hän siinä kuoli Jumalan edessä."],[13,11,"Niin David tuli murheelliseksi, että Herra Ussan repäisi rikki. Ja hän kutsui sen paikan Perets-ussa tähän päivään asti,","Niin David tuli murheelliseksi, että Herra Ussan repäisi rikki. Ja hän kutsui sen paikan Perets-ussa tähän päivään asti,"],[13,12,"Ja David pelkäsi Jumalaa sinä päivänä ja sanoi: kuinka minun pitää viemän Jumalan arkin minun tyköni?","Ja David pelkäsi Jumalaa sinä päivänä ja sanoi: kuinka minun pitää viemän Jumalan arkin minun tyköni?"],[13,13,"Sentähden ei David antanut viedä Jumalan arkkia tykönsä Davidin kaupunkiin, vaan antoi poiketa Obededomin Gatilaisen huoneesen.","Sentähden ei David antanut viedä Jumalan arkkia tykönsä Davidin kaupunkiin, vaan antoi poiketa Obededomin Gatilaisen huoneesen."],[13,14,"Ja Jumalan arkki viipyi Obededomin tykönä hänen huoneessansa kolme kuukautta. Ja Herra siunasi Obededomin huoneen ja kaikki mitä hänellä oli.","Ja Jumalan arkki viipyi Obededomin tykönä hänen huoneessansa kolme kuukautta. Ja Herra siunasi Obededomin huoneen ja kaikki mitä hänellä oli."],[14,1,"Ja Hiram Tyron kuningas lähetti sanansaattajat Davidin tykö, ja sedripuita, muuraajia ja puuseppiä, rakentamaan hänelle huonetta.","Ja Hiram Tyron kuningas lähetti sanansaattajat Davidin tykö, ja sedripuita, muuraajia ja puuseppiä, rakentamaan hänelle huonetta."],[14,2,"Ja David ymmärsi, että Herra oli hänen vahvistanut Israelin kuninkaaksi; sillä hänen valtakuntansa korkeni hänen kansansa Israelin tähden.","Ja David ymmärsi, että Herra oli hänen vahvistanut Israelin kuninkaaksi; sillä hänen valtakuntansa korkeni hänen kansansa Israelin tähden."],[14,3,"Ja David otti vielä emäntiä Jerusalemissa, ja hän siitti vielä poikia ja tyttäriä.","Ja David otti vielä emäntiä Jerusalemissa, ja hän siitti vielä poikia ja tyttäriä."],[14,4,"Ja niiden nimet, jotka hänelle olivat syntyneet Jerusalemissa, olivat: Sammua, Sobab, Natan ja Salomo,","Ja niiden nimet, jotka hänelle olivat syntyneet Jerusalemissa, olivat: Sammua, Sobab, Natan ja Salomo,"],[14,5,"Jibhar, Elisua ja Elpalet,","Jibhar, Elisua ja Elpalet,"],[14,6,"Noga, Nepheg ja Japhia,","Noga, Nepheg ja Japhia,"],[14,7,"Elisama, Baeljada ja Eliphalet.","Elisama, Baeljada ja Eliphalet."],[14,8,"Ja kuin Philistealaiset kuulivat Davidin voidelluksi koko Israelin kuninkaaksi, nousivat kaikki Philistealaiset Davidia etsimään. Kun David sen kuuli, meni hän heitä vastaan.","Ja kuin Philistealaiset kuulivat Davidin voidelluksi koko Israelin kuninkaaksi, nousivat kaikki Philistealaiset Davidia etsimään. Kun David sen kuuli, meni hän heitä vastaan."],[14,9,"Ja Philistealaiset tulivat ja levisivät Rephaimin laaksoon.","Ja Philistealaiset tulivat ja levisivät Rephaimin laaksoon."],[14,10,"Mutta David kysyi neuvoa Jumalalta ja sanoi: pitääkö minun menemän ylös Philistealaisia vastaan, ja tahdotkos heitä antaa minun käsiini? Herra sanoi hänelle: mene, ja minä tahdon antaa heidät sinun käsiis.","Mutta David kysyi neuvoa Jumalalta ja sanoi: pitääkö minun menemän ylös Philistealaisia vastaan, ja tahdotkos heitä antaa minun käsiini? Herra sanoi hänelle: mene, ja minä tahdon antaa heidät sinun käsiis."],[14,11,"Ja kuin he menivät ylös Baalperatsimiin päin, löi David heidät siellä; ja David sanoi: Jumala on hajoittanut vihamieheni minun käteni kautta, niinkuin vesi hajoitetaan; sentähden kutsuivat he sen paikan nimen Baalperatsim.","Ja kuin he menivät ylös Baalperatsimiin päin, löi David heidät siellä; ja David sanoi: Jumala on hajoittanut vihamieheni minun käteni kautta, niinkuin vesi hajoitetaan; sentähden kutsuivat he sen paikan nimen Baalperatsim."],[14,12,"Ja he jättivät sinne jumalansa, ja Davidin käskyn jälkeen poltettiin ne tulessa.","Ja he jättivät sinne jumalansa, ja Davidin käskyn jälkeen poltettiin ne tulessa."],[14,13,"Mutta Philistealaiset kokoontuivat jälleen ja asettivat itsensä alas laaksoon.","Mutta Philistealaiset kokoontuivat jälleen ja asettivat itsensä alas laaksoon."],[14,14,"Ja David kysyi jälleen neuvoa Jumalalta, ja Jumala sanoi hänelle: ei sinun pidä menemän heidän jälkeensä; mutta poikkea heistä, ettäs tulisit metsäfikunapuiden kohdalla heitä vastaan.","Ja David kysyi jälleen neuvoa Jumalalta, ja Jumala sanoi hänelle: ei sinun pidä menemän heidän jälkeensä; mutta poikkea heistä, ettäs tulisit metsäfikunapuiden kohdalla heitä vastaan."],[14,15,"Ja kuin kuulet metsäfikunapuiden latvat havisevan, niin mene sotimaan; sillä Jumala on mennyt sinun edelläs lyömään Philistealaisten sotajoukkoa.","Ja kuin kuulet metsäfikunapuiden latvat havisevan, niin mene sotimaan; sillä Jumala on mennyt sinun edelläs lyömään Philistealaisten sotajoukkoa."],[14,16,"Ja David teki niinkuin Jumala hänelle oli käskenyt; ja he löivät Philistealaisten sotajoukot Gibeonista niin Gaseriin asti.","Ja David teki niinkuin Jumala hänelle oli käskenyt; ja he löivät Philistealaisten sotajoukot Gibeonista niin Gaseriin asti."],[14,17,"Ja Davidin nimi kuului kaikissa maissa; ja Herra antoi hänen pelkonsa tulla kaikkein pakanain päälle.","Ja Davidin nimi kuului kaikissa maissa; ja Herra antoi hänen pelkonsa tulla kaikkein pakanain päälle."],[15,1,"Ja hän rakensi itsellensä huoneita Davidin kaupunkiin, ja valmisti sian Jumalan arkille, ja valmisti sille majan.","Ja hän rakensi itsellensä huoneita Davidin kaupunkiin, ja valmisti sian Jumalan arkille, ja valmisti sille majan."],[15,2,"Silloin sanoi David: ei yhdenkään pidä kantaman Jumalan arkkia, vaan Leviläiset; sillä Herra on heidät valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ijankaikkisesti.","Silloin sanoi David: ei yhdenkään pidä kantaman Jumalan arkkia, vaan Leviläiset; sillä Herra on heidät valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ijankaikkisesti."],[15,3,"Sentähden kokosi David koko Israelin Jerusalemiin, kantamaan Herran arkkia ylös siihen paikkaan, jonka hän hänelle valmistanut oli.","Sentähden kokosi David koko Israelin Jerusalemiin, kantamaan Herran arkkia ylös siihen paikkaan, jonka hän hänelle valmistanut oli."],[15,4,"Ja David antoi myös tulla kokoon Aaronin lapset ja Leviläiset:","Ja David antoi myös tulla kokoon Aaronin lapset ja Leviläiset:"],[15,5,"Kahatin lapsista päämiehen Urielin, sadan ja kahdenkymmenen veljensä kanssa;","Kahatin lapsista päämiehen Urielin, sadan ja kahdenkymmenen veljensä kanssa;"],[15,6,"Merarin lapsista päämiehen Asajan, kahdensadan ja kahdenkymmenen veljensä kanssa;","Merarin lapsista päämiehen Asajan, kahdensadan ja kahdenkymmenen veljensä kanssa;"],[15,7,"Gersomin lapsista päämiehen Joelin, sadan ja kolmenkymmenen veljensä kanssa;","Gersomin lapsista päämiehen Joelin, sadan ja kolmenkymmenen veljensä kanssa;"],[15,8,"Elitsaphanin lapsista päämiehen Semajan, kahdensadan veljensä kanssa;","Elitsaphanin lapsista päämiehen Semajan, kahdensadan veljensä kanssa;"],[15,9,"Hebronin lapsista päämiehen Elielin, kahdeksankymmenen veljensä kanssa;","Hebronin lapsista päämiehen Elielin, kahdeksankymmenen veljensä kanssa;"],[15,10,"Ussielin lapsista päämiehen Amminadabin, sadan ja kahdeksantoistakymmenen veljensä kanssa.","Ussielin lapsista päämiehen Amminadabin, sadan ja kahdeksantoistakymmenen veljensä kanssa."],[15,11,"Ja David kutsui papit Zadokin ja Abjatarin, ja Leviläiset, Urielin, Asajan, Joelin, Semajan, Elielin ja Amminadabin,","Ja David kutsui papit Zadokin ja Abjatarin, ja Leviläiset, Urielin, Asajan, Joelin, Semajan, Elielin ja Amminadabin,"],[15,12,"Ja sanoi heille: te kuin olette isäin päämiehet Leviläisten seassa, pyhittäkäät teitänne veljeinne kanssa kantamaan ylös Herran Israelin Jumalan arkkia siihen siaan, jonka minä hänelle valmistanut olen.","Ja sanoi heille: te kuin olette isäin päämiehet Leviläisten seassa, pyhittäkäät teitänne veljeinne kanssa kantamaan ylös Herran Israelin Jumalan arkkia siihen siaan, jonka minä hänelle valmistanut olen."],[15,13,"Sillä ennen kuin ette läsnä olleet, teki Herra meidän Jumalamme raon meissä, ettemme häntä etsineet, niinkuin meidän tekemän piti.","Sillä ennen kuin ette läsnä olleet, teki Herra meidän Jumalamme raon meissä, ettemme häntä etsineet, niinkuin meidän tekemän piti."],[15,14,"Niin papit ja Leviläiset pyhittivät itsensä Herran Israelin Jumalan arkkia kantamaan.","Niin papit ja Leviläiset pyhittivät itsensä Herran Israelin Jumalan arkkia kantamaan."],[15,15,"Ja Leviläisten pojat kantoivat Jumalan arkin, niinkuin Moses Herran sanan jälkeen käskenyt oli, olallansa korennoilla, jotka siinä olivat.","Ja Leviläisten pojat kantoivat Jumalan arkin, niinkuin Moses Herran sanan jälkeen käskenyt oli, olallansa korennoilla, jotka siinä olivat."],[15,16,"Ja David sanoi Leviläisten päämiehille, että he asettaisivat veljistänsä veisaajia harpuilla, psaltareilla, kanteleilla ja symbaleilla, niin että he olisivat kuultut veisaavan korkialla äänellä ilon kanssa.","Ja David sanoi Leviläisten päämiehille, että he asettaisivat veljistänsä veisaajia harpuilla, psaltareilla, kanteleilla ja symbaleilla, niin että he olisivat kuultut veisaavan korkialla äänellä ilon kanssa."],[15,17,"Niin Leviläiset asettivat Hemanin Joelin pojan ja hänen veljistänsä Asaphin Berekian pojan, ja Merarin pojista heidän veljistänsä Etanin Kusajan pojan,","Niin Leviläiset asettivat Hemanin Joelin pojan ja hänen veljistänsä Asaphin Berekian pojan, ja Merarin pojista heidän veljistänsä Etanin Kusajan pojan,"],[15,18,"Ja heidän kanssansa heidän veljensä toisesta vuorosta, Sakarian, Benin, Jaeselin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maesejan, Mattitjan, Eliphelehun, Miknejan, Obededomin ja Jeielin, ovenvartiat.","Ja heidän kanssansa heidän veljensä toisesta vuorosta, Sakarian, Benin, Jaeselin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maesejan, Mattitjan, Eliphelehun, Miknejan, Obededomin ja Jeielin, ovenvartiat."],[15,19,"Sillä Heman, Asaph ja Etan olivat veisaajat vaskisymbaleilla, helistäin heliällä äänellä;","Sillä Heman, Asaph ja Etan olivat veisaajat vaskisymbaleilla, helistäin heliällä äänellä;"],[15,20,"Mutta Sakaria, Ussiel, Semiramot, Jehiel, Unni, Eliab, Maesia ja Benaja psaltarilla alamotin päällä;","Mutta Sakaria, Ussiel, Semiramot, Jehiel, Unni, Eliab, Maesia ja Benaja psaltarilla alamotin päällä;"],[15,21,"Vaan Mattitja ja Eliphelehu ja Mikneja, ja Obededom, Jeiel ja Ahasia veisasivat kahdeksan kielisillä kanteleilla heidän edellänsä.","Vaan Mattitja ja Eliphelehu ja Mikneja, ja Obededom, Jeiel ja Ahasia veisasivat kahdeksan kielisillä kanteleilla heidän edellänsä."],[15,22,"Mutta Kenania Leviläisten päämies, veisumestari, piti neuvoman heitä ylhäisesti veisaamaan; sillä hän oli sangen taitava.","Mutta Kenania Leviläisten päämies, veisumestari, piti neuvoman heitä ylhäisesti veisaamaan; sillä hän oli sangen taitava."],[15,23,"Ja Berekia ja Elkana olivat arkin ovenvartiat.","Ja Berekia ja Elkana olivat arkin ovenvartiat."],[15,24,"Mutta papit Sebania, Josaphat, Netaneel, Amasai, Sakaria, Benaja ja Elieser soittivat basunilla Jumalan arkin edessä; ja Obededom ja Jehija olivat arkin ovenvartiat.","Mutta papit Sebania, Josaphat, Netaneel, Amasai, Sakaria, Benaja ja Elieser soittivat basunilla Jumalan arkin edessä; ja Obededom ja Jehija olivat arkin ovenvartiat."],[15,25,"Niin meni David ja Israelin vanhimmat ja tuhanten päämiehet noutamaan Herran liitonarkkia Obededomin huoneesta ilolla.","Niin meni David ja Israelin vanhimmat ja tuhanten päämiehet noutamaan Herran liitonarkkia Obededomin huoneesta ilolla."],[15,26,"Ja koska Jumala autti Leviläisiä, jotka kantoivat Herran liitonarkkia, uhrasivat he seitsemän mullia ja seitsemän oinasta.","Ja koska Jumala autti Leviläisiä, jotka kantoivat Herran liitonarkkia, uhrasivat he seitsemän mullia ja seitsemän oinasta."],[15,27,"Ja David oli puettu liinavaatteella, ja kaikki Leviläiset, jotka arkkia kantoivat, ja veisaajat, ja Kenania veisumestari veisaajain kanssa; oli myös Davidin yllä liinainen päällisvaate.","Ja David oli puettu liinavaatteella, ja kaikki Leviläiset, jotka arkkia kantoivat, ja veisaajat, ja Kenania veisumestari veisaajain kanssa; oli myös Davidin yllä liinainen päällisvaate."],[15,28,"Niin saatti koko Israel Herran liitonarkin ilolla, basunain, trometein, heliäin symbalein, psaltarein ja kantelein kanssa.","Niin saatti koko Israel Herran liitonarkin ilolla, basunain, trometein, heliäin symbalein, psaltarein ja kantelein kanssa."],[15,29,"Kuin Herran liitonarkki tuli Davidin kaupunkiin, katsoi Mikal Saulin tytär akkunasta ja näki Davidin hyppäävän ja soittavan, niin hän katsoi hänen sydämessänsä ylön.","Kuin Herran liitonarkki tuli Davidin kaupunkiin, katsoi Mikal Saulin tytär akkunasta ja näki Davidin hyppäävän ja soittavan, niin hän katsoi hänen sydämessänsä ylön."],[16,1,"Kuin he Jumalan arkin olivat kantaneet sisälle, asettivat he sen keskelle majaa, jonka David oli valmistanut, ja uhrasivat polttouhria ja kiitosuhria Jumalan edessä.","Kuin he Jumalan arkin olivat kantaneet sisälle, asettivat he sen keskelle majaa, jonka David oli valmistanut, ja uhrasivat polttouhria ja kiitosuhria Jumalan edessä."],[16,2,"Ja kuin David oli täyttänyt polttouhrit ja kiitosuhrit, siunasi hän kansaa Herran nimeen,","Ja kuin David oli täyttänyt polttouhrit ja kiitosuhrit, siunasi hän kansaa Herran nimeen,"],[16,3,"Ja jakoi jokaiselle Israelissa sekä miehille että vaimoille, jokaiselle leivän ja kappaleen lihaa ja mitan viinaa.","Ja jakoi jokaiselle Israelissa sekä miehille että vaimoille, jokaiselle leivän ja kappaleen lihaa ja mitan viinaa."],[16,4,"Ja hän asetti Herran arkin eteen muutamia Leviläisiä palveliaksi, ylistämään, kiittämään ja kunnioittamaan Herraa Israelin Jumalaa.","Ja hän asetti Herran arkin eteen muutamia Leviläisiä palveliaksi, ylistämään, kiittämään ja kunnioittamaan Herraa Israelin Jumalaa."],[16,5,"Ne olivat: Asaph ensimäinen, Sakaria toinen, Jeiel, Semiramot, Jehiel, Mattitja, Eliab, Benaja, Obededom ja Jeiel, psaltarein ja harppuin kanssa; mutta Asaph kiliseväisten symbalein kanssa;","Ne olivat: Asaph ensimäinen, Sakaria toinen, Jeiel, Semiramot, Jehiel, Mattitja, Eliab, Benaja, Obededom ja Jeiel, psaltarein ja harppuin kanssa; mutta Asaph kiliseväisten symbalein kanssa;"],[16,6,"Ja Benaja ja Jehasiel papit, vaskitorvilla, aina Jumalan liitonarkin edessä.","Ja Benaja ja Jehasiel papit, vaskitorvilla, aina Jumalan liitonarkin edessä."],[16,7,"Sinä päivänä asetti David ensisti kiittämään Herraa, Asaphin ja hänen veljeinsä kautta.","Sinä päivänä asetti David ensisti kiittämään Herraa, Asaphin ja hänen veljeinsä kautta."],[16,8,"Kiittäkäät Herraa ja saarnatkaat hänen nimeänsä, julistakaat hänen töitänsä kansain seassa;","Kiittäkäät Herraa ja saarnatkaat hänen nimeänsä, julistakaat hänen töitänsä kansain seassa;"],[16,9,"Veisatkaat hänelle, soittakaat hänelle, puhukaat kaikista hänen ihmeellisistä töistänsä!","Veisatkaat hänelle, soittakaat hänelle, puhukaat kaikista hänen ihmeellisistä töistänsä!"],[16,10,"Ylistäkäät hänen pyhää nimeänsä, niiden sydän iloitkaan, jotka etsivät Herraa!","Ylistäkäät hänen pyhää nimeänsä, niiden sydän iloitkaan, jotka etsivät Herraa!"],[16,11,"Etsikäät Herraa ja hänen voimaansa, etsikäät hänen kasvojansa alati!","Etsikäät Herraa ja hänen voimaansa, etsikäät hänen kasvojansa alati!"],[16,12,"Muistakaat hänen ihmeellisiä töitänsä, jotka hän tehnyt on, hänen ihmeitänsä ja suunsa tuomioita,","Muistakaat hänen ihmeellisiä töitänsä, jotka hän tehnyt on, hänen ihmeitänsä ja suunsa tuomioita,"],[16,13,"Te Israelin hänen palveliansa siemen, te Jakobin hänen valittunsa lapset!","Te Israelin hänen palveliansa siemen, te Jakobin hänen valittunsa lapset!"],[16,14,"Hänpä on Herra meidän Jumalamme, hän tuomitsee kaikessa maailmassa.","Hänpä on Herra meidän Jumalamme, hän tuomitsee kaikessa maailmassa."],[16,15,"Muistakaat ijankaikkisesti hänen liittoansa, mitä hän on käskenyt tuhannelle sukukunnalle,","Muistakaat ijankaikkisesti hänen liittoansa, mitä hän on käskenyt tuhannelle sukukunnalle,"],[16,16,"Jonka hän teki Abrahamin kanssa ja hänen valaansa Isaakin kanssa;","Jonka hän teki Abrahamin kanssa ja hänen valaansa Isaakin kanssa;"],[16,17,"Ja sääsi sen Jakobille säädyksi ja Israelille ijankaikkiseksi liitoksi,","Ja sääsi sen Jakobille säädyksi ja Israelille ijankaikkiseksi liitoksi,"],[16,18,"Ja sanoi: sinulle minä annan Kanaanin maan, teidän perimisenne arvan;","Ja sanoi: sinulle minä annan Kanaanin maan, teidän perimisenne arvan;"],[16,19,"Koska te vähät ja harvat olitte, ja muukalaiset siinä.","Koska te vähät ja harvat olitte, ja muukalaiset siinä."],[16,20,"Ja he vaelsivat kansasta kansaan, ja yhdestä valtakunnasta toiseen kansaan.","Ja he vaelsivat kansasta kansaan, ja yhdestä valtakunnasta toiseen kansaan."],[16,21,"Eipä hän sallinut kenenkään heitä vahingoittaa, vaan rankaisi kuninkaat heidän tähtensä.","Eipä hän sallinut kenenkään heitä vahingoittaa, vaan rankaisi kuninkaat heidän tähtensä."],[16,22,"Älkäät ruvetko minun voideltuihini, ja älkäät pahaa tehkö minun prophetailleni!","Älkäät ruvetko minun voideltuihini, ja älkäät pahaa tehkö minun prophetailleni!"],[16,23,"Veisatkaat Herralle kaikki maa, julistakaat päivä päivältä hänen autuuttansa!","Veisatkaat Herralle kaikki maa, julistakaat päivä päivältä hänen autuuttansa!"],[16,24,"Luetelkaat pakanain seassa hänen kunniaansa, kaikkein kansain seassa hänen ihmeitänsä!","Luetelkaat pakanain seassa hänen kunniaansa, kaikkein kansain seassa hänen ihmeitänsä!"],[16,25,"Sillä Herra on suuri ja sangen kiitettävä, peljättävä kaikkein jumalain seassa;","Sillä Herra on suuri ja sangen kiitettävä, peljättävä kaikkein jumalain seassa;"],[16,26,"Sillä kaikki pakanain jumalat ovat epäjumalat; mutta Herra on taivaat tehnyt.","Sillä kaikki pakanain jumalat ovat epäjumalat; mutta Herra on taivaat tehnyt."],[16,27,"Kaunistus ja kunnia on hänen edessänsä, ja väkevyys ja ilo on hänen siassansa.","Kaunistus ja kunnia on hänen edessänsä, ja väkevyys ja ilo on hänen siassansa."],[16,28,"Te kansain sukukunnat, tuokaat Herralle, tuokaat Herralle kunnia ja voima!","Te kansain sukukunnat, tuokaat Herralle, tuokaat Herralle kunnia ja voima!"],[16,29,"Tuokaat Herralle hänen nimensä kunnia, tuokaat lahjoja ja tulkaat hänen eteensä. Kumartakaat Herraa pyhässä kaunistuksessa!","Tuokaat Herralle hänen nimensä kunnia, tuokaat lahjoja ja tulkaat hänen eteensä. Kumartakaat Herraa pyhässä kaunistuksessa!"],[16,30,"Peljätkäät häntä kaikki maailma; hän on maan vahvistanut, ettei se liiku.","Peljätkäät häntä kaikki maailma; hän on maan vahvistanut, ettei se liiku."],[16,31,"Taivaat iloitkaan ja maa riemuitkaan, sanottakaan pakanain seassa, että Herra hallitsee!","Taivaat iloitkaan ja maa riemuitkaan, sanottakaan pakanain seassa, että Herra hallitsee!"],[16,32,"Meri pauhatkaan ja mitä siinä on, kedot iloitkaan ja kaikki, mitä sen päällä on.","Meri pauhatkaan ja mitä siinä on, kedot iloitkaan ja kaikki, mitä sen päällä on."],[16,33,"Ja ihastukaan kaikki puut metsissä Herran edessä; sillä hän tulee tuomitsemaan maata.","Ja ihastukaan kaikki puut metsissä Herran edessä; sillä hän tulee tuomitsemaan maata."],[16,34,"Kiittäkäät Herraa, sillä hän on hyvä, ja hänen laupiutensa on ijankaikkinen!","Kiittäkäät Herraa, sillä hän on hyvä, ja hänen laupiutensa on ijankaikkinen!"],[16,35,"Ja sanokaat: auta meitä Jumala, meidän vapahtajamme, ja kokoa meitä ja kehitä meitä pakanoista, että me kiittäisimme sinun pyhää nimeäs ja kerskaisimme sinun kiitoksessas.","Ja sanokaat: auta meitä Jumala, meidän vapahtajamme, ja kokoa meitä ja kehitä meitä pakanoista, että me kiittäisimme sinun pyhää nimeäs ja kerskaisimme sinun kiitoksessas."],[16,36,"Kiitetty olkoon Herra Israelin Jumala ijankaikkisesta ijankaikkiseen; ja kaikki kansa sanokaan: amen! ja kiittäkään Herraa!","Kiitetty olkoon Herra Israelin Jumala ijankaikkisesta ijankaikkiseen; ja kaikki kansa sanokaan: amen! ja kiittäkään Herraa!"],[16,37,"Näin jätti hän Herran liitonarkin eteen Asaphin ja hänen veljensä, palvelemaan alinomati arkin edessä jokapäiväisessä työssä;","Näin jätti hän Herran liitonarkin eteen Asaphin ja hänen veljensä, palvelemaan alinomati arkin edessä jokapäiväisessä työssä;"],[16,38,"Mutta Obededomin ja hänen kahdeksan veljeänsä seitsemättäkymmentä, ja Obededomin Jeditunin pojan ja Hossan, ovenvartiaksi.","Mutta Obededomin ja hänen kahdeksan veljeänsä seitsemättäkymmentä, ja Obededomin Jeditunin pojan ja Hossan, ovenvartiaksi."],[16,39,"Ja papin Zadokin ja papit hänen veljensä pani hän Herran majan eteen Gibeonin korkeudelle,","Ja papin Zadokin ja papit hänen veljensä pani hän Herran majan eteen Gibeonin korkeudelle,"],[16,40,"Tekemään päivä päivältä Herralle polttouhria polttouhrin alttarilla aamulla ja ehtoolla; kaiketi niinkuin kirjoitettu on Herran laissa, ja hän Israelille käskenyt oli;","Tekemään päivä päivältä Herralle polttouhria polttouhrin alttarilla aamulla ja ehtoolla; kaiketi niinkuin kirjoitettu on Herran laissa, ja hän Israelille käskenyt oli;"],[16,41,"Ja Hemanin ja Jedutunin heidän kanssansa, ja muut valitut, nimeltänsä nimitetyt, kiittämään Herraa, että hänen laupiutensa on ijankaikkisesti;","Ja Hemanin ja Jedutunin heidän kanssansa, ja muut valitut, nimeltänsä nimitetyt, kiittämään Herraa, että hänen laupiutensa on ijankaikkisesti;"],[16,42,"Ja Hemanin ja Jedutunin heidän kanssansa, vaskitorvilla ja symbaleilla soittamaan, ja Jumalan kanteleilla. Mutta Jedutunin pojat pani hän ovenvartiaksi.","Ja Hemanin ja Jedutunin heidän kanssansa, vaskitorvilla ja symbaleilla soittamaan, ja Jumalan kanteleilla. Mutta Jedutunin pojat pani hän ovenvartiaksi."],[16,43,"Ja näin matkusti kaikki kansa kukin kotiansa; David myös palasi siunaamaan huonettansa.","Ja näin matkusti kaikki kansa kukin kotiansa; David myös palasi siunaamaan huonettansa."],[17,1,"Ja tapahtui, kuin David asui huoneessansa, sanoi hän propheta Natanille: katso, minä asun sedrihuoneessa, ja Herran liitonarkki on vaatetten alla.","Ja tapahtui, kuin David asui huoneessansa, sanoi hän propheta Natanille: katso, minä asun sedrihuoneessa, ja Herran liitonarkki on vaatetten alla."],[17,2,"Natan sanoi Davidille: kaikki mikä sinun sydämessäs on, tee, sillä Herra on sinun kanssas.","Natan sanoi Davidille: kaikki mikä sinun sydämessäs on, tee, sillä Herra on sinun kanssas."],[17,3,"Mutta sinä yönä tuli Jumalan sana Natanin tykö ja sanoi:","Mutta sinä yönä tuli Jumalan sana Natanin tykö ja sanoi:"],[17,4,"Mene ja sano palvelialleni Davidille: näin sanoo Herra: ei sinun pidä minulle rakentaman huonetta asuakseni;","Mene ja sano palvelialleni Davidille: näin sanoo Herra: ei sinun pidä minulle rakentaman huonetta asuakseni;"],[17,5,"Sillä en minä ole asunut yhdessäkään huoneessa siitä päivästä, kuin minä Israelin lapset johdatin ulos, tähän päivään asti, vaan minä olen aina ollut majoissa ja tabernaklissa.","Sillä en minä ole asunut yhdessäkään huoneessa siitä päivästä, kuin minä Israelin lapset johdatin ulos, tähän päivään asti, vaan minä olen aina ollut majoissa ja tabernaklissa."],[17,6,"Kuhunka ikänä minä vaelsin koko Israelissa, olenko minä puhutellut jotakuta tuomaria Israelissa, jonka minä olen käskenyt kaita minun kansaani, ja sanonut: miksi ette ole minulle rakentaneet sedrihuonetta?","Kuhunka ikänä minä vaelsin koko Israelissa, olenko minä puhutellut jotakuta tuomaria Israelissa, jonka minä olen käskenyt kaita minun kansaani, ja sanonut: miksi ette ole minulle rakentaneet sedrihuonetta?"],[17,7,"Niin sano nyt näin palvelialleni Davidille: näin sanoo Herra Zebaot: minä olen ottanut sinun kedolta, kussas lampaita kaitsit, kansani Israelin päämieheksi,","Niin sano nyt näin palvelialleni Davidille: näin sanoo Herra Zebaot: minä olen ottanut sinun kedolta, kussas lampaita kaitsit, kansani Israelin päämieheksi,"],[17,8,"Ja olen ollut sinun kanssas, kuhunkas ikänä vaelsit, ja olen hävittänyt kaikki vihamiehes edestäs, ja olen tehnyt sinulle nimen, niiden suurten nimien jälkeen, jotka maan päällä ovat;","Ja olen ollut sinun kanssas, kuhunkas ikänä vaelsit, ja olen hävittänyt kaikki vihamiehes edestäs, ja olen tehnyt sinulle nimen, niiden suurten nimien jälkeen, jotka maan päällä ovat;"],[17,9,"Mutta minä panen kansalleni Israelille paikan ja istutan sen niin, että se siinä asuu ja ei enään liikuteta, ja pahan kansan ei pidä enää sitä vaivaaman niinkuin ennen.","Mutta minä panen kansalleni Israelille paikan ja istutan sen niin, että se siinä asuu ja ei enään liikuteta, ja pahan kansan ei pidä enää sitä vaivaaman niinkuin ennen."],[17,10,"Ja siitä ajasta, jona minä asetin tuomarit kansalleni Israelille, painoin minä kaikki sinun vihamiehes alas: ja minä ilmoitan sinulle Herran rakentavan sinulle huoneen.","Ja siitä ajasta, jona minä asetin tuomarit kansalleni Israelille, painoin minä kaikki sinun vihamiehes alas: ja minä ilmoitan sinulle Herran rakentavan sinulle huoneen."],[17,11,"Ja pitää tapahtuman, kuin sinun aikas on täytetty, että sinä menet isäis tykö, niin minä herätän sinun siemenes sinun jälkees, joka pitää oleman sinun pojistas, ja minä vahvistan hänen valtakuntansa.","Ja pitää tapahtuman, kuin sinun aikas on täytetty, että sinä menet isäis tykö, niin minä herätän sinun siemenes sinun jälkees, joka pitää oleman sinun pojistas, ja minä vahvistan hänen valtakuntansa."],[17,12,"Hän rakentaa minulle huoneen, ja minä vahvistan hänen istuimensa ijankaikkisesti.","Hän rakentaa minulle huoneen, ja minä vahvistan hänen istuimensa ijankaikkisesti."],[17,13,"Minä olen hänen isänsä, ja hän on minun poikani: ja en minä käännä laupiuttani häneltä pois, niinkuin minä sen käänsin häneltä pois, joka sinun edelläs oli;","Minä olen hänen isänsä, ja hän on minun poikani: ja en minä käännä laupiuttani häneltä pois, niinkuin minä sen käänsin häneltä pois, joka sinun edelläs oli;"],[17,14,"Mutta minä asetan hänen minun huoneeseni ja valtakuntaani ijankaikkisesti, niin että hänen istuimensa on pysyväinen ijankaikkisesti.","Mutta minä asetan hänen minun huoneeseni ja valtakuntaani ijankaikkisesti, niin että hänen istuimensa on pysyväinen ijankaikkisesti."],[17,15,"Ja kuin Natan kaikkein näiden sanain jälkeen ja kaiken tämän näyn jälkeen Davidin kanssa puhunut oli,","Ja kuin Natan kaikkein näiden sanain jälkeen ja kaiken tämän näyn jälkeen Davidin kanssa puhunut oli,"],[17,16,"Niin tuli kuningas David ja oli Herran edessä, ja sanoi: kuka olen minä, Herra Jumala? ja mikä on minun huoneeni, ettäs olet saattanut minun tähän asti?","Niin tuli kuningas David ja oli Herran edessä, ja sanoi: kuka olen minä, Herra Jumala? ja mikä on minun huoneeni, ettäs olet saattanut minun tähän asti?"],[17,17,"Ja tämä on vähä ollut sinun silmäis edessä, Jumala, mutta sinä olet myös puhunut sinun palvelias huoneelle kaukaisista asioista, ja olet katsellut minun niinkuin ihmisen hahmossa, joka on Herra Jumala korkeudessa.","Ja tämä on vähä ollut sinun silmäis edessä, Jumala, mutta sinä olet myös puhunut sinun palvelias huoneelle kaukaisista asioista, ja olet katsellut minun niinkuin ihmisen hahmossa, joka on Herra Jumala korkeudessa."],[17,18,"Mitä enempää David mahtaa anoa sinulta, ettäs kunnioittaisit palvelias? sillä sinä tunnet palvelias.","Mitä enempää David mahtaa anoa sinulta, ettäs kunnioittaisit palvelias? sillä sinä tunnet palvelias."],[17,19,"Herra, palvelias tähden ja sinun sydämes jälkeen olet sinä kaikki nämät suuret asiat tehnyt, ilmoittaakses kaikki ne suuret työt.","Herra, palvelias tähden ja sinun sydämes jälkeen olet sinä kaikki nämät suuret asiat tehnyt, ilmoittaakses kaikki ne suuret työt."],[17,20,"Herra, ei ole sinun kaltaistas ja ei ole Jumalaa paitsi sinua, kaiken senjälkeen, minkä me korvillamme kuulleet olemme.","Herra, ei ole sinun kaltaistas ja ei ole Jumalaa paitsi sinua, kaiken senjälkeen, minkä me korvillamme kuulleet olemme."],[17,21,"Ja mikä kansa maan päällä on niinkuin kansas Israel, jota Jumala mennyt on vapahtamaan itsellensä kansaksi, ja tekemään itsellensä nimeä suurista ja hirmuisista töistä, ajain pakanat ulos kansas edestä, jonkas Egyptistä vapahtanut olet?","Ja mikä kansa maan päällä on niinkuin kansas Israel, jota Jumala mennyt on vapahtamaan itsellensä kansaksi, ja tekemään itsellensä nimeä suurista ja hirmuisista töistä, ajain pakanat ulos kansas edestä, jonkas Egyptistä vapahtanut olet?"],[17,22,"Ja olet tehnyt kansas Israelin itselles ijankaikkiseksi kansaksi, ja sinä Herra olet heidän Jumalaksensa tullut.","Ja olet tehnyt kansas Israelin itselles ijankaikkiseksi kansaksi, ja sinä Herra olet heidän Jumalaksensa tullut."],[17,23,"Nyt Herra, se sana, jonkas puhunut olet palveliastas ja hänen huoneestansa, vahvistukoon ijankaikkisesti! ja tee niinkuin sinä puhunut olet.","Nyt Herra, se sana, jonkas puhunut olet palveliastas ja hänen huoneestansa, vahvistukoon ijankaikkisesti! ja tee niinkuin sinä puhunut olet."],[17,24,"Vahvistukoon ja suureksi tulkoon sinun nimes ijankaikkisesti! että sanottaisiin: Herra Zebaot, Israelin Jumala, on Jumala Israelissa, ja palvelias Davidin huone olkoon pysyväinen sinun edessäs!","Vahvistukoon ja suureksi tulkoon sinun nimes ijankaikkisesti! että sanottaisiin: Herra Zebaot, Israelin Jumala, on Jumala Israelissa, ja palvelias Davidin huone olkoon pysyväinen sinun edessäs!"],[17,25,"Sillä sinä, Jumalani, olet ilmoittanut palvelias korvain kuullen, ettäs rakennat hänelle huoneen, sentähden on palvelias aikonut rukoilla sinun edessäs.","Sillä sinä, Jumalani, olet ilmoittanut palvelias korvain kuullen, ettäs rakennat hänelle huoneen, sentähden on palvelias aikonut rukoilla sinun edessäs."],[17,26,"Nyt Herra, sinä olet Jumala, ja sinä olet tätä hyvää puhunut palvelialles;","Nyt Herra, sinä olet Jumala, ja sinä olet tätä hyvää puhunut palvelialles;"],[17,27,"Niin rupee nyt siunaamaan palvelias huonetta, että se pysyis ijankaikkisesti sinun edessäs; sillä sinä Herra olet siunannut sen, niin olkoon se siunattu ijankaikkisesti!","Niin rupee nyt siunaamaan palvelias huonetta, että se pysyis ijankaikkisesti sinun edessäs; sillä sinä Herra olet siunannut sen, niin olkoon se siunattu ijankaikkisesti!"],[18,1,"Sitte löi David Philistealaiset ja vaati allensa heidät, ja hän otti Gatin kylinensä Philistealaisten kädestä.","Sitte löi David Philistealaiset ja vaati allensa heidät, ja hän otti Gatin kylinensä Philistealaisten kädestä."],[18,2,"Hän löi myös Moabilaiset, niin että he tulivat Davidille alamaisiksi ja veivät hänelle lahjoja.","Hän löi myös Moabilaiset, niin että he tulivat Davidille alamaisiksi ja veivät hänelle lahjoja."],[18,3,"David löi myös Hadareserin Zoban kuninkaan Hamatissa, silloin kuin hän meni asettamaan sotajoukkoansa Phratin veden tykö.","David löi myös Hadareserin Zoban kuninkaan Hamatissa, silloin kuin hän meni asettamaan sotajoukkoansa Phratin veden tykö."],[18,4,"Ja David voitti häneltä tuhannen vaunua, seitsemäntuhatta hevosmiestä ja kaksikymmentätuhatta jalkamiestä. Ja David raiskasi kaikki vaunut, ja piti heistä tallella sata vaunua.","Ja David voitti häneltä tuhannen vaunua, seitsemäntuhatta hevosmiestä ja kaksikymmentätuhatta jalkamiestä. Ja David raiskasi kaikki vaunut, ja piti heistä tallella sata vaunua."],[18,5,"Ja Syrialaiset Damaskusta tulivat Hadareserin Zoban kuninkaan apuun; mutta David löi Syrialaisista kaksikolmattakymmentä tuhatta miestä.","Ja Syrialaiset Damaskusta tulivat Hadareserin Zoban kuninkaan apuun; mutta David löi Syrialaisista kaksikolmattakymmentä tuhatta miestä."],[18,6,"Ja David asetti vartiat Syrian Damaskuun, niin että Syrialaiset tulivat Davidin alamaisiksi ja veivät hänelle lahjoja; sillä Herra autti Davidia, kuhunka ikänä hän vaelsi.","Ja David asetti vartiat Syrian Damaskuun, niin että Syrialaiset tulivat Davidin alamaisiksi ja veivät hänelle lahjoja; sillä Herra autti Davidia, kuhunka ikänä hän vaelsi."],[18,7,"Ja David otti ne kultaiset kilvet, jotka olivat Hadareserin palvelioilla, ja vei ne Jerusalemiin.","Ja David otti ne kultaiset kilvet, jotka olivat Hadareserin palvelioilla, ja vei ne Jerusalemiin."],[18,8,"Otti myös David Hadareserin kaupungeista Tibehatista ja Kunista juuri paljon vaskea, josta Salomo teki vaskimeren, patsaat ja vaskiastioita.","Otti myös David Hadareserin kaupungeista Tibehatista ja Kunista juuri paljon vaskea, josta Salomo teki vaskimeren, patsaat ja vaskiastioita."],[18,9,"Ja kuin Togu Hematin kuningas kuuli Davidin lyöneen kaiken Hadareserin Zoban kuninkaan sotajoukon,","Ja kuin Togu Hematin kuningas kuuli Davidin lyöneen kaiken Hadareserin Zoban kuninkaan sotajoukon,"],[18,10,"Lähetti hän poikansa Hadoramin kuningas Davidin tykö, tervehtimään häntä ystävällisesti ja siunaamaan häntä, että hän Hadareserin kanssa sotinut ja hänen lyönyt oli; sillä Togulla oli sota Hadareserin kanssa: niin myös kaikellaisia kultaisia, hopiaisia ja vaskisia asioita (lähetti hän).","Lähetti hän poikansa Hadoramin kuningas Davidin tykö, tervehtimään häntä ystävällisesti ja siunaamaan häntä, että hän Hadareserin kanssa sotinut ja hänen lyönyt oli; sillä Togulla oli sota Hadareserin kanssa: niin myös kaikellaisia kultaisia, hopiaisia ja vaskisia asioita (lähetti hän)."],[18,11,"Ja kuningas David pyhitti ne Herralle sen sen hopian ja kullan kanssa, jonka hän oli ottanut kaikilta pakanoilta, Edomilaisilta, Moabilaisilta, Ammonin lapsilta, Philistealaisilta ja Amalekilaisilta.","Ja kuningas David pyhitti ne Herralle sen sen hopian ja kullan kanssa, jonka hän oli ottanut kaikilta pakanoilta, Edomilaisilta, Moabilaisilta, Ammonin lapsilta, Philistealaisilta ja Amalekilaisilta."],[18,12,"Ja Abisai Zerujan poika löi Suolalaaksossa Edomilaisista kahdeksantoistakymmentä tuhatta,","Ja Abisai Zerujan poika löi Suolalaaksossa Edomilaisista kahdeksantoistakymmentä tuhatta,"],[18,13,"Ja asetti vartiat Edomiin, niin että kaikki Edomilaiset olivat Davidin alamaiset; sillä Herra autti Davidia, kuhunka ikänä hän vaelsi.","Ja asetti vartiat Edomiin, niin että kaikki Edomilaiset olivat Davidin alamaiset; sillä Herra autti Davidia, kuhunka ikänä hän vaelsi."],[18,14,"Ja niin hallitsi David kaiken Israelin, ja hän teki oikeuden ja hurskauden kaikelle kansallensa.","Ja niin hallitsi David kaiken Israelin, ja hän teki oikeuden ja hurskauden kaikelle kansallensa."],[18,15,"Joab Zerujan poika oli sotajoukon päällä, Josaphat Ahiludin poika oli kansleri.","Joab Zerujan poika oli sotajoukon päällä, Josaphat Ahiludin poika oli kansleri."],[18,16,"Zadok Ahitobin poika ja Abimelek Abjatarin poika olivat papit, Sausa oli kirjoittaja.","Zadok Ahitobin poika ja Abimelek Abjatarin poika olivat papit, Sausa oli kirjoittaja."],[18,17,"Benaja Jojadan poika oli Kretin ja Pletin päällä. Ja Davidin pojat olivat ensimäiset kuninkaan käsillä.","Benaja Jojadan poika oli Kretin ja Pletin päällä. Ja Davidin pojat olivat ensimäiset kuninkaan käsillä."],[19,1,"Sen jälkeen tapahtui, että Nahas Ammonin lasten kuningas kuoli, ja hänen poikansa tuli kuninkaaksi hänen siaansa.","Sen jälkeen tapahtui, että Nahas Ammonin lasten kuningas kuoli, ja hänen poikansa tuli kuninkaaksi hänen siaansa."],[19,2,"Niin David sanoi: minä osoitan laupiuden Hanunille Nahaksen pojalle; sillä hänen isänsä on tehnyt laupiuden minun kohtaani. Ja David lähetti sanansaattajat lohduttamaan häntä hänen isänsä tähden. Ja Davidin palveliat tulivat Ammonin lasten maalle Hanunin tykö, lohduttamaan häntä.","Niin David sanoi: minä osoitan laupiuden Hanunille Nahaksen pojalle; sillä hänen isänsä on tehnyt laupiuden minun kohtaani. Ja David lähetti sanansaattajat lohduttamaan häntä hänen isänsä tähden. Ja Davidin palveliat tulivat Ammonin lasten maalle Hanunin tykö, lohduttamaan häntä."],[19,3,"Niin sanoivat Ammonin lasten ylimmäiset Hanunille: luuletkos Davidin kunnioittavan isääs sinun silmäis edessä, että hän lähetti lohduttajat sinun tykös? ja eikö hänen palveliansa tulleet sinun tykös tutkistelemaan, kukistamaan ja vakoomaan maata?","Niin sanoivat Ammonin lasten ylimmäiset Hanunille: luuletkos Davidin kunnioittavan isääs sinun silmäis edessä, että hän lähetti lohduttajat sinun tykös? ja eikö hänen palveliansa tulleet sinun tykös tutkistelemaan, kukistamaan ja vakoomaan maata?"],[19,4,"Silloin otti Hanun Davidin palveliat, ajeli heidät ja leikkasi puolen heidän vaatteistansa liki kupeisiin asti, ja päästi heidät menemään.","Silloin otti Hanun Davidin palveliat, ajeli heidät ja leikkasi puolen heidän vaatteistansa liki kupeisiin asti, ja päästi heidät menemään."],[19,5,"Ja he menivät, ja se tehtiin Davidille tiettäväksi niistä miehistä. Ja hän lähetti heitä vastaan (sillä miehet olivat sangen suuresti häväistyt), ja kuningas sanoi: olkaat siihenasti Jerihossa kuin teidän partanne kasvaa, tulkaat sitte jälleen.","Ja he menivät, ja se tehtiin Davidille tiettäväksi niistä miehistä. Ja hän lähetti heitä vastaan (sillä miehet olivat sangen suuresti häväistyt), ja kuningas sanoi: olkaat siihenasti Jerihossa kuin teidän partanne kasvaa, tulkaat sitte jälleen."],[19,6,"Mutta kuin Ammonin lapset näkivät haisevansa Davidin edessä, lähetti Hanun ja Ammonin lapset tuhannen leiviskää hopiaa, palkataksensa vaunuja ja hevosmiehiä Mesopotamiasta ja Syrian Maekasta ja Sobasta.","Mutta kuin Ammonin lapset näkivät haisevansa Davidin edessä, lähetti Hanun ja Ammonin lapset tuhannen leiviskää hopiaa, palkataksensa vaunuja ja hevosmiehiä Mesopotamiasta ja Syrian Maekasta ja Sobasta."],[19,7,"Ja he palkkasivat kaksineljättäkymmentä tuhatta vaunua, ja Maekan kuninkaan väkinensä. He tulivat ja sioittivat itsensä Medban eteen. Ja Ammonin lapset kokoontuivat myös kaupungeistansa ja tulivat sotaan.","Ja he palkkasivat kaksineljättäkymmentä tuhatta vaunua, ja Maekan kuninkaan väkinensä. He tulivat ja sioittivat itsensä Medban eteen. Ja Ammonin lapset kokoontuivat myös kaupungeistansa ja tulivat sotaan."],[19,8,"Kuin David sen kuuli, lähetti hän Joabin ulos ja koko sankarein sotajoukon.","Kuin David sen kuuli, lähetti hän Joabin ulos ja koko sankarein sotajoukon."],[19,9,"Ja Ammonin lapset olivat lähteneet ja hankitsivat heitänsä sotaan kaupungin portin edessä; mutta kuninkaat, jotka tulleet olivat, olivat kedolla erinänsä.","Ja Ammonin lapset olivat lähteneet ja hankitsivat heitänsä sotaan kaupungin portin edessä; mutta kuninkaat, jotka tulleet olivat, olivat kedolla erinänsä."],[19,10,"Kuin Joab näki sodan sekä edessänsä että takanansa nousevan häntä vastaan, valitsi hän kaikki parhaat miehet Israelista ja asetti ne Syrialaisia vastaan.","Kuin Joab näki sodan sekä edessänsä että takanansa nousevan häntä vastaan, valitsi hän kaikki parhaat miehet Israelista ja asetti ne Syrialaisia vastaan."],[19,11,"Muun väen antoi hän veljensä Abisain käden alle, ja he varustivat itsensä Ammonin lapsia vastaan.","Muun väen antoi hän veljensä Abisain käden alle, ja he varustivat itsensä Ammonin lapsia vastaan."],[19,12,"Ja hän sanoi: jos Syrialaiset tulevat minua väkevämmäksi, niin tule minun avukseni; ja jos Ammonin lapset tulevat sinua väkevämmäksi, niin minä autan sinua.","Ja hän sanoi: jos Syrialaiset tulevat minua väkevämmäksi, niin tule minun avukseni; ja jos Ammonin lapset tulevat sinua väkevämmäksi, niin minä autan sinua."],[19,13,"Ole miehuullinen, ja olkaamme vahvat kansamme edestä ja Jumalamme kaupunkein edestä: mutta Herra tehköön niinkuin hänelle otollinen on!","Ole miehuullinen, ja olkaamme vahvat kansamme edestä ja Jumalamme kaupunkein edestä: mutta Herra tehköön niinkuin hänelle otollinen on!"],[19,14,"Ja Joab lähestyi sillä väellä, joka hänen kanssansa oli, sotimaan Syrialaisia vastaan; ja ne pakenivat häntä.","Ja Joab lähestyi sillä väellä, joka hänen kanssansa oli, sotimaan Syrialaisia vastaan; ja ne pakenivat häntä."],[19,15,"Kuin Ammonin lapset näkivät Syrialaisten pakenevan, pakenivat hekin Abisaita hänen veljeänsä ja menivät kaupunkiin; ja Joab meni Jerusalemiin.","Kuin Ammonin lapset näkivät Syrialaisten pakenevan, pakenivat hekin Abisaita hänen veljeänsä ja menivät kaupunkiin; ja Joab meni Jerusalemiin."],[19,16,"Kuin Syrialaiset näkivät itsensä Israelilta lyödyksi, lähettivät he sanansaattajat ja toivat Syrialaiset tuolta puolelta virtaa. Ja Sophak Hadareserin sodanpäämies meni heidän edellänsä.","Kuin Syrialaiset näkivät itsensä Israelilta lyödyksi, lähettivät he sanansaattajat ja toivat Syrialaiset tuolta puolelta virtaa. Ja Sophak Hadareserin sodanpäämies meni heidän edellänsä."],[19,17,"Kuin se oli Davidille sanottu, kokosi hän koko Israelin ja meni Jordanin ylitse. Ja kuin hän tuli heidän tykönsä, asettui hän heitä vastaan; ja David asetti itsensä Syrialaisia vastaan sotaan, ja ne sotivat hänen kanssansa.","Kuin se oli Davidille sanottu, kokosi hän koko Israelin ja meni Jordanin ylitse. Ja kuin hän tuli heidän tykönsä, asettui hän heitä vastaan; ja David asetti itsensä Syrialaisia vastaan sotaan, ja ne sotivat hänen kanssansa."],[19,18,"Mutta Syrialaiset pakenivat Israelia. Ja David tappoi Syrialaisista seitsemäntuhatta vaunua ja neljäkymmentä tuhatta jalkamiestä, hän tappoi myös Sophakin sodanpäämiehen.","Mutta Syrialaiset pakenivat Israelia. Ja David tappoi Syrialaisista seitsemäntuhatta vaunua ja neljäkymmentä tuhatta jalkamiestä, hän tappoi myös Sophakin sodanpäämiehen."],[19,19,"Ja koska Hadareserin palveliat näkivät itsensä lyödyksi Israelilta, tekivät he rauhan Davidin kanssa, ja olivat hänen palveliansa; ja Syrialaiset ei tahtoneet enää auttaa Ammonin lapsia.","Ja koska Hadareserin palveliat näkivät itsensä lyödyksi Israelilta, tekivät he rauhan Davidin kanssa, ja olivat hänen palveliansa; ja Syrialaiset ei tahtoneet enää auttaa Ammonin lapsia."],[20,1,"Ja kuin ajastaika kulunut oli siihen aikaan kuin kuninkaat lähtevät ulos, johdatti Joab sotajoukon ja hävitti Ammonin lasten maan, tuli ja piiritti Rabban; mutta David oli Jerusalemissa. Ja Joab löi Rabban ja kukisti sen.","Ja kuin ajastaika kulunut oli siihen aikaan kuin kuninkaat lähtevät ulos, johdatti Joab sotajoukon ja hävitti Ammonin lasten maan, tuli ja piiritti Rabban; mutta David oli Jerusalemissa. Ja Joab löi Rabban ja kukisti sen."],[20,2,"Ja David otti heidän kuninkaansa kruunun hänen päästänsä ja löysi sen painavan leiviskän kultaa, ja siinä oli kalliita kiviä, ja se pantiin Davidin päähän. Hän toi myös sangen paljon saalista kaupungista.","Ja David otti heidän kuninkaansa kruunun hänen päästänsä ja löysi sen painavan leiviskän kultaa, ja siinä oli kalliita kiviä, ja se pantiin Davidin päähän. Hän toi myös sangen paljon saalista kaupungista."],[20,3,"Mutta väen, joka siellä oli, toi hän ulos ja siirsi heidät sahoihin ja rautahaudoille ja kirvestöihin. Niin teki David kaikkein Ammonin lasten kaupunkein kanssa. Ja David palasi sitte kaiken väen kanssa Jerusalemiin.","Mutta väen, joka siellä oli, toi hän ulos ja siirsi heidät sahoihin ja rautahaudoille ja kirvestöihin. Niin teki David kaikkein Ammonin lasten kaupunkein kanssa. Ja David palasi sitte kaiken väen kanssa Jerusalemiin."],[20,4,"Sitte nousi sota taas Gaserissa Philistealaisten kanssa. Silloin löi Sibbekai Husatilainen Sippain, joka oli Raphan lapsia, ja he lannistettiin.","Sitte nousi sota taas Gaserissa Philistealaisten kanssa. Silloin löi Sibbekai Husatilainen Sippain, joka oli Raphan lapsia, ja he lannistettiin."],[20,5,"Ja vielä nousi sota Philistealaisten kanssa. Silloin löi Elhanan Jairin poika Lahemin Goljatin Gatilaisen veljen, jonka keihään varsi oli niinkuin kankaan puu.","Ja vielä nousi sota Philistealaisten kanssa. Silloin löi Elhanan Jairin poika Lahemin Goljatin Gatilaisen veljen, jonka keihään varsi oli niinkuin kankaan puu."],[20,6,"Ja taas nousi sota Gatissa; siellä oli suuri mies, ja hänellä oli kuusi sormea ja kuusi varvasta, se on neljäkolmattakymmentä. Ja hän myös oli syntynyt Raphan pojista.","Ja taas nousi sota Gatissa; siellä oli suuri mies, ja hänellä oli kuusi sormea ja kuusi varvasta, se on neljäkolmattakymmentä. Ja hän myös oli syntynyt Raphan pojista."],[20,7,"Ja hän pilkkasi Israelia; mutta Jonatan Simean poika, Davidin veljen poika, löi hänen.","Ja hän pilkkasi Israelia; mutta Jonatan Simean poika, Davidin veljen poika, löi hänen."],[20,8,"Nämät olivat syntyneet Raphalle Gatissa; ja he lankesivat Davidin käden ja hänen palveliainsa kätten kautta.","Nämät olivat syntyneet Raphalle Gatissa; ja he lankesivat Davidin käden ja hänen palveliainsa kätten kautta."],[21,1,"Ja saatana seisoi Israelia vastaan ja kehoitti Davidin lukemaan Israelia.","Ja saatana seisoi Israelia vastaan ja kehoitti Davidin lukemaan Israelia."],[21,2,"Ja David sanoi Joabille ja kansan ylimmäisille: menkäät ja lukekaat Israel Bersebasta Daniin saakka, ja tuokaat minulle, että minä tietäisin heidän lukunsa.","Ja David sanoi Joabille ja kansan ylimmäisille: menkäät ja lukekaat Israel Bersebasta Daniin saakka, ja tuokaat minulle, että minä tietäisin heidän lukunsa."],[21,3,"Joab sanoi: Herra enentäköön kansansa sata kertaa suuremmaksi kuin se nyt on. Herrani kuningas, eikö nämät kaikki ole herrani palveliat? miksi siis herrani kysyy sitä? miksi se tulis synniksi Israelille?","Joab sanoi: Herra enentäköön kansansa sata kertaa suuremmaksi kuin se nyt on. Herrani kuningas, eikö nämät kaikki ole herrani palveliat? miksi siis herrani kysyy sitä? miksi se tulis synniksi Israelille?"],[21,4,"Mutta kuninkaan sana voitti Joabin. Ja Joab meni ja vaelsi koko Israelin ympäri, ja tuli Jerusalemiin.","Mutta kuninkaan sana voitti Joabin. Ja Joab meni ja vaelsi koko Israelin ympäri, ja tuli Jerusalemiin."],[21,5,"Ja Joab antoi Davidille luetun kansan luvun: ja koko Israelissa oli yksitoistakymmentä kertaa satatuhatta miestä, jotka miekkaa ulos vetivät. Ja Juudassa neljäsataa tuhatta ja seitsemänkymmentä tuhatta miekan vetävää miestä.","Ja Joab antoi Davidille luetun kansan luvun: ja koko Israelissa oli yksitoistakymmentä kertaa satatuhatta miestä, jotka miekkaa ulos vetivät. Ja Juudassa neljäsataa tuhatta ja seitsemänkymmentä tuhatta miekan vetävää miestä."],[21,6,"Mutta Leviä ja BenJaminia ei hän näiden sekaan lukenut; sillä Joab kauhistui kuninkaan sanasta.","Mutta Leviä ja BenJaminia ei hän näiden sekaan lukenut; sillä Joab kauhistui kuninkaan sanasta."],[21,7,"Mutta asia oli paha Jumalan silmäin edessä; ja hän löi Israelin.","Mutta asia oli paha Jumalan silmäin edessä; ja hän löi Israelin."],[21,8,"Ja David sanoi Jumalalle: minä olen raskaasti syntiä tehnyt, että minä sen tehnyt olen: mutta ota palvelias vääryys pois; sillä minä olen sangen tyhmästi tehnyt.","Ja David sanoi Jumalalle: minä olen raskaasti syntiä tehnyt, että minä sen tehnyt olen: mutta ota palvelias vääryys pois; sillä minä olen sangen tyhmästi tehnyt."],[21,9,"Ja Herra puhui Gadille, Davidin näkiälle, sanoen:","Ja Herra puhui Gadille, Davidin näkiälle, sanoen:"],[21,10,"Mene ja puhu Davidille, sanoen: näin sanoo Herra: kolme minä panen sinun etees: valitse yksi niistä, ja minä teen sen sinulle.","Mene ja puhu Davidille, sanoen: näin sanoo Herra: kolme minä panen sinun etees: valitse yksi niistä, ja minä teen sen sinulle."],[21,11,"Ja kuin Gad tuli Davidin tykö, sanoi hän hänelle: näin sanoo Herra: valitse sinulles:","Ja kuin Gad tuli Davidin tykö, sanoi hän hänelle: näin sanoo Herra: valitse sinulles:"],[21,12,"Taikka kolme nälkävuotta, taikka kolmen kuukauden pako vihollistes edessä ja vainollises miekan edessä, että se on käsittävä sinun, eli kolmeksi päiväksi Herran miekka ja ruttotauti maalle, niin että Herran enkeli kadottaa kaikki Israelin rajoilla. Niin ajattele siis nyt, mitä minun pitää häntä vastaamaan, joka minun on lähettänyt.","Taikka kolme nälkävuotta, taikka kolmen kuukauden pako vihollistes edessä ja vainollises miekan edessä, että se on käsittävä sinun, eli kolmeksi päiväksi Herran miekka ja ruttotauti maalle, niin että Herran enkeli kadottaa kaikki Israelin rajoilla. Niin ajattele siis nyt, mitä minun pitää häntä vastaamaan, joka minun on lähettänyt."],[21,13,"David sanoi Gadille: minulla on suuri ahdistus; kuitenkin tahdon minä langeta Herran käsiin, sillä hänen laupiutensa on sangen suuri, en tahdo langeta ihmisten käsiin.","David sanoi Gadille: minulla on suuri ahdistus; kuitenkin tahdon minä langeta Herran käsiin, sillä hänen laupiutensa on sangen suuri, en tahdo langeta ihmisten käsiin."],[21,14,"Ja Herra antoi ruttotaudin tulla Israeliin, niin että Israelista lankesi seitsemänkymmentä tuhatta miestä.","Ja Herra antoi ruttotaudin tulla Israeliin, niin että Israelista lankesi seitsemänkymmentä tuhatta miestä."],[21,15,"Ja Jumala lähetti enkelin Jerusalemiin hukuttamaan sitä; ja hukuttaissa katsoi Herra siihen ja katui sitä pahaa, ja sanoi enkelille, joka hukutti: nyt on kyllä, pidä kätes ylös! Mutta Herran enkeli seisoi Ornanin Jebusilaisen riihen tykönä.","Ja Jumala lähetti enkelin Jerusalemiin hukuttamaan sitä; ja hukuttaissa katsoi Herra siihen ja katui sitä pahaa, ja sanoi enkelille, joka hukutti: nyt on kyllä, pidä kätes ylös! Mutta Herran enkeli seisoi Ornanin Jebusilaisen riihen tykönä."],[21,16,"Ja David nosti silmänsä ja sai nähdä Herran enkelin seisovan maan ja taivaan välillä, ja ulosvedetyn miekan hänen kädessänsä ojennetun Jerusalemin päälle. Niin lankesi David ja vanhimmat kasvoillensa, puetetut säkeillä.","Ja David nosti silmänsä ja sai nähdä Herran enkelin seisovan maan ja taivaan välillä, ja ulosvedetyn miekan hänen kädessänsä ojennetun Jerusalemin päälle. Niin lankesi David ja vanhimmat kasvoillensa, puetetut säkeillä."],[21,17,"Ja David sanoi Jumalalle: enkö minä se ole, joka annoin lukea kansan? minä se olen, joka syntiä tein ja aivan pahoin tein. Mitä nämät lampaat tehneet ovat? Herra Jumalani, anna kätes olla minun ja minun isäni huoneen päälle, ja ei sinun kansalles vaivaksi.","Ja David sanoi Jumalalle: enkö minä se ole, joka annoin lukea kansan? minä se olen, joka syntiä tein ja aivan pahoin tein. Mitä nämät lampaat tehneet ovat? Herra Jumalani, anna kätes olla minun ja minun isäni huoneen päälle, ja ei sinun kansalles vaivaksi."],[21,18,"Ja Herran enkeli sanoi Gadille että hän sanois Davidille, että David menis ja rakentais Herralle alttarin Ornanin Jebusilaisen riiheen.","Ja Herran enkeli sanoi Gadille että hän sanois Davidille, että David menis ja rakentais Herralle alttarin Ornanin Jebusilaisen riiheen."],[21,19,"Ja David meni Gadin sanan jälkeen, jonka hän Herran nimeen puhunut oli.","Ja David meni Gadin sanan jälkeen, jonka hän Herran nimeen puhunut oli."],[21,20,"Vaan kuin Ornan käänsi itsensä ja näki neljän poikansa kanssa enkelin, lymyttivät he heitänsä; sillä Ornan tappoi nisuja.","Vaan kuin Ornan käänsi itsensä ja näki neljän poikansa kanssa enkelin, lymyttivät he heitänsä; sillä Ornan tappoi nisuja."],[21,21,"Kuin David meni Ornanin tykö, näki Ornan ja havaitsi Davidin, ja meni riihestä ulos ja lankesi kasvoillensa Davidin eteen maahan.","Kuin David meni Ornanin tykö, näki Ornan ja havaitsi Davidin, ja meni riihestä ulos ja lankesi kasvoillensa Davidin eteen maahan."],[21,22,"Ja David sanoi Ornanille: anna minulle sen riihen sia, rakentaakseni siihen Herralle alttarin; anna se minulle täyden rahan edestä, että vitsaus lakkais kansasta.","Ja David sanoi Ornanille: anna minulle sen riihen sia, rakentaakseni siihen Herralle alttarin; anna se minulle täyden rahan edestä, että vitsaus lakkais kansasta."],[21,23,"Ja Ornan sanoi Davidille: ota sinulles ja tee, herrani kuningas, kuin sinulle kelpaa. Katso, minä annan myös härkiä polttouhriksi ja aseita puiksi, ja nisuja ruokauhriksi: kaikki minä annan.","Ja Ornan sanoi Davidille: ota sinulles ja tee, herrani kuningas, kuin sinulle kelpaa. Katso, minä annan myös härkiä polttouhriksi ja aseita puiksi, ja nisuja ruokauhriksi: kaikki minä annan."],[21,24,"Mutta kuningas David sanoi Ornanille: ei niin, vaan minä tahdon peräti ostaa sen täydellä rahalla; sillä en minä ota sitä, mikä sinun on, Herralle ja tee polttouhria maksamata.","Mutta kuningas David sanoi Ornanille: ei niin, vaan minä tahdon peräti ostaa sen täydellä rahalla; sillä en minä ota sitä, mikä sinun on, Herralle ja tee polttouhria maksamata."],[21,25,"Niin David antoi Ornanille sen sian edestä kuudensadan siklin painon kultaa.","Niin David antoi Ornanille sen sian edestä kuudensadan siklin painon kultaa."],[21,26,"Ja David rakensi siinä Herralle alttarin ja uhrasi polttouhria ja kiitosuhria, ja rukoili Herraa; ja hän kuuli hänen tulella taivaasta polttouhrin alttarilla.","Ja David rakensi siinä Herralle alttarin ja uhrasi polttouhria ja kiitosuhria, ja rukoili Herraa; ja hän kuuli hänen tulella taivaasta polttouhrin alttarilla."],[21,27,"Ja Herra sanoi enkelille, että hän pistäis miekkansa tuppeensa.","Ja Herra sanoi enkelille, että hän pistäis miekkansa tuppeensa."],[21,28,"Kuin David näki Herran kuulleeksi häntä Ornanin Jebusilaisen riihessä, uhrasi hän siellä.","Kuin David näki Herran kuulleeksi häntä Ornanin Jebusilaisen riihessä, uhrasi hän siellä."],[21,29,"Sillä Herran maja, jonka Moses oli tehnyt korvessa, ja polttouhrin alttari olivat silloin Gibeonin korkeudella.","Sillä Herran maja, jonka Moses oli tehnyt korvessa, ja polttouhrin alttari olivat silloin Gibeonin korkeudella."],[21,30,"Ja ei David taitanut mennä sen eteen kysymään Jumalaa; sillä hän oli peljästynyt Herran enkelin miekkaa.","Ja ei David taitanut mennä sen eteen kysymään Jumalaa; sillä hän oli peljästynyt Herran enkelin miekkaa."],[22,1,"Ja David sanoi: tässä pitää oleman Herran huone, ja tämä alttari Israelin polttouhria varten.","Ja David sanoi: tässä pitää oleman Herran huone, ja tämä alttari Israelin polttouhria varten."],[22,2,"Ja David käski koota muukalaiset, jotka Israelin maalla olivat: ne asetti hän kivien vuoliaksi, vuolemaan kiviä Jumalan huoneen rakennukseksi.","Ja David käski koota muukalaiset, jotka Israelin maalla olivat: ne asetti hän kivien vuoliaksi, vuolemaan kiviä Jumalan huoneen rakennukseksi."],[22,3,"Ja David valmisti paljon rautaa porttein ovien nauloiksi, ja mitä yhteen naulittaa tarvittiin, ja niin paljo vaskea, ettei se punnittaa taidettu;","Ja David valmisti paljon rautaa porttein ovien nauloiksi, ja mitä yhteen naulittaa tarvittiin, ja niin paljo vaskea, ettei se punnittaa taidettu;"],[22,4,"Ja sedripuita epäluvun; sillä Sidonilaiset ja Tyrolaiset toivat paljon sedripuita Davidille.","Ja sedripuita epäluvun; sillä Sidonilaiset ja Tyrolaiset toivat paljon sedripuita Davidille."],[22,5,"Ja David ajatteli: minun poikani Salomo on nuori ja heikko, mutta huone, joka pitää Herralle rakettaman, pitää niin suuri oleman, että sen nimi ja kunnia korotetaan kaikissa maissa; sentähden valmistan minä nyt hänelle varaksi. Näin valmisti David paljon ennen kuolemaansa.","Ja David ajatteli: minun poikani Salomo on nuori ja heikko, mutta huone, joka pitää Herralle rakettaman, pitää niin suuri oleman, että sen nimi ja kunnia korotetaan kaikissa maissa; sentähden valmistan minä nyt hänelle varaksi. Näin valmisti David paljon ennen kuolemaansa."],[22,6,"Ja hän kutsui poikansa Salomon ja käski hänen rakentaa huoneen Herralle Israelin Jumalalle.","Ja hän kutsui poikansa Salomon ja käski hänen rakentaa huoneen Herralle Israelin Jumalalle."],[22,7,"Ja David sanoi Salomolle: poikani, minun mieleni oli rakentaa Herralle minun Jumalalleni huonetta;","Ja David sanoi Salomolle: poikani, minun mieleni oli rakentaa Herralle minun Jumalalleni huonetta;"],[22,8,"Mutta Herran sana tuli minun tyköni ja sanoi: sinä olet paljon verta vuodattanut ja suurta sotaa pitänyt; sentähden ei sinun pidä rakentaman minun nimelleni huonetta, ettäs niin paljon verta olet vuodattanut maan päälle minun edessäni.","Mutta Herran sana tuli minun tyköni ja sanoi: sinä olet paljon verta vuodattanut ja suurta sotaa pitänyt; sentähden ei sinun pidä rakentaman minun nimelleni huonetta, ettäs niin paljon verta olet vuodattanut maan päälle minun edessäni."],[22,9,"Katso, poika, joka sinulle syntyy, on oleva levollinen mies; sillä minä annan levon kaikilta vihollisiltansa hänen ympärillänsä: sentähden pitää hänen nimensä oleman Salomo; sillä minä annan rauhan ja levon Israelille hänen elinaikanansa.","Katso, poika, joka sinulle syntyy, on oleva levollinen mies; sillä minä annan levon kaikilta vihollisiltansa hänen ympärillänsä: sentähden pitää hänen nimensä oleman Salomo; sillä minä annan rauhan ja levon Israelille hänen elinaikanansa."],[22,10,"Hänen pitää rakentaman minun nimelleni huoneen, hänen pitää oleman minun poikani, ja minä olen hänen isänsä: ja minä vahvistan hänen valtakuntansa istuimen Israelissa ijankaikkisesti.","Hänen pitää rakentaman minun nimelleni huoneen, hänen pitää oleman minun poikani, ja minä olen hänen isänsä: ja minä vahvistan hänen valtakuntansa istuimen Israelissa ijankaikkisesti."],[22,11,"Niin on nyt, minun poikani, Herra sinun kanssas: sinä menestyt ja rakennat Herralle sinun Jumalalles huoneen, niinkuin hän sinusta puhunut on.","Niin on nyt, minun poikani, Herra sinun kanssas: sinä menestyt ja rakennat Herralle sinun Jumalalles huoneen, niinkuin hän sinusta puhunut on."],[22,12,"Kuitenkin antakoon Herra sinulle ymmärryksen ja toimen, ja asettakoon sinun Israelia hallitsemaan ja pitämään Herran sinun Jumalas lain!","Kuitenkin antakoon Herra sinulle ymmärryksen ja toimen, ja asettakoon sinun Israelia hallitsemaan ja pitämään Herran sinun Jumalas lain!"],[22,13,"Silloin sinä menestyt, koskas ahkeroitset pitää niitä säätyjä ja oikeuksia, jotka Herra Moseksen kautta on käskenyt Israelille. Ole vahva ja hyvässä turvassa, älä pelkää, älä myös vavahdu.","Silloin sinä menestyt, koskas ahkeroitset pitää niitä säätyjä ja oikeuksia, jotka Herra Moseksen kautta on käskenyt Israelille. Ole vahva ja hyvässä turvassa, älä pelkää, älä myös vavahdu."],[22,14,"Katso, minä olen vaivassani valmistanut Herran huoneesen satatuhatta leiviskää kultaa ja tuhannen kertaa tuhannen leiviskää hopiaa, niin myös vaskea ja rautaa määrättömästi (sillä niitä on ylen paljo): minä olen myös toimittanut hirsiä ja kiviä, joihin vielä lisätä taidat.","Katso, minä olen vaivassani valmistanut Herran huoneesen satatuhatta leiviskää kultaa ja tuhannen kertaa tuhannen leiviskää hopiaa, niin myös vaskea ja rautaa määrättömästi (sillä niitä on ylen paljo): minä olen myös toimittanut hirsiä ja kiviä, joihin vielä lisätä taidat."],[22,15,"Niin on sinulla paljo työntekiöitä, kivenhakkaajia ja puuseppiä, ja kaikkia taitavia kaikkinaisiin töihin.","Niin on sinulla paljo työntekiöitä, kivenhakkaajia ja puuseppiä, ja kaikkia taitavia kaikkinaisiin töihin."],[22,16,"Kullalla, hopialla, vaskella ja raudalla ei ole lukua: nouse siis ja tee se, Herra on sinun kanssas.","Kullalla, hopialla, vaskella ja raudalla ei ole lukua: nouse siis ja tee se, Herra on sinun kanssas."],[22,17,"Ja David käski kaikkia Israelin ylimmäisiä auttamaan poikaansa Salomoa.","Ja David käski kaikkia Israelin ylimmäisiä auttamaan poikaansa Salomoa."],[22,18,"Eikö Herra teidän Jumalanne ole teidän kanssanne ja ole antanut teille levon joka taholta? Sillä hän on antanut maan asujamet minun käsiini, ja maa on voitettu Herran ja hänen kansansa edessä.","Eikö Herra teidän Jumalanne ole teidän kanssanne ja ole antanut teille levon joka taholta? Sillä hän on antanut maan asujamet minun käsiini, ja maa on voitettu Herran ja hänen kansansa edessä."],[22,19,"Sentähden antakaat sydämenne ja sielunne etsiä Herraa teidän Jumalaanne; nouskaat ja rakentakaat Herralle Jumalalle pyhä, kannettaa siihen Herran liitonarkki ja pyhät Jumalan astiat huoneesen, joka Herran nimeen rakennetaan.","Sentähden antakaat sydämenne ja sielunne etsiä Herraa teidän Jumalaanne; nouskaat ja rakentakaat Herralle Jumalalle pyhä, kannettaa siihen Herran liitonarkki ja pyhät Jumalan astiat huoneesen, joka Herran nimeen rakennetaan."],[23,1,"Kuin David oli vanha ja elämästä kyllänsä saanut, asetti hän poikansa Salomon Israelin kuninkaaksi,","Kuin David oli vanha ja elämästä kyllänsä saanut, asetti hän poikansa Salomon Israelin kuninkaaksi,"],[23,2,"Ja kokosi kaikki ylimmäiset Israelissa, ja papit ja Leviläiset,","Ja kokosi kaikki ylimmäiset Israelissa, ja papit ja Leviläiset,"],[23,3,"Että Leviläiset luettaisiin hamasta kolmestakymmenestä ajastajasta ja sen ylitse. Ja heidän lukunsa oli päästä päähän, väkeviä miehiä, kahdeksanneljättäkymmentä tuhatta,","Että Leviläiset luettaisiin hamasta kolmestakymmenestä ajastajasta ja sen ylitse. Ja heidän lukunsa oli päästä päähän, väkeviä miehiä, kahdeksanneljättäkymmentä tuhatta,"],[23,4,"Joista oli neljäkolmattakymmentä tuhatta teettäjää Herran huoneessa, ja kuusituhatta virkamiestä ja tuomaria;","Joista oli neljäkolmattakymmentä tuhatta teettäjää Herran huoneessa, ja kuusituhatta virkamiestä ja tuomaria;"],[23,5,"Ja neljätuhatta ovenvartiaa ja neljätuhatta niitä, jotka Herralle kiitosta veisasivat kanteleilla, jotka minä pannut olen kiitosta veisaamaan.","Ja neljätuhatta ovenvartiaa ja neljätuhatta niitä, jotka Herralle kiitosta veisasivat kanteleilla, jotka minä pannut olen kiitosta veisaamaan."],[23,6,"Ja David teki järjestyksen Levin lapsille, Gersonille, Kahatille ja Merarille.","Ja David teki järjestyksen Levin lapsille, Gersonille, Kahatille ja Merarille."],[23,7,"Gersonilaisia olivat Laedan ja Simei.","Gersonilaisia olivat Laedan ja Simei."],[23,8,"Laedanin lapset: ensimäinen Jehieli, Setam ja Joel, kolme;","Laedanin lapset: ensimäinen Jehieli, Setam ja Joel, kolme;"],[23,9,"Simein lapset: Salomit, Hasiel ja Haran, kolme. Nämät olivat Laedanin isäin ylimmäiset.","Simein lapset: Salomit, Hasiel ja Haran, kolme. Nämät olivat Laedanin isäin ylimmäiset."],[23,10,"Olivat myös nämät Simein lapset: Jahat, Sina, Jeus ja Beria. Nämät neljä olivat Simein lapset.","Olivat myös nämät Simein lapset: Jahat, Sina, Jeus ja Beria. Nämät neljä olivat Simein lapset."],[23,11,"Jahat oli ensimäinen, Sina toinen. Mutta Jeuksella ja Berialla ei ollut monta lasta, sentähden luettiin ne yhdeksi isän huoneeksi.","Jahat oli ensimäinen, Sina toinen. Mutta Jeuksella ja Berialla ei ollut monta lasta, sentähden luettiin ne yhdeksi isän huoneeksi."],[23,12,"Kahatin lapset: Amram, Jitshar, Hebron ja Ussiel, neljä.","Kahatin lapset: Amram, Jitshar, Hebron ja Ussiel, neljä."],[23,13,"Amramin lapset: Aaron ja Moses. Mutta Aaron eroitettiin, koska oli pyhitetty kaikkein pyhimmälle, hän ja hänen poikansa ijankaikkisesti, kantamaan suitsutusta Herran edessä, ja palvelemaan häntä, ja siunaamaan hänen nimeensä ijankaikkisesti.","Amramin lapset: Aaron ja Moses. Mutta Aaron eroitettiin, koska oli pyhitetty kaikkein pyhimmälle, hän ja hänen poikansa ijankaikkisesti, kantamaan suitsutusta Herran edessä, ja palvelemaan häntä, ja siunaamaan hänen nimeensä ijankaikkisesti."],[23,14,"Ja Moseksen Jumalan miehen lapset luettiin Leviläisten sukukuntain sekaan.","Ja Moseksen Jumalan miehen lapset luettiin Leviläisten sukukuntain sekaan."],[23,15,"Moseksen lapset olivat: Gersom ja Elieser.","Moseksen lapset olivat: Gersom ja Elieser."],[23,16,"Gersomin lapset: ensimäinen oli Sebuel.","Gersomin lapset: ensimäinen oli Sebuel."],[23,17,"Elieserin lapset: ensimäinen oli Rehabia. Ja Elieserillä ei ollut muita lapsia, vaan Rehabeamin lapsia oli paljon enempi.","Elieserin lapset: ensimäinen oli Rehabia. Ja Elieserillä ei ollut muita lapsia, vaan Rehabeamin lapsia oli paljon enempi."],[23,18,"Jitsharin lapset: Selomit ensimäinen.","Jitsharin lapset: Selomit ensimäinen."],[23,19,"Hebronin lapset: Jeria ensimäinen, Amaria toinen, Jahasiel kolmas ja Jakneam neljäs.","Hebronin lapset: Jeria ensimäinen, Amaria toinen, Jahasiel kolmas ja Jakneam neljäs."],[23,20,"Ussielin lapset: Miika ensimäinen ja Jissia toinen.","Ussielin lapset: Miika ensimäinen ja Jissia toinen."],[23,21,"Merarin lapset: Maheli ja Musi. Mahelin lapset: Eleasar ja Kis.","Merarin lapset: Maheli ja Musi. Mahelin lapset: Eleasar ja Kis."],[23,22,"Mutta Eleasar kuoli, ja ei ollut hänellä poikia, vaan tyttäriä, jotka heidän veljensä Kisin pojat naivat.","Mutta Eleasar kuoli, ja ei ollut hänellä poikia, vaan tyttäriä, jotka heidän veljensä Kisin pojat naivat."],[23,23,"Musin lapset: Maheli, Eder ja Jeremot, kolme.","Musin lapset: Maheli, Eder ja Jeremot, kolme."],[23,24,"Nämät ovat Levin lapset heidän isäinsä huoneen jälkeen, isäin päämiehet, jotka nimien luvun jälkeen päästä päähän luetut olivat, jotka tekivät viran töitä Herran huoneen palveluksessa, kahdenkymmenen ajastaikaisista ja sen ylitse.","Nämät ovat Levin lapset heidän isäinsä huoneen jälkeen, isäin päämiehet, jotka nimien luvun jälkeen päästä päähän luetut olivat, jotka tekivät viran töitä Herran huoneen palveluksessa, kahdenkymmenen ajastaikaisista ja sen ylitse."],[23,25,"Sillä David sanoi: Herra Israelin Jumala, joka on asuva Jerusalemissa ijankaikkisesti, on antanut kansallensa levon.","Sillä David sanoi: Herra Israelin Jumala, joka on asuva Jerusalemissa ijankaikkisesti, on antanut kansallensa levon."],[23,26,"Ja ei Leviläiset tarvinneet kantaa majaa kaikkein hänen kaluinsa kanssa palvelukseen.","Ja ei Leviläiset tarvinneet kantaa majaa kaikkein hänen kaluinsa kanssa palvelukseen."],[23,27,"Ja Levin lapset luettiin Davidin viimeisten sanain jälkeen Leviläisten sekaan, kahdenkymmenen vuotisista ja sen ylitse,","Ja Levin lapset luettiin Davidin viimeisten sanain jälkeen Leviläisten sekaan, kahdenkymmenen vuotisista ja sen ylitse,"],[23,28,"Että heidän piti seisoman Aaronin lasten sivussa palvelemassa Herran huoneessa, kartanoilla ja kammioissa, ja kaikkinaisissa pyhitetyn puhdistuksissa, ja kaikissa viran töissä Herran huoneessa;","Että heidän piti seisoman Aaronin lasten sivussa palvelemassa Herran huoneessa, kartanoilla ja kammioissa, ja kaikkinaisissa pyhitetyn puhdistuksissa, ja kaikissa viran töissä Herran huoneessa;"],[23,29,"Ja oleman näkyleipäin, sämpyläjauhoin, ruokauhrein, happamattomain kyrsäin, pannuin, halstarien ja kaikkein vaakain ja mittain päällä;","Ja oleman näkyleipäin, sämpyläjauhoin, ruokauhrein, happamattomain kyrsäin, pannuin, halstarien ja kaikkein vaakain ja mittain päällä;"],[23,30,"Ja seisoman joka aamulla, kiittämässä ja ylistämässä Herraa, niin myös ehtoolla,","Ja seisoman joka aamulla, kiittämässä ja ylistämässä Herraa, niin myös ehtoolla,"],[23,31,"Ja uhraamassa Herralle kaikkinaiset polttouhrit sabbateina, uudelle kuulla ja juhlapäivinä, luvun ja tavan jälkeen, alati Herran edessä,","Ja uhraamassa Herralle kaikkinaiset polttouhrit sabbateina, uudelle kuulla ja juhlapäivinä, luvun ja tavan jälkeen, alati Herran edessä,"],[23,32,"Ja ottamassa vaarin seurakunnan majasta ja pyhyyden vartiosta, ja Aaronin lasten heidän veljeinsä vartiosta, Herran huoneen palveluksessa.","Ja ottamassa vaarin seurakunnan majasta ja pyhyyden vartiosta, ja Aaronin lasten heidän veljeinsä vartiosta, Herran huoneen palveluksessa."],[24,1,"Mutta tämä oli Aaronin lasten järjestys: Aaronin pojat oli: Nadab, Abihu, Eleasar ja Itamar.","Mutta tämä oli Aaronin lasten järjestys: Aaronin pojat oli: Nadab, Abihu, Eleasar ja Itamar."],[24,2,"Mutta Nadab ja Abihu kuolivat isänsä edessä, ja ei heillä ollut lasta. Ja Eleasar ja Itamar tulivat papeiksi.","Mutta Nadab ja Abihu kuolivat isänsä edessä, ja ei heillä ollut lasta. Ja Eleasar ja Itamar tulivat papeiksi."],[24,3,"Ja David määräsi heitä näin: Zadokin Eleasarin lapsista ja Ahimelekin Itamarin lapsista, heidän virkansa jälkeen heidän palveluksessansa.","Ja David määräsi heitä näin: Zadokin Eleasarin lapsista ja Ahimelekin Itamarin lapsista, heidän virkansa jälkeen heidän palveluksessansa."],[24,4,"Ja usiammat väkevät päämiehet löydettiin Eleasarin kuin Itamarin lapsista, koska he heitä niin määräsivät: Eleasarin lapsista oli siellä kuusitoistakymmentä ylimmäistä heidän isäinsä huoneessa, ja kahdeksan Itamarin lapsista, heidän isäinsä huoneessa.","Ja usiammat väkevät päämiehet löydettiin Eleasarin kuin Itamarin lapsista, koska he heitä niin määräsivät: Eleasarin lapsista oli siellä kuusitoistakymmentä ylimmäistä heidän isäinsä huoneessa, ja kahdeksan Itamarin lapsista, heidän isäinsä huoneessa."],[24,5,"Ja he määräsivät heitä arvalla sekä näitä että niitä; sillä molemmat Eleasarin ja Itamarin lapset olivat päämiehet pyhässä ja päämiehet Jumalan edessä.","Ja he määräsivät heitä arvalla sekä näitä että niitä; sillä molemmat Eleasarin ja Itamarin lapset olivat päämiehet pyhässä ja päämiehet Jumalan edessä."],[24,6,"Ja Semaja kirjoittaja, Netaneelin poika Leviläisistä, kirjoitti heidät kuninkaan edessä, ja päämiesten ja papin Zadokin, ja Ahimelekin Abjatarin pojan, ja pappein ja Leviläisten, ja ylimmäisten isäin edessä: yksi isän huone otettiin Eleasarin edestä ja toinen otettiin sitte Itamarin edestä.","Ja Semaja kirjoittaja, Netaneelin poika Leviläisistä, kirjoitti heidät kuninkaan edessä, ja päämiesten ja papin Zadokin, ja Ahimelekin Abjatarin pojan, ja pappein ja Leviläisten, ja ylimmäisten isäin edessä: yksi isän huone otettiin Eleasarin edestä ja toinen otettiin sitte Itamarin edestä."],[24,7,"Ja ensimäinen arpa lankesi Jojaribin päälle, toinen Jedatjan,","Ja ensimäinen arpa lankesi Jojaribin päälle, toinen Jedatjan,"],[24,8,"Kolmas Harimin, neljäs Seorimin,","Kolmas Harimin, neljäs Seorimin,"],[24,9,"Viides Malkian, kuudes Mijamin,","Viides Malkian, kuudes Mijamin,"],[24,10,"Seitsemäs Hakkotsin, kahdeksas Abian,","Seitsemäs Hakkotsin, kahdeksas Abian,"],[24,11,"Yhdeksäs Jesuan, kymmenes Sekanian,","Yhdeksäs Jesuan, kymmenes Sekanian,"],[24,12,"Yksitoistakymmenes Eliasibin, kaksitoistakymmenes Jakimin,","Yksitoistakymmenes Eliasibin, kaksitoistakymmenes Jakimin,"],[24,13,"Kolmastoistakymmenes Huppan, neljästoistakymmenes Jesebabin,","Kolmastoistakymmenes Huppan, neljästoistakymmenes Jesebabin,"],[24,14,"Viidestoistakymmenes Bilgan, kuudestoistakymmenes Immerin,","Viidestoistakymmenes Bilgan, kuudestoistakymmenes Immerin,"],[24,15,"Seitsemästoistakymmenes Hesirin, kahdeksastoistakymmenes Happitsetsin,","Seitsemästoistakymmenes Hesirin, kahdeksastoistakymmenes Happitsetsin,"],[24,16,"Yhdeksästoistakymmenes Petahian, kahdeskymmenes Jeheskelin,","Yhdeksästoistakymmenes Petahian, kahdeskymmenes Jeheskelin,"],[24,17,"Ensimäinenkolmattakymmentä Jakinin, toinenkolmattakymmentä Gamulin,","Ensimäinenkolmattakymmentä Jakinin, toinenkolmattakymmentä Gamulin,"],[24,18,"Kolmaskolmattakymmentä Delajan, neljäskolmattakymmentä Maasian.","Kolmaskolmattakymmentä Delajan, neljäskolmattakymmentä Maasian."],[24,19,"Tämä on heidän järjestyksensä heidän virkansa jälkeen, menemään Herran huoneesen tapansa jälkeen, isänsä Aaronin käden alla; niinkuin Herra Israelin Jumala heidän oli käskenyt.","Tämä on heidän järjestyksensä heidän virkansa jälkeen, menemään Herran huoneesen tapansa jälkeen, isänsä Aaronin käden alla; niinkuin Herra Israelin Jumala heidän oli käskenyt."],[24,20,"Muiden Levin lasten seassa oli Amramin lapsista Subael, Subaelin lapsista Jehdeja.","Muiden Levin lasten seassa oli Amramin lapsista Subael, Subaelin lapsista Jehdeja."],[24,21,"Rehabian lapsista: Jissia oli heistä ensimäinen.","Rehabian lapsista: Jissia oli heistä ensimäinen."],[24,22,"Mutta Jitseharilaisista oli Selomot, Selomotin lapsista Jahat.","Mutta Jitseharilaisista oli Selomot, Selomotin lapsista Jahat."],[24,23,"(Hebronin lapset) Jerija ensimäinen, Amaria toinen, Jahasiel kolmas, Jekameam neljäs.","(Hebronin lapset) Jerija ensimäinen, Amaria toinen, Jahasiel kolmas, Jekameam neljäs."],[24,24,"Ussielin lapset: Miika. Miikan lapsista Samir.","Ussielin lapset: Miika. Miikan lapsista Samir."],[24,25,"Jesija oli Miikan veli; Jesijan lapsista Sakaria.","Jesija oli Miikan veli; Jesijan lapsista Sakaria."],[24,26,"Merarin lapset: Maheli ja Musi; Jaesijan hänen poikansa lapset.","Merarin lapset: Maheli ja Musi; Jaesijan hänen poikansa lapset."],[24,27,"Merarin lapset Jaesijasta, hänen poikansa oli Soham, Sakkur ja Ibri.","Merarin lapset Jaesijasta, hänen poikansa oli Soham, Sakkur ja Ibri."],[24,28,"Mutta Mahelilla oli Eleasar, ja hänellä ei ollut yhtään poikaa.","Mutta Mahelilla oli Eleasar, ja hänellä ei ollut yhtään poikaa."],[24,29,"Kisistä, Kisin lapset: Jerahmeel.","Kisistä, Kisin lapset: Jerahmeel."],[24,30,"Musin lapset: Maheli, Eder ja Jeremot. Ne ovat Leviläisten lapset heidän isäinsä huoneen jälkeen.","Musin lapset: Maheli, Eder ja Jeremot. Ne ovat Leviläisten lapset heidän isäinsä huoneen jälkeen."],[24,31,"Ja nämät myös heittivät arpaa veljeinsä Aaronin lasten kanssa kuningas Davidin edessä, ja Zadokin ja Ahimelekin, ja ylimmäisten isäin edessä, pappein ja Leviläisten seassa; ylimmäinen isäin seassa pienimmänkin veljensä kanssa.","Ja nämät myös heittivät arpaa veljeinsä Aaronin lasten kanssa kuningas Davidin edessä, ja Zadokin ja Ahimelekin, ja ylimmäisten isäin edessä, pappein ja Leviläisten seassa; ylimmäinen isäin seassa pienimmänkin veljensä kanssa."],[25,1,"Ja David sodanpäämiesten kanssa eroitti virkoihin Asaphin, Hemanin ja Jedutunin lapset, jotka propheterasivat harpuilla, psaltareilla ja symbaleilla. Ja he luettiin töihin heidän virkansa jälkeen.","Ja David sodanpäämiesten kanssa eroitti virkoihin Asaphin, Hemanin ja Jedutunin lapset, jotka propheterasivat harpuilla, psaltareilla ja symbaleilla. Ja he luettiin töihin heidän virkansa jälkeen."],[25,2,"Asaphin lapsista: Sakkur, Joseph, Netania, Asarela, Asaphin pojat, Asaphin käden alla, jotka ennustivat kuninkaan tykönä.","Asaphin lapsista: Sakkur, Joseph, Netania, Asarela, Asaphin pojat, Asaphin käden alla, jotka ennustivat kuninkaan tykönä."],[25,3,"Jedutunista, Jedutunin lapset: Gedalia, Zeri, Jesaja, Hasabia ja Mattitia, kuusi isänsä Jedutunin johdon alla harpuilla, jotka ennustivat, kiittivät ja ylistivät Herraa.","Jedutunista, Jedutunin lapset: Gedalia, Zeri, Jesaja, Hasabia ja Mattitia, kuusi isänsä Jedutunin johdon alla harpuilla, jotka ennustivat, kiittivät ja ylistivät Herraa."],[25,4,"Hemanista: Hemanin lapset, Bukkia, Mattania, Ussiel, Sebuel ja Jerimot, Hanania, Hanani, Eliata, Giddalti ja Romamtieser, Josbekaja, Malloti, Hotir, Mahasiot;","Hemanista: Hemanin lapset, Bukkia, Mattania, Ussiel, Sebuel ja Jerimot, Hanania, Hanani, Eliata, Giddalti ja Romamtieser, Josbekaja, Malloti, Hotir, Mahasiot;"],[25,5,"Nämät olivat kaikki Hemanin lapset, kuninkaan näkiän Jumalan sanassa, ylentämään sarvea; sillä Jumala oli antanut Hemanille neljätoistakymmentä poikaa ja kolme tytärtä.","Nämät olivat kaikki Hemanin lapset, kuninkaan näkiän Jumalan sanassa, ylentämään sarvea; sillä Jumala oli antanut Hemanille neljätoistakymmentä poikaa ja kolme tytärtä."],[25,6,"Nämät kaikki olivat isänsä käden alla, veisaamassa Herran huoneessa symbaleilla, psaltareilla ja harpuilla, Jumalan huoneen virassa, kuninkaan, Asaphin, Jedutunin ja Hemanin asetuksen jälkeen.","Nämät kaikki olivat isänsä käden alla, veisaamassa Herran huoneessa symbaleilla, psaltareilla ja harpuilla, Jumalan huoneen virassa, kuninkaan, Asaphin, Jedutunin ja Hemanin asetuksen jälkeen."],[25,7,"Ja heidän ja heidän veljeinsä luku kaikki yhteen, jotka olivat oppineet ja ymmärtäväiset Herran veisussa, oli kaksisataa ja kahdeksanyhdeksättäkymmentä.","Ja heidän ja heidän veljeinsä luku kaikki yhteen, jotka olivat oppineet ja ymmärtäväiset Herran veisussa, oli kaksisataa ja kahdeksanyhdeksättäkymmentä."],[25,8,"Ja heittivät arpaa vartioistansa niin pieni kuin suuri, ja oppinut niinkuin opetuslapsi.","Ja heittivät arpaa vartioistansa niin pieni kuin suuri, ja oppinut niinkuin opetuslapsi."],[25,9,"Ja ensimäinen arpa lankesi Asaphin Josephille, toinen Gedalialle ja hänen veljillensä ja pojillensa: ja heitä oli kaksitoistakymmentä:","Ja ensimäinen arpa lankesi Asaphin Josephille, toinen Gedalialle ja hänen veljillensä ja pojillensa: ja heitä oli kaksitoistakymmentä:"],[25,10,"Kolmas Sakkurin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kolmas Sakkurin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,11,"Neljäs Jitsrin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Neljäs Jitsrin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,12,"Viides Netanian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Viides Netanian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,13,"Kuudes Bukkian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kuudes Bukkian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,14,"Seitsemäs Jesarelan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Seitsemäs Jesarelan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,15,"Kahdeksas Jesaian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kahdeksas Jesaian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,16,"Yhdeksäs Mattanian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Yhdeksäs Mattanian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,17,"Kymmenes Simein, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kymmenes Simein, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,18,"Ensimäinentoistakymmentä Asareelin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Ensimäinentoistakymmentä Asareelin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,19,"Toinentoistakymmentä Hasabian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Toinentoistakymmentä Hasabian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,20,"Kolmastoistakymmentä Subaelin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kolmastoistakymmentä Subaelin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,21,"Neljästoistakymmentä Mattitjan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Neljästoistakymmentä Mattitjan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,22,"Viidestoistakymmentä Jeremotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Viidestoistakymmentä Jeremotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,23,"Kuudestoistakymmentä Hananian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kuudestoistakymmentä Hananian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,24,"Seitsemästoistakymmentä Josbekasan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Seitsemästoistakymmentä Josbekasan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,25,"Kahdeksastoistakymmentä Hananin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kahdeksastoistakymmentä Hananin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,26,"Yhdeksästoistakymmentä Mallotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Yhdeksästoistakymmentä Mallotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,27,"Kahdeskymmenes Elijatan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kahdeskymmenes Elijatan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,28,"Ensimäinenkolmattakymmentä Hotirin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Ensimäinenkolmattakymmentä Hotirin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,29,"Toinenkolmattakymmentä Giddaltin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Toinenkolmattakymmentä Giddaltin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,30,"Kolmaskolmattakymmentä Mahesjotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;","Kolmaskolmattakymmentä Mahesjotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;"],[25,31,"Neljäskolmattakymmentä Romamtieserin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä.","Neljäskolmattakymmentä Romamtieserin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä."],[26,1,"Ovenvartiain järjestyksessä: Korhilaisista oli Meselemia, Koren poika, Asaphin lapsista.","Ovenvartiain järjestyksessä: Korhilaisista oli Meselemia, Koren poika, Asaphin lapsista."],[26,2,"Meselemian lapset olivat nämät: hänen esikoisensa Sakaria, toinen Jediael, kolmas Sebadia, neljäs Jatniel,","Meselemian lapset olivat nämät: hänen esikoisensa Sakaria, toinen Jediael, kolmas Sebadia, neljäs Jatniel,"],[26,3,"Viides Elam, kuudes Johanan, seitsemäs Eljoenai.","Viides Elam, kuudes Johanan, seitsemäs Eljoenai."],[26,4,"Mutta Obededomin lapset olivat nämät: hänen esikoisensa Semaja, toinen Josabad, kolmas Joa, neljäs Sakar, viides Netaneel,","Mutta Obededomin lapset olivat nämät: hänen esikoisensa Semaja, toinen Josabad, kolmas Joa, neljäs Sakar, viides Netaneel,"],[26,5,"Kuudes Ammiel, seitsemäs Isaskar, kahdeksas Pegultai; sillä Jumala oli siunannut hänen.","Kuudes Ammiel, seitsemäs Isaskar, kahdeksas Pegultai; sillä Jumala oli siunannut hänen."],[26,6,"Ja hänen poikansa Semaja siitti myös poikia, jotka isänsä huoneessa hallitsivat; sillä he olivat väkevät sankarit.","Ja hänen poikansa Semaja siitti myös poikia, jotka isänsä huoneessa hallitsivat; sillä he olivat väkevät sankarit."],[26,7,"Semajan lapset: Otni, Rephael, Obed ja Elsabad, jonka veljet olivat väkevät miehet, Elihu ja Semakia.","Semajan lapset: Otni, Rephael, Obed ja Elsabad, jonka veljet olivat väkevät miehet, Elihu ja Semakia."],[26,8,"Nämät kaikki olivat Obededomin lapset, he ja heidän lapsensa ja veljensä olivat väkevät miehet virassa: kaksiseitsemättäkymmentä Obededomista.","Nämät kaikki olivat Obededomin lapset, he ja heidän lapsensa ja veljensä olivat väkevät miehet virassa: kaksiseitsemättäkymmentä Obededomista."],[26,9,"Meselemialla oli lapsia ja veljiä, väkeviä miehiä kahdeksantoistakymmentä.","Meselemialla oli lapsia ja veljiä, väkeviä miehiä kahdeksantoistakymmentä."],[26,10,"Mutta Hosalla Merarin lapsista oli poikia: kaikkein jaloin oli Simri, vaikka ei hän ollut esikoinen, kuitenkin asetti hänen isänsä hänen päämieheksi;","Mutta Hosalla Merarin lapsista oli poikia: kaikkein jaloin oli Simri, vaikka ei hän ollut esikoinen, kuitenkin asetti hänen isänsä hänen päämieheksi;"],[26,11,"Toinen Hilkia, kolmas Tebalia, neljäs Sakaria: kaikki Hosan lapset ja veljet kolmetoistakymmentä.","Toinen Hilkia, kolmas Tebalia, neljäs Sakaria: kaikki Hosan lapset ja veljet kolmetoistakymmentä."],[26,12,"Tämä on ovenvartiain järjestys väkeväin päämiesten seassa, vartioissa heidän veljeinsä kohdalla, palvelemaan Herran huoneessa.","Tämä on ovenvartiain järjestys väkeväin päämiesten seassa, vartioissa heidän veljeinsä kohdalla, palvelemaan Herran huoneessa."],[26,13,"Ja arpa oli heitetty pienten niinkuin suurtenkin välillä, heidän isäinsä huoneessa, jokaisen portin eteen.","Ja arpa oli heitetty pienten niinkuin suurtenkin välillä, heidän isäinsä huoneessa, jokaisen portin eteen."],[26,14,"Arpa itään päin lankesi Selemian päälle; mutta hänen poikansa Sakaria, joka toimellinen neuvossa oli, heitti arvan, ja hänen arpansa lankesi pohjaan päin;","Arpa itään päin lankesi Selemian päälle; mutta hänen poikansa Sakaria, joka toimellinen neuvossa oli, heitti arvan, ja hänen arpansa lankesi pohjaan päin;"],[26,15,"Mutta Obededomin etelään päin, ja hänen poikainsa Asuppimin huoneen tykö.","Mutta Obededomin etelään päin, ja hänen poikainsa Asuppimin huoneen tykö."],[26,16,"Ja Suppim ja Hosa saivat lännen puolelle, Salleketin portille, josta korkian ahteen päälle mennään, jossa vartiat seisovat toinen toistansa vastaan.","Ja Suppim ja Hosa saivat lännen puolelle, Salleketin portille, josta korkian ahteen päälle mennään, jossa vartiat seisovat toinen toistansa vastaan."],[26,17,"Itään päin oli kuusi Leviläistä, pohjaan päin neljä joka päivä, etelään päin neljä joka päivä, mutta Asuppimin tykönä kaksi ja kaksi;","Itään päin oli kuusi Leviläistä, pohjaan päin neljä joka päivä, etelään päin neljä joka päivä, mutta Asuppimin tykönä kaksi ja kaksi;"],[26,18,"Parbarin tykönä länteen päin neljä joka haarassa, ja kahdet Parbarin tykönä.","Parbarin tykönä länteen päin neljä joka haarassa, ja kahdet Parbarin tykönä."],[26,19,"Tämä on ovenvartiain järjestys, Korhilaisten ja Merarin lasten seassa.","Tämä on ovenvartiain järjestys, Korhilaisten ja Merarin lasten seassa."],[26,20,"Leviläisistä oli Ahia Jumalan huoneen tavarain päällä ja pyhyyden tavarain päällä;","Leviläisistä oli Ahia Jumalan huoneen tavarain päällä ja pyhyyden tavarain päällä;"],[26,21,"Laedanin lapset, Gersonin lapset Laedanista: Laedanin Gersonilaisen, isäin päämiehet Jehieliläiset;","Laedanin lapset, Gersonin lapset Laedanista: Laedanin Gersonilaisen, isäin päämiehet Jehieliläiset;"],[26,22,"Jehieliläisten lapset: Setam ja hänen veljensä Joel, Herran huoneen tavarain päällä;","Jehieliläisten lapset: Setam ja hänen veljensä Joel, Herran huoneen tavarain päällä;"],[26,23,"Amramilaisista, Jitseharilaisista, Hebronilaisista ja Ussielilaisista","Amramilaisista, Jitseharilaisista, Hebronilaisista ja Ussielilaisista"],[26,24,"Oli Sebuel Gersomin poika, Moseksen pojan poika, päämies tavarain päällä.","Oli Sebuel Gersomin poika, Moseksen pojan poika, päämies tavarain päällä."],[26,25,"Mutta hänen veljellänsä Elieserillä oli poika Rehabia, ja hänen poikansa Jesaja, hänen poikansa Joram, hänen poikansa Sikri, ja hänen poikansa Selomit.","Mutta hänen veljellänsä Elieserillä oli poika Rehabia, ja hänen poikansa Jesaja, hänen poikansa Joram, hänen poikansa Sikri, ja hänen poikansa Selomit."],[26,26,"Selomit ja hänen veljensä olivat kaikkein pyhäin tavarain päällä, jotka David kuningas oli pyhittänyt, ja ylimmäiset isät, tuhanten ja satain päämiehet sotajoukon päällä.","Selomit ja hänen veljensä olivat kaikkein pyhäin tavarain päällä, jotka David kuningas oli pyhittänyt, ja ylimmäiset isät, tuhanten ja satain päämiehet sotajoukon päällä."],[26,27,"Sodasta ja saaliista ovat he pyhittäneet Herran huoneen parannukseksi;","Sodasta ja saaliista ovat he pyhittäneet Herran huoneen parannukseksi;"],[26,28,"Kaikki myös mitä näkiä Samuel, ja Saul Kisin poika, ja Abner Nerin poika, ja Joab Zerujan poika olivat pyhittäneet, ja kaikki mitkä pyhitetyt olivat, olivat Selomitin ja hänen veljeinsä käden alla.","Kaikki myös mitä näkiä Samuel, ja Saul Kisin poika, ja Abner Nerin poika, ja Joab Zerujan poika olivat pyhittäneet, ja kaikki mitkä pyhitetyt olivat, olivat Selomitin ja hänen veljeinsä käden alla."],[26,29,"Jitseharilaisista olivat Kenania poikinensa asetetut ulkonaisen työn haltiaksi ja tuomariksi Israelissa;","Jitseharilaisista olivat Kenania poikinensa asetetut ulkonaisen työn haltiaksi ja tuomariksi Israelissa;"],[26,30,"Hebronilaisia Hasabia ja hänen veljensä, väkevät miehet, tuhannen ja seitsemänsataa, asetetut virkaan Israelissa, tuolla puolella Jordania länteen päin, kaikkinaisiin Herran asioihin ja kuninkaan palvelukseen.","Hebronilaisia Hasabia ja hänen veljensä, väkevät miehet, tuhannen ja seitsemänsataa, asetetut virkaan Israelissa, tuolla puolella Jordania länteen päin, kaikkinaisiin Herran asioihin ja kuninkaan palvelukseen."],[26,31,"Hebronilaisia oli myös Jerijah, Hebronilaisten päämies, heidän sukukuntainsa ja isäinsä seassa. Ja neljäntenäkymmenentenä kuningas Davidin valtakunnan vuonna etsittiin ja löydettiin heidän seassansa väkevät miehet Gileadin Jaeserissa.","Hebronilaisia oli myös Jerijah, Hebronilaisten päämies, heidän sukukuntainsa ja isäinsä seassa. Ja neljäntenäkymmenentenä kuningas Davidin valtakunnan vuonna etsittiin ja löydettiin heidän seassansa väkevät miehet Gileadin Jaeserissa."],[26,32,"Ja hänen veljensä olivat väkevät miehet, kaksituhatta ja seitsemänsataa isäin päämiehiä. Ja David kuningas asetti heitä Rubenilaisten, Gadilaisten ja puolen Manassen sukukunnan päälle, kaikkiin Jumalan ja kuninkaan asioihin.","Ja hänen veljensä olivat väkevät miehet, kaksituhatta ja seitsemänsataa isäin päämiehiä. Ja David kuningas asetti heitä Rubenilaisten, Gadilaisten ja puolen Manassen sukukunnan päälle, kaikkiin Jumalan ja kuninkaan asioihin."],[27,1,"Mutta Israelin lapset heidän lukunsa jälkeen olivat: isäin päämiehet, tuhanten ja satain ruhtinaat, ja virkamiehet, jotka ottivat kuninkaasta vaarin, heidän järjestyksensä jälkeen, vaeltamaan sinne ja tänne jokainen kuukautenansa, joka kuukautena ajastajassa; ja jokaisessa joukossa oli neljäkolmattakymmentä tuhatta.","Mutta Israelin lapset heidän lukunsa jälkeen olivat: isäin päämiehet, tuhanten ja satain ruhtinaat, ja virkamiehet, jotka ottivat kuninkaasta vaarin, heidän järjestyksensä jälkeen, vaeltamaan sinne ja tänne jokainen kuukautenansa, joka kuukautena ajastajassa; ja jokaisessa joukossa oli neljäkolmattakymmentä tuhatta."],[27,2,"Ensimäisen joukon päällä ensimäisenä kuukautena oli Jasobeam Saddielin poika, ja hänen joukossansa neljäkolmattakymmentä tuhatta.","Ensimäisen joukon päällä ensimäisenä kuukautena oli Jasobeam Saddielin poika, ja hänen joukossansa neljäkolmattakymmentä tuhatta."],[27,3,"Mutta Peretsin lapsista oli ylimmäinen kaikkein sodanpäämiesten päällä, ensimäisenä kuukautena.","Mutta Peretsin lapsista oli ylimmäinen kaikkein sodanpäämiesten päällä, ensimäisenä kuukautena."],[27,4,"Toisen kuukauden joukon päällä oli Dodai Ahohilainen, ja Miklot päämies hänen joukkonsa päällä, ja hänen joukossansa neljäkolmattakymmentä tuhatta.","Toisen kuukauden joukon päällä oli Dodai Ahohilainen, ja Miklot päämies hänen joukkonsa päällä, ja hänen joukossansa neljäkolmattakymmentä tuhatta."],[27,5,"Kolmannen joukon päämies kolmantena kuukautena oli Benaja papin Jojadan poika, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Kolmannen joukon päämies kolmantena kuukautena oli Benaja papin Jojadan poika, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,6,"Tämä on Benaja väkevä kolmenkymmenen seassa ja kolmenkymmenen päällä, ja hänen joukkonsa oli hänen poikansa Ammisabadin alla.","Tämä on Benaja väkevä kolmenkymmenen seassa ja kolmenkymmenen päällä, ja hänen joukkonsa oli hänen poikansa Ammisabadin alla."],[27,7,"Neljäs, neljäntenä kuukautena, oli Asahel Joabin veli, ja hänen jälkeensä Sebadia hänen poikansa, ja hänen joukossansa neljäkolmattakymmentä tuhatta.","Neljäs, neljäntenä kuukautena, oli Asahel Joabin veli, ja hänen jälkeensä Sebadia hänen poikansa, ja hänen joukossansa neljäkolmattakymmentä tuhatta."],[27,8,"Viides, viidentenä kuukautena, oli päämies Samehut Jesrahilainen, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Viides, viidentenä kuukautena, oli päämies Samehut Jesrahilainen, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,9,"Kuudes, kuudentena kuukautena, oli Ira Ikeksen Thekoalaisen poika, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Kuudes, kuudentena kuukautena, oli Ira Ikeksen Thekoalaisen poika, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,10,"Seitsemäs, seitsemäntenä kuukautena, oli Heles Pelonilainen Ephraimin lapsia, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Seitsemäs, seitsemäntenä kuukautena, oli Heles Pelonilainen Ephraimin lapsia, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,11,"Kahdeksas, kahdeksantena kuukautena, oli Sibbekai Hussatilainen Sarhilaisista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Kahdeksas, kahdeksantena kuukautena, oli Sibbekai Hussatilainen Sarhilaisista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,12,"Yhdeksäs, yhdeksäntenä kuukautena, oli Abieser Antotilainen Jeminin lapsista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Yhdeksäs, yhdeksäntenä kuukautena, oli Abieser Antotilainen Jeminin lapsista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,13,"Kymmenes, kymmenentenä kuukautena, oli Maherai Netophatilainen Sarhilaisista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Kymmenes, kymmenentenä kuukautena, oli Maherai Netophatilainen Sarhilaisista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,14,"Ensimäinentoistakymmentä, ensimäisenä kuukautena toistakymmentä, oli Benaja Pirtagonilainen Ephraimin lapsista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.","Ensimäinentoistakymmentä, ensimäisenä kuukautena toistakymmentä, oli Benaja Pirtagonilainen Ephraimin lapsista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta."],[27,15,"Toinentoistakymmentä, toisena kuukautena toistakymmentä, oli Heldai Netophatilainen Otnielista, ja hänen joukossansa neljäkolmattakymmentä tuhatta.","Toinentoistakymmentä, toisena kuukautena toistakymmentä, oli Heldai Netophatilainen Otnielista, ja hänen joukossansa neljäkolmattakymmentä tuhatta."],[27,16,"Israelin sukukuntain päällä: Rubenilaisten päämies oli Elieser Sikrin poika; Simeonilaisten seassa Sephatia Maekan poika;","Israelin sukukuntain päällä: Rubenilaisten päämies oli Elieser Sikrin poika; Simeonilaisten seassa Sephatia Maekan poika;"],[27,17,"Leviläisten seassa, Hasabia Kemuelin poika; Aronilaisten seassa Zadok;","Leviläisten seassa, Hasabia Kemuelin poika; Aronilaisten seassa Zadok;"],[27,18,"Juudan seassa, Elihu Davidin veljistä; Isaskarin seassa, Omri Mikaelin poika;","Juudan seassa, Elihu Davidin veljistä; Isaskarin seassa, Omri Mikaelin poika;"],[27,19,"Sebulonin seassa, Jismaja Obadian poika; Naphtalin seassa, Jerimot Asrielin poika;","Sebulonin seassa, Jismaja Obadian poika; Naphtalin seassa, Jerimot Asrielin poika;"],[27,20,"Ephraimin lasten seassa, Hosea Asasian poika; puolen Manassen sukukunnan seassa, Joel Pedajan poika;","Ephraimin lasten seassa, Hosea Asasian poika; puolen Manassen sukukunnan seassa, Joel Pedajan poika;"],[27,21,"Puolen Manassen sukukunnan seassa Gileadissa, Jiddo Sakarian poika; BenJaminin seassa, Jaasiel Abnerin poika;","Puolen Manassen sukukunnan seassa Gileadissa, Jiddo Sakarian poika; BenJaminin seassa, Jaasiel Abnerin poika;"],[27,22,"Danin seassa, Asareel Jerohamin poika. Nämät ovat Israelin sukukuntain päämiehet.","Danin seassa, Asareel Jerohamin poika. Nämät ovat Israelin sukukuntain päämiehet."],[27,23,"Mutta David ei lukenut niitä, jotka kahdenkymmenen vuotiset ja sitä nuoremmat olivat; sillä Herra oli luvannut enentää Israelin niinkuin tähdet taivaissa.","Mutta David ei lukenut niitä, jotka kahdenkymmenen vuotiset ja sitä nuoremmat olivat; sillä Herra oli luvannut enentää Israelin niinkuin tähdet taivaissa."],[27,24,"Mutta Joab Zerujan poika oli ruvennut lukemaan ja ei sitä täyttänyt, ja viha tuli siitä Israelin päälle: ja ei se luku tullut kuningas Davidin aikakirjaan.","Mutta Joab Zerujan poika oli ruvennut lukemaan ja ei sitä täyttänyt, ja viha tuli siitä Israelin päälle: ja ei se luku tullut kuningas Davidin aikakirjaan."],[27,25,"Kuninkaan tavarain päällä oli Asmavet Adielin poika, ja tavarain päällä, jotka olivat maalla, kaupungeissa, kylissä ja linnoissa, oli Jonatan Ussian poika.","Kuninkaan tavarain päällä oli Asmavet Adielin poika, ja tavarain päällä, jotka olivat maalla, kaupungeissa, kylissä ja linnoissa, oli Jonatan Ussian poika."],[27,26,"Talonpoikain päällä, jotka maata viljelivät, oli Esri Kelubin poika.","Talonpoikain päällä, jotka maata viljelivät, oli Esri Kelubin poika."],[27,27,"Viinamäkein päällä oli Simei Ramalainen; viinakellarein ja viinatavarain päällä Sabdi Siphmiläinen.","Viinamäkein päällä oli Simei Ramalainen; viinakellarein ja viinatavarain päällä Sabdi Siphmiläinen."],[27,28,"Öljypuiden ja metsäfikunapuiden päällä, jotka olivat laaksossa, oli BaalHanan Gadarilainen; öljytavarain päällä Joas.","Öljypuiden ja metsäfikunapuiden päällä, jotka olivat laaksossa, oli BaalHanan Gadarilainen; öljytavarain päällä Joas."],[27,29,"Laidunhärkäin päällä Saronissa oli Sitrai Saronilainen; mutta härkäin päällä laaksossa Saphat Adlain poika;","Laidunhärkäin päällä Saronissa oli Sitrai Saronilainen; mutta härkäin päällä laaksossa Saphat Adlain poika;"],[27,30,"Kamelein päällä Obil Ismaelilainen; aasein päällä Jehedia Meronotilainen;","Kamelein päällä Obil Ismaelilainen; aasein päällä Jehedia Meronotilainen;"],[27,31,"Lammasten päällä Jasis Hagarilainen: nämät kaikki olivat päämiehet kuningas Davidin omaisuuden päällä.","Lammasten päällä Jasis Hagarilainen: nämät kaikki olivat päämiehet kuningas Davidin omaisuuden päällä."],[27,32,"Mutta Davidin setä Jonatan oli neuvonantaja, toimellinen mies ja hyvin oppinut. Jehiel Hakmonin poika oli kuninkaan lasten tykönä.","Mutta Davidin setä Jonatan oli neuvonantaja, toimellinen mies ja hyvin oppinut. Jehiel Hakmonin poika oli kuninkaan lasten tykönä."],[27,33,"Ahitophel oli myös kuninkaan neuvonantaja; Husai Arkilainen oli kuninkaan ystävä.","Ahitophel oli myös kuninkaan neuvonantaja; Husai Arkilainen oli kuninkaan ystävä."],[27,34,"Ja Ahitophelin jälkeen oli Jojada Benajan poika ja Ebjatar. Mutta Joab oli kuninkaan sodan päämies.","Ja Ahitophelin jälkeen oli Jojada Benajan poika ja Ebjatar. Mutta Joab oli kuninkaan sodan päämies."],[28,1,"Ja David kokosi kaikki Israelin päämiehet, sukukuntain päämiehet ja niiden joukkoin päämiehet, jotka kuningasta palvelivat, päämiehet tuhanten ja satain päällä, kuninkaan ja hänen poikainsa omaisuuden ja tavaran päämiehet kamaripalveliain kanssa, ja uljaat ja kaikki väkevät sotamiehet Jerusalemiin.","Ja David kokosi kaikki Israelin päämiehet, sukukuntain päämiehet ja niiden joukkoin päämiehet, jotka kuningasta palvelivat, päämiehet tuhanten ja satain päällä, kuninkaan ja hänen poikainsa omaisuuden ja tavaran päämiehet kamaripalveliain kanssa, ja uljaat ja kaikki väkevät sotamiehet Jerusalemiin."],[28,2,"Ja kuningas David nousi seisoalle ja sanoi: veljeni ja kansani, kuulkaat minua: minä olen aikonut rakentaa Herran liitonarkin lepohuoneen ja Jumalamme jalkain astinlaudan, ja olen valmistanut rakennuksen varaa.","Ja kuningas David nousi seisoalle ja sanoi: veljeni ja kansani, kuulkaat minua: minä olen aikonut rakentaa Herran liitonarkin lepohuoneen ja Jumalamme jalkain astinlaudan, ja olen valmistanut rakennuksen varaa."],[28,3,"Mutta Jumala sanoi minulle: ei sinun pidä rakentaman nimelleni huonetta; sillä sinä olet sotamies ja olet paljon verta vuodattanut.","Mutta Jumala sanoi minulle: ei sinun pidä rakentaman nimelleni huonetta; sillä sinä olet sotamies ja olet paljon verta vuodattanut."],[28,4,"Herra Israelin Jumala on valinnut minun koko isäni huoneesta Israelin kuninkaaksi ijankaikkisesti; sillä hän on Juudan valinnut hallitsiaksi, ja Juudan huoneesta minun isäni huoneen; ja minä olen ollut isäni lapsista hänelle niin kelvollinen, että hän teki minun koko Israelin kuninkaaksi.","Herra Israelin Jumala on valinnut minun koko isäni huoneesta Israelin kuninkaaksi ijankaikkisesti; sillä hän on Juudan valinnut hallitsiaksi, ja Juudan huoneesta minun isäni huoneen; ja minä olen ollut isäni lapsista hänelle niin kelvollinen, että hän teki minun koko Israelin kuninkaaksi."],[28,5,"Ja kaikkein poikaini seassa (sillä Herra on antanut minulle monta poikaa) on hän valinnut poikani Salomon istumaan Herran valtakunnan istuimella Israelin ylitse,","Ja kaikkein poikaini seassa (sillä Herra on antanut minulle monta poikaa) on hän valinnut poikani Salomon istumaan Herran valtakunnan istuimella Israelin ylitse,"],[28,6,"Ja on puhunut minulle: poikas Salomo pitää rakentaman minun huoneeni ja kartanoni; sillä minä olen hänen valinnut pojakseni, ja minä olen hänen isänsä,","Ja on puhunut minulle: poikas Salomo pitää rakentaman minun huoneeni ja kartanoni; sillä minä olen hänen valinnut pojakseni, ja minä olen hänen isänsä,"],[28,7,"Ja vahvistan hänen valtakuntansa ijankaikkisesti, ja hän vahvana pysyy, pitäen minun käskyni ja oikeuteni, niinkuin tänäpänäkin;","Ja vahvistan hänen valtakuntansa ijankaikkisesti, ja hän vahvana pysyy, pitäen minun käskyni ja oikeuteni, niinkuin tänäpänäkin;"],[28,8,"Nyt siis, koko Herran kokouksen Israelin silmäin edessä ja meidän Jumalamme korvissa, pitäkäät ja tutkistelkaat kaikki Herran teidän Jumalanne käskyt, että te omistaisitte tämän hyvän maan ja jättäisitte sen teidän lapsillenne perinnöksi teidän jälkeenne ijankaikkisesti.","Nyt siis, koko Herran kokouksen Israelin silmäin edessä ja meidän Jumalamme korvissa, pitäkäät ja tutkistelkaat kaikki Herran teidän Jumalanne käskyt, että te omistaisitte tämän hyvän maan ja jättäisitte sen teidän lapsillenne perinnöksi teidän jälkeenne ijankaikkisesti."],[28,9,"Ja sinä, poikani Salomo! tunne isäs Jumala ja palvele häntä kaikesta sydämestä ja hyvällä mielellä; sillä Herra tutkistelee kaikki sydämet ja ymmärtää kaikkein ajatusten aikomiset; jos etsit häntä, niin sinä löydät hänen; jos hylkäät hänen, niin hän sinun hylkää ijankaikkisesti.","Ja sinä, poikani Salomo! tunne isäs Jumala ja palvele häntä kaikesta sydämestä ja hyvällä mielellä; sillä Herra tutkistelee kaikki sydämet ja ymmärtää kaikkein ajatusten aikomiset; jos etsit häntä, niin sinä löydät hänen; jos hylkäät hänen, niin hän sinun hylkää ijankaikkisesti."],[28,10,"Niin katso nyt, koska Jumala on sinun valinnut rakentamaan huonetta pyhäksi siaksi: ole vahva ja tee niin.","Niin katso nyt, koska Jumala on sinun valinnut rakentamaan huonetta pyhäksi siaksi: ole vahva ja tee niin."],[28,11,"Ja David antoi pojallensa Salomolle pihan muodon ja hänen huonettensa ja tavarahuoneiden, salien ja sisimäisten kammioin, ja armoistuimen huoneen muodon,","Ja David antoi pojallensa Salomolle pihan muodon ja hänen huonettensa ja tavarahuoneiden, salien ja sisimäisten kammioin, ja armoistuimen huoneen muodon,"],[28,12,"Ja vielä kaikkein niiden muodon, jotka hänen mielessänsä olivat, Herran huoneen kartanoista ja kaikista huoneista ympäri, Jumalan huoneen tavaroista ja pyhitetyistä tavaroista,","Ja vielä kaikkein niiden muodon, jotka hänen mielessänsä olivat, Herran huoneen kartanoista ja kaikista huoneista ympäri, Jumalan huoneen tavaroista ja pyhitetyistä tavaroista,"],[28,13,"Pappein ja Leviläisten järjestyksen, ja kaikkein Herran huoneen virkain töiden, ja kaikkein astiain muodon, Herran huoneen palveluksessa.","Pappein ja Leviläisten järjestyksen, ja kaikkein Herran huoneen virkain töiden, ja kaikkein astiain muodon, Herran huoneen palveluksessa."],[28,14,"Kultaa hän antoi kullan painon jälkeen kaikkinaisiksi astioiksi joka virassa, antoi myös hopiaa jokaiseen hopia-astiaan painonsa, jokaisen virka-astian jälkeen;","Kultaa hän antoi kullan painon jälkeen kaikkinaisiksi astioiksi joka virassa, antoi myös hopiaa jokaiseen hopia-astiaan painonsa, jokaisen virka-astian jälkeen;"],[28,15,"Ja kultaa kultaisille kynttiläjaloille ja kultaisille lampuille, jokaiselle kynttiläjalalle ja hänen lampullensa hänen painonsa. Niin antoi hän myös hopiaa hopiakynttiläjaloille ja heidän heidän lampuillensa, jokaisen kynttiläjalan viran jälkeen;","Ja kultaa kultaisille kynttiläjaloille ja kultaisille lampuille, jokaiselle kynttiläjalalle ja hänen lampullensa hänen painonsa. Niin antoi hän myös hopiaa hopiakynttiläjaloille ja heidän heidän lampuillensa, jokaisen kynttiläjalan viran jälkeen;"],[28,16,"Niin myös kultaa näkyleipäin pöydiksi, jokaiselle pöydälle painonsa, ja myös hopiaa hopiapöydiksi;","Niin myös kultaa näkyleipäin pöydiksi, jokaiselle pöydälle painonsa, ja myös hopiaa hopiapöydiksi;"],[28,17,"Ja puhdasta kultaa kolmihaaraisiksi hangoiksi, maljoiksi ja kannuiksi: kultaa myös kultapikareiksi, jokaiselle pikarille painonsa, hopiaa hopiapikareiksi, jokaiselle pikarille painonsa:","Ja puhdasta kultaa kolmihaaraisiksi hangoiksi, maljoiksi ja kannuiksi: kultaa myös kultapikareiksi, jokaiselle pikarille painonsa, hopiaa hopiapikareiksi, jokaiselle pikarille painonsa:"],[28,18,"Ja savu-alttariksi kaikkein puhtaimpaa kultaa painonsa: ja kultaisten Kerubimein ratasten muodon, jotka levittivät siipensä ja peittivät Herran liitonarkin.","Ja savu-alttariksi kaikkein puhtaimpaa kultaa painonsa: ja kultaisten Kerubimein ratasten muodon, jotka levittivät siipensä ja peittivät Herran liitonarkin."],[28,19,"Kaikki nämät kirjoitettuina Herran kädeltä, joka minun antoi ymmärtää kaikkein töiden muodon.","Kaikki nämät kirjoitettuina Herran kädeltä, joka minun antoi ymmärtää kaikkein töiden muodon."],[28,20,"Ja David sanoi pojallensa Salomolle: ole vahva ja miehuullinen, ja tee niin, älä pelkää, älä myös hämmästy; sillä Herra Jumala minun Jumalani on sinun kanssas, ja ei ota kättänsä pois sinulta, eikä hylkää sinua, siihenasti ettäs kaiken viran työt Jumalan huoneessa päättänyt olet.","Ja David sanoi pojallensa Salomolle: ole vahva ja miehuullinen, ja tee niin, älä pelkää, älä myös hämmästy; sillä Herra Jumala minun Jumalani on sinun kanssas, ja ei ota kättänsä pois sinulta, eikä hylkää sinua, siihenasti ettäs kaiken viran työt Jumalan huoneessa päättänyt olet."],[28,21,"Ja katso, pappein ja Leviläisten järjestykset pitää oleman kaikessa Jumalan huoneen palveluksessa ja sinun kanssas on hyväntahtoisia ja ymmärtäväisiä kaikkeen virkaan; niin myös päämiehet ja kaikki kansa, kaikissa sinun asioissas.","Ja katso, pappein ja Leviläisten järjestykset pitää oleman kaikessa Jumalan huoneen palveluksessa ja sinun kanssas on hyväntahtoisia ja ymmärtäväisiä kaikkeen virkaan; niin myös päämiehet ja kaikki kansa, kaikissa sinun asioissas."],[29,1,"Ja kuningas David sanoi koko joukolle: Salomon, yhden minun pojistani, on Jumala valinnut, joka vielä nuori ja heikko on, mutta työ on suuri; sillä ei se ole ihmisen asumasia, vaan Herran Jumalan.","Ja kuningas David sanoi koko joukolle: Salomon, yhden minun pojistani, on Jumala valinnut, joka vielä nuori ja heikko on, mutta työ on suuri; sillä ei se ole ihmisen asumasia, vaan Herran Jumalan."],[29,2,"Ja minä olen kaikesta voimastani valmistanut Jumalani huoneelle kultaa kultakaluiksi, hopiaa hopiaisiksi, vaskea vaskisiksi, rautaa rautaisiksi, puita puuaseiksi, ja onikin kiviä, kiinniliitetyitä rubineja, monenpilkullisia kiviä, ja kaikkinaisia kalliita kiviä, ja marmorikiviä sangen paljon.","Ja minä olen kaikesta voimastani valmistanut Jumalani huoneelle kultaa kultakaluiksi, hopiaa hopiaisiksi, vaskea vaskisiksi, rautaa rautaisiksi, puita puuaseiksi, ja onikin kiviä, kiinniliitetyitä rubineja, monenpilkullisia kiviä, ja kaikkinaisia kalliita kiviä, ja marmorikiviä sangen paljon."],[29,3,"Ja olen vielä antanut hyvästä tahdostani Jumalani huoneesen mitä minun omani on, kultaa ja hopiaa, ylitse sen kaiken, minkä minä olen valmistanut pyhän huoneesen:","Ja olen vielä antanut hyvästä tahdostani Jumalani huoneesen mitä minun omani on, kultaa ja hopiaa, ylitse sen kaiken, minkä minä olen valmistanut pyhän huoneesen:"],[29,4,"Kolmetuhatta leiviskää ophirin kultaa ja seitsemäntuhatta leiviskää puhdasta hopiaa, silata huonetten seiniä,","Kolmetuhatta leiviskää ophirin kultaa ja seitsemäntuhatta leiviskää puhdasta hopiaa, silata huonetten seiniä,"],[29,5,"Kultaa kultaisiin, ja hopiaa hopiaisiin ja kaikkinaisiin töihin, tekiäin käden kautta. Ja kuka on hyväntahtoinen täyttämään kättänsä tänäpänä Herralle?","Kultaa kultaisiin, ja hopiaa hopiaisiin ja kaikkinaisiin töihin, tekiäin käden kautta. Ja kuka on hyväntahtoinen täyttämään kättänsä tänäpänä Herralle?"],[29,6,"Niin isäin päämiehet ja Israelin sukukuntain päämiehet, niin myös tuhanten ja satain päämiehet, ja kuninkaan töiden päämiehet olivat hyväntahtoiset,","Niin isäin päämiehet ja Israelin sukukuntain päämiehet, niin myös tuhanten ja satain päämiehet, ja kuninkaan töiden päämiehet olivat hyväntahtoiset,"],[29,7,"Ja antoivat Jumalan huoneen palvelukseen viisituhatta leiviskää kultaa, ja kymmenentuhatta kultapenninkiä, ja kymmenentuhatta leiviskää hopiaa, kahdeksantoistakymmentä tuhatta leiviskää vaskea, ja satatuhatta leiviskää rautaa.","Ja antoivat Jumalan huoneen palvelukseen viisituhatta leiviskää kultaa, ja kymmenentuhatta kultapenninkiä, ja kymmenentuhatta leiviskää hopiaa, kahdeksantoistakymmentä tuhatta leiviskää vaskea, ja satatuhatta leiviskää rautaa."],[29,8,"Ja joiden tyköä kiviä löydettiin, ne he antoivat Herran huoneen tavaroihin, Jehielin Gersonilaisen käden alle.","Ja joiden tyköä kiviä löydettiin, ne he antoivat Herran huoneen tavaroihin, Jehielin Gersonilaisen käden alle."],[29,9,"Ja kansa iloitsi, että he niin hyvästä tahdosta antoivat; sillä he antoivat Herralle vaasta sydämestä, vapaasta tahdostansa. Ja kuningas David oli myös sangen suuresti iloissansa.","Ja kansa iloitsi, että he niin hyvästä tahdosta antoivat; sillä he antoivat Herralle vaasta sydämestä, vapaasta tahdostansa. Ja kuningas David oli myös sangen suuresti iloissansa."],[29,10,"Ja David kiitti Herraa kaiken kansan edestä ja sanoi: kiitetty ole sinä Herra, Israelin meidän isämme Jumala ijankaikkisesta ijankaikkiseen!","Ja David kiitti Herraa kaiken kansan edestä ja sanoi: kiitetty ole sinä Herra, Israelin meidän isämme Jumala ijankaikkisesta ijankaikkiseen!"],[29,11,"Sillä sinun, Herra, on suuruus, ja voima, ja kunnia, ja voitto, ja kiitos; sillä kaikki, mitä taivaassa ja maan päällä on, se on sinun. Sinun Herra on valtakunta, ja sinä olet korotettu kaikkein päämiesten ylitse.","Sillä sinun, Herra, on suuruus, ja voima, ja kunnia, ja voitto, ja kiitos; sillä kaikki, mitä taivaassa ja maan päällä on, se on sinun. Sinun Herra on valtakunta, ja sinä olet korotettu kaikkein päämiesten ylitse."],[29,12,"Rikkaus ja kunnia ovat sinun edessäs, ja sinä hallitset kaikki kappaleet, ja sinun kädessäs on väki ja voima: sinun kädessäs on kaikki suureksi ja väkeväksi tehdä.","Rikkaus ja kunnia ovat sinun edessäs, ja sinä hallitset kaikki kappaleet, ja sinun kädessäs on väki ja voima: sinun kädessäs on kaikki suureksi ja väkeväksi tehdä."],[29,13,"Ja nyt meidän Jumalamme! me kiitämme sinua, ja ylistämme sinun kunnias nimeä.","Ja nyt meidän Jumalamme! me kiitämme sinua, ja ylistämme sinun kunnias nimeä."],[29,14,"Sillä mikä minä olen, ja mikä on minun kansani, että me olemme niin paljon voineet antaa hyvällä mielellä, niinkuin se nyt tapahtuu? sillä se on kaikki sinulta tullut, ja sinun kädestäs olemme me antaneet sinulle sen.","Sillä mikä minä olen, ja mikä on minun kansani, että me olemme niin paljon voineet antaa hyvällä mielellä, niinkuin se nyt tapahtuu? sillä se on kaikki sinulta tullut, ja sinun kädestäs olemme me antaneet sinulle sen."],[29,15,"Sillä me olemme muukalaiset ja oudot sinun edessäs, niinkuin kaikki meidän isämmekin: meidän ikämme on maan päällä niinkuin varjo, ja ei täällä ole yhtään viipymystä.","Sillä me olemme muukalaiset ja oudot sinun edessäs, niinkuin kaikki meidän isämmekin: meidän ikämme on maan päällä niinkuin varjo, ja ei täällä ole yhtään viipymystä."],[29,16,"Herra meidän Jumalamme! kaikki tämä kalun paljous, jonka me olemme valmistaneet sinun pyhälle nimelles rakentaa huonetta, se on kaikki tullut sinun kädestäs, ja ne ovat kaikki sinun.","Herra meidän Jumalamme! kaikki tämä kalun paljous, jonka me olemme valmistaneet sinun pyhälle nimelles rakentaa huonetta, se on kaikki tullut sinun kädestäs, ja ne ovat kaikki sinun."],[29,17,"Minun Jumalani! minä tiedän, ettäs tutkistelet sydämen ja tahdot vakuutta. Sentähden olen myös minä kaikki nämät yksivakaisesta sydämestä antanut vapaalla mielellä. Ja minä näin nyt ilolla tämän sinun kansas, joka tässä on, että se on hyvällä mielellä sinulle antanut.","Minun Jumalani! minä tiedän, ettäs tutkistelet sydämen ja tahdot vakuutta. Sentähden olen myös minä kaikki nämät yksivakaisesta sydämestä antanut vapaalla mielellä. Ja minä näin nyt ilolla tämän sinun kansas, joka tässä on, että se on hyvällä mielellä sinulle antanut."],[29,18,"Herra meidän isäimme Abrahamin, Isaakin ja Israelin Jumala! pidä ijankaikkisesti tämänkaltainen mieli ja tahto kansas sydämessä, ja valmista heidän sydämensä sinun tykös.","Herra meidän isäimme Abrahamin, Isaakin ja Israelin Jumala! pidä ijankaikkisesti tämänkaltainen mieli ja tahto kansas sydämessä, ja valmista heidän sydämensä sinun tykös."],[29,19,"Ja pojalleni Salomolle anna täydellinen sydän pitämään sinun käskys, todistukses ja säätys, niin että hän ne kaikki tekis ja rakentais tämän asuinsian, jonka minä olen valmistanut.","Ja pojalleni Salomolle anna täydellinen sydän pitämään sinun käskys, todistukses ja säätys, niin että hän ne kaikki tekis ja rakentais tämän asuinsian, jonka minä olen valmistanut."],[29,20,"Ja David sanoi kaikelle kansalle: kiittäkäät Herraa teidän Jumalaanne! ja kaikki kansa kiitti Herraa isäinsä Jumalaa, kumarsivat ja rukoilivat Herraa ja kuningasta,","Ja David sanoi kaikelle kansalle: kiittäkäät Herraa teidän Jumalaanne! ja kaikki kansa kiitti Herraa isäinsä Jumalaa, kumarsivat ja rukoilivat Herraa ja kuningasta,"],[29,21,"Ja he uhrasivat Herralle uhrin, ja toisena päivänä uhrasivat he polttouhrin Herralle, tuhannen mullia, tuhannen oinasta, tuhannen karitsaa, ja heidän juomauhrinsa, ja monta muuta uhria kaiken Israelin edessä.","Ja he uhrasivat Herralle uhrin, ja toisena päivänä uhrasivat he polttouhrin Herralle, tuhannen mullia, tuhannen oinasta, tuhannen karitsaa, ja heidän juomauhrinsa, ja monta muuta uhria kaiken Israelin edessä."],[29,22,"Ja he söivät ja joivat sinä päivänä sangen suurella ilolla Herran edessä, ja tekivät Salomon Davidin pojan toisen kerran kuninkaaksi ja voitelivat hänen Herralle hallitsiaksi ja Zadokin papiksi.","Ja he söivät ja joivat sinä päivänä sangen suurella ilolla Herran edessä, ja tekivät Salomon Davidin pojan toisen kerran kuninkaaksi ja voitelivat hänen Herralle hallitsiaksi ja Zadokin papiksi."],[29,23,"Ja niin Salomo istui Herran istuimelle kuninkaaksi isänsä Davidin siaan, ja oli onnellinen; ja koko Israel oli hänelle kuuliainen.","Ja niin Salomo istui Herran istuimelle kuninkaaksi isänsä Davidin siaan, ja oli onnellinen; ja koko Israel oli hänelle kuuliainen."],[29,24,"Niin myös kaikki päämiehet ja voimalliset, ja kaikki kuningas Davidin lapset antoivat itsensä kuningas Salomon alle.","Niin myös kaikki päämiehet ja voimalliset, ja kaikki kuningas Davidin lapset antoivat itsensä kuningas Salomon alle."],[29,25,"Ja Herra teki Salomon enemmin ja enemmin suuremmaksi kaiken Israelin edessä, ja antoi hänelle kuuluisan valtakunnan, jonkakaltaista ei yhdelläkään kuninkaalla Israelissa hänen edellänsä ole ollut.","Ja Herra teki Salomon enemmin ja enemmin suuremmaksi kaiken Israelin edessä, ja antoi hänelle kuuluisan valtakunnan, jonkakaltaista ei yhdelläkään kuninkaalla Israelissa hänen edellänsä ole ollut."],[29,26,"Ja niin oli David, Isain poika, koko Israelin kuningas.","Ja niin oli David, Isain poika, koko Israelin kuningas."],[29,27,"Mutta aika, jonka hän oli Israelin kuninkaana, oli neljäkymmentä ajastaikaa. Hebronissa hän hallitsi seitsemän ajastaikaa ja Jerusalemissa kolmeneljättäkymmentä.","Mutta aika, jonka hän oli Israelin kuninkaana, oli neljäkymmentä ajastaikaa. Hebronissa hän hallitsi seitsemän ajastaikaa ja Jerusalemissa kolmeneljättäkymmentä."],[29,28,"Ja hän kuoli hyvällä ijällä, ravittuna elämästä, rikkaudesta ja kunniasta; ja hänen poikansa Salomo tuli kuninkaaksi hänen siaansa.","Ja hän kuoli hyvällä ijällä, ravittuna elämästä, rikkaudesta ja kunniasta; ja hänen poikansa Salomo tuli kuninkaaksi hänen siaansa."],[29,29,"Mutta kuningas Davidin teot ensimäiset ja viimeiset, katso, ne ovat kirjoitetut näkiän Samuelin teoissa, ja prophetan Natanin teoissa, ja näkiän Gadin teoissa,","Mutta kuningas Davidin teot ensimäiset ja viimeiset, katso, ne ovat kirjoitetut näkiän Samuelin teoissa, ja prophetan Natanin teoissa, ja näkiän Gadin teoissa,"],[29,30,"Kaiken hänen valtakuntansa, väkevyytensä ja aikainsa kanssa, jotka hänen ja Israelin, ja kaikkein maan valtakuntain aikana kuluneet ovat.","Kaiken hänen valtakuntansa, väkevyytensä ja aikainsa kanssa, jotka hänen ja Israelin, ja kaikkein maan valtakuntain aikana kuluneet ovat."]]}};